pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: next item fills this bin exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here: prefer leaving a tight-but-usable remainder.
            let rem_after_next = post_residual - next_item_size;
            score -= 20.0 - (rem_after_next as f64).min(20.0);
            score += (rem_after_next as f64) * 0.15;
        } else {
            // Next item won't fit after this placement: penalize proportionally.
            let overflow = next_item_size as f64 - post_residual as f64;
            score += overflow * 0.35;
        }
        // Smooth penalty on absolute mismatch to lookahead demand.
        score += gap * 0.08;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // placing here uses scarce space efficiently.
    let rel = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += rel * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin gives a good fit
    // (i.e., this call's residual is full and existing fits are poor).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a tight fit, but below heavily
        // mismatched lookahead placements.
        score = 55.0 + (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can serve the next item too.
            if next_item_size + item_size <= bin_capacity {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size are pure waste -> heavy penalty proportional to their size.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    }
    // Residuals in the awkward mid-range (usable only by tiny items) get a
    // moderate penalty scaled by how deep into the stream we are.
    if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 25.0 * progress;
    }

    // Reward tight fits: near-exact fills are excellent.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if it cannot fit, the residual is dead space for the lookahead -> penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing
    // bins; opening new bins should be less attractive.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline is full capacity; apply pressure and
        // mean-residual coupling so we only open when existing bins are messy.
        score = bin_capacity as f64 + bin_pressure + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 90.0; // never open when a last-chance bin exists
        }
    } else {
        // Existing bins get slight preference as open_bins_count grows.
        score -= bin_pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 60.0;

    // Reward using bins with small residuals (best-fit flavor).
    score += bin_residual as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins whose residual deviates below the mean (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: bonus if post_residual can host the next item (keep bins usable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is dead space for the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.8;
    }

    // New-bin candidate: baseline moderate score; only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 120.0
            + open_bins_count as f64 * 2.0
            - (if next_item_size > 0 && item_size >= next_item_size { 10.0 } else { 0.0 });
        // If this bin is the only fitting bin, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that cannot fit the next item is dead space unless tiny.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward residual that exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Prefer bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it is chosen only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in reusable classes
    // (multiples of 10 / large chunks), penalize tiny unusable slivers.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer division class (0..10)
        let remainder = (pr % 10) as f64;
        // Penalize the ragged part of the residual (dead-space risk)
        score += remainder * 1.5;
        // Reward coarse classes: residuals that can host mid-size items
        if class >= 2 { score -= (class as f64) * 2.0; }
        if pr <= 5 { score += 25.0; }          // near-dead sliver
        if pr > 0 && pr < 10 { score += 15.0; } // unusable for most items
    } else {
        score -= 30.0; // perfect fit: zero waste, best outcome
    }

    // Lookahead: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly placement
            // extra reward if next item fits snugly in the new residual
            let snug = (post_residual - next_item_size) as f64;
            score -= (10.0 - (snug % 10.0)) * 0.5;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere here anyway; residual class matters less
            score += 3.0;
        } else {
            score += 10.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        let pressure = open_bins_count as f64 / 8.0;
        // small items: better to fill existing space; large items may justify a fresh bin
        let size_pull = (item_size as f64) * 0.3;
        score += 55.0 - size_pull - pressure * 10.0 - frag * 20.0;
        if item_size >= 60 { score -= 25.0; } // big items pair poorly with leftovers
    }

    // Stream maturity: late in stream, consolidate; early, allow exploration
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mild preference to spread load when many bins are open
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (low post_residual).
    score -= (post_residual as f64).powi(3) / (bin_capacity as f64).powi(2) * 2.0;

    // Aggressive 2-step lookahead: if the next item fits the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0 + (slack_after_next as f64).powi(2) / 100.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap that the next item cannot use (dead space).
        score += (next_item_size as f64 - post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Relative residual context: bins tighter than the mean are better fill targets.
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item relative to mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        let bonus = 25.0 * (pressure - mean_tight) + 10.0 * progress;
        score += bonus; // negative bonus makes new bin attractive when open bins are tight
    }

    // Mild penalty for wasting a very roomy bin on a small item.
    if item_size < 30 && bin_residual > 70 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor(); // 0..8 harmonic octile class
    // Reward tiny residuals (near-perfect fit), penalize mid-range dead space.
    score -= 18.0 * (1.0 - class / 8.0) * (1.0 - class / 8.0) * (pr / cap);

    // Integer-division thresholds: residuals that are exact multiples of small
    // denominators are reusable by future items.
    let res = post_residual;
    if res > 0 {
        if res % 10 == 0 { score -= 6.0; }
        else if res % 5 == 0 { score -= 3.0; }
        else if res % 25 == 0 { score -= 8.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize leaving a stranded mid residual
            if post_residual < 10 {
                score += 4.0; // tiny dead space, mildly bad
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64) / cap;
        // New bin is attractive when item is large and mean residual is small.
        let new_bin_score = cap - 40.0 * tightness
            - 10.0 * (mean_residual / cap)
            - 15.0 * progress
            - 2.0 * open_bins_count as f64;
        // Blend: keep base residual but apply new-bin evaluation.
        score = 0.5 * score + 0.5 * new_bin_score;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // reserve space for a growing trend
        }
    }

    // Mild global pressure: prefer filling bins when many are open.
    score -= 0.5 * open_bins_count as f64 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    // Tighter packing valued more as stream progresses
    score -= 0.9 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 + 2.0 * t * t);
    // Cubic dead-space penalty: small residuals late in stream are costly
    score += 0.35 * fit_ratio * fit_ratio * fit_ratio * cap * (0.5 + t);
    // Reward near-perfect fits smoothly
    score -= 6.0 * (1.0 - fit_ratio).powi(4);

    // Lookahead coupling: smooth interaction of post_residual with next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        // Penalize when next item neither fits nor fills bin (smooth quadratic)
        score += 1.2 * gap_norm * gap_norm * cap;
        // Reward when next item exactly fills post_residual (smooth Gaussian-like)
        score -= 8.0 * (-40.0 * gap_norm * gap_norm);
        // Late-stream lookahead weight
        score += 0.8 * t * (pr - nx.min(pr)) / cap * cap * 0.01;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * t;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by residual waste
        score += 0.15 * (fitting_bins_count as f64).ln() * fit_ratio * cap;
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev * cap;

    // Open bins pressure: with many open bins, favor consolidation
    let ob = open_bins_count as f64;
    score += 0.05 * ob * fit_ratio * cap * (0.5 + 0.5 * t);

    // New-bin candidate handling: empty bin gets smooth adaptive threshold
    if bin_residual == bin_capacity {
        let threshold = cap * (0.35 + 0.4 * t * t) + 0.2 * mean_residual * t;
        score = threshold + 0.3 * (1.0 - t) * cap;
        if fitting_bins_count == 1 {
            score += 25.0; // never open new bin if this is the only fitting one
        }
    }

    score
}

