    // Time horizon: early in stream, encourage opening new bins to diversify residuals;
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins late, reward early.
        score += 12.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If item is large and mean residual is small, new bin is attractive.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - mean_tight);
    } else {
        score -= 4.0 * progress;
    }

    // Many open bins: discourage spreading; prefer consolidating into existing bins.
    score += 1.5 * (open_bins_count as f64).sqrt().min(10.0);

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth polynomial base: penalize both large and tiny residuals,
    // with a sweet spot that shifts as the stream progresses.
    let sweet = 0.25 + 0.35 * progress;
    let base = post * (1.0 + 2.0 * (norm_post - sweet) * (norm_post - sweet));

    // Non-linear coupling of post_residual with stream progress.
    let coupling = post * (norm_post * (1.0 - norm_post)) * (1.0 - 2.0 * progress);

    let mut score = base + 4.0 * coupling;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= next_item_size as u64 { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64;
        score += fits_next * (-0.5 * gap / cap) - (1.0 - fits_next) * (1.0 + 3.0 * progress);
    }

    // Slight preference for consolidating into few bins when residuals are tight.
    score += 0.05 * (open_bins_count as f64) * norm_post;

    // Dead-space penalty grows with progress.
    score += progress * post * norm_post;

    // New-bin candidate: neutral-ish, mildly penalized early, allowed late.
    if bin_residual == bin_capacity {
        score += 8.0 - 12.0 * progress + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in low classes (small leftovers)
    // are good; high classes (large wasted space) are penalized superlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (harmonic classes of C/8)
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8
    let class_penalty: f64 = match class {
        0 => -30.0, // near-perfect fill
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,   // ~half-full leftover: mediocre
        5 => 10.0,
        6 => 16.0,
        7 => 24.0,
        _ => 34.0,  // almost untouched bin
    };
    score += class_penalty;

    // Modulo arithmetic: residuals that are multiples of common small item
    // sizes (mod 10 grid) are more likely reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            score += 5.0 + 0.1 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.05 * (bin_residual as f64);
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = item_size as f64 / cap;
        if tightness > 0.6 || fitting_bins_count == 0 {
            score -= 15.0 + 20.0 * tightness;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild preference for bins below mean residual (balance load across bins)
    score += 0.08 * (pr - mean_residual).max(0.0);

    // Slight reward for using bins later in their life (fewer lingering bins)
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny dead space: almost unusable for items >= 10 (or >= 1 generally).
            score += 60.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual <= 15 {
            // Marginal gap: risky, likely to strand future small items.
            score += 25.0 * (15.0 - post_residual as f64) / 5.0;
        } else if post_residual <= 25 {
            // Moderate gap: mildly undesirable.
            score += 8.0;
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0;
            } else if slack < 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            score += 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // no open bin offers a reasonable fit. Penalize it moderately so tight fits win,
    // but its raw post_residual (= capacity - item_size) is already large.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Early in the stream, opening bins is cheaper (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Slight tie-breaker: prefer bins whose residual deviates from the mean
    // in the direction of a tighter fit.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero dead space is the ideal outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 5.0;

    // 2-step lookahead: if the next item exactly fills the leftover space,
    // this placement is a chain-perfect fit — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits but imperfectly; mild reward proportional to how snug.
            let snug = (post_residual - next_item_size) as f64;
            score -= 50.0 / (1.0 + snug / 10.0);
        } else {
            // Next item cannot use the leftover: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // nearly full; placing here consolidates waste — reward slightly.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 300.0;
        // But if no open bin fits tightly, opening fresh is fine — soften the penalty
        // when the current item is large and would leave a very small post_residual.
        if item_size >= 60 {
            score -= 120.0;
        }
        // Lookahead: a fresh bin can host the current item AND the next one.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: as the stream nears its end, prefer filling
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 20.0 * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core with tighter coupling: reward snug fits nonlinearly.
    let snugness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * snugness * snugness;

    // Penalize post residuals that are too small to ever be useful again
    // (dead space below the minimum plausible item size).
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can also fit in the post-residual, reward
    // this placement (chaining items into the same bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for tight two-item packing.
            if post_residual - next_item_size < 10 {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // Post residual blocks the next item but is wasted: mild penalty.
            score += 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, growing with number of open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If other bins fit, discourage new bin unless fit is poor.
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Late in the stream, opening bins is more acceptable (avoid
        // cascading overflows into few bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Global residual balance: prefer bins whose residual is close to the
    // mean residual (keeps the pool of usable bins uniform).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation;

    // Mild preference for using fuller bins early (harmonic best-fit pressure).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * fill_ratio;

    // Time horizon: early on, be more selective (add small noise-free
    // regularization); late, pack greedily into fullest bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize post_residual, but with a non-linear (quadratic) waste term
    let mut score = pr + 30.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are increasingly rewarded
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * progress * tightness * tightness * tightness;

    // Interaction: large items deserve priority when residuals are scarce
    let scarcity = 1.0 / (1.0 + mean_residual / cap);
    score -= 25.0 * fit * fit * scarcity;

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for bin proliferation early in the stream
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible by small sizes (common item sizes) are more valuable.
    let r = post_residual;
    let mut class_bonus = 0.0;
    if r == 0 {
        class_bonus -= 30.0; // perfect fit, extremely desirable
    } else if r < 10 {
        class_bonus += 25.0; // dead space below minimum item size
    } else {
        // integer-division thresholds: how many "typical" small items still fit
        let slots = r / 10;
        class_bonus -= (slots as f64) * 1.5;
        // modulo harmonic: residual in a "friendly" class (multiples of 5, 20, 25)
        if r % 5 == 0 { class_bonus -= 4.0; }
        if r % 20 == 0 { class_bonus -= 3.0; }
        if r % 25 == 0 { class_bonus -= 3.0; }
        if r % 10 != 0 && r % 5 != 0 { class_bonus += 6.0; } // awkward class
    }
    score += class_bonus;

    // Penalize wasting a large residual on a small item (bad capacity fraction use)
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac < 0.35 && bin_residual > 60 {
        score += 12.0 * (1.0 - fill_frac);
    }

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when the item is huge or fit is poor
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        if tight > 0.85 {
            score -= 15.0; // big item, fresh bin is fine
        } else {
            score += 18.0 * (1.0 - tight); // discourage opening bins for small items
        }
    }

    // Lookahead coupling: if next item could exactly fill this bin's post residual,
    // reward the placement (harmonic pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // leftover won't serve the next item
    }

    // Stream progression: early on, be more willing to open bins (spread risk)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins with high mean residual: prefer consolidating into existing bins
    if open_bins_count > 4 && mean_residual > 40.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host even the
    // smallest plausible future item are wasted; penalize them extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 20.0 / (1.0 + tightness);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - slack / 100.0);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Pressure proportional to number of open bins: discourage proliferation.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0 + 1.2 * open_bins_count as f64;
        // But if placing in an open bin leaves a useless tiny gap, new bin wins.
        if post_residual == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Mild stream-progression term: early on, be slightly more conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress;

    // Prefer bins whose residual is above the mean (save tight bins for tight items).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.05 * (residual_f - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - residual_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect closure: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: next item exactly fills the leftover space.
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here: mild reward, scaled by tightness.
            let tightness = (next_item_size as f64) / (post_residual as f64);
            score -= 50.0 + 200.0 * tightness;
        } else {
            // Next item cannot fit: leftover space is likely dead space.
            // Penalize more when the gap is small (worst dead space) relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0 + 2.0 * gap;
        }
    }

    // Favor bins whose residual is already small relative to the fleet average
    // (concentrate waste in few bins rather than spreading it).
    let dev = (post_residual as f64) - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has huge residual, so the base
    // score already penalizes it. Add a mild extra penalty unless the stream
    // is early (building initial bins) or many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 60.0 * progress;
        // If no open bin fits (fitting_bins_count==0 means only the new bin fits),
        // opening is fine: cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = post / cap;
    score -= 30.0 * (-fit_ratio * 8.0).exp();

    // Penalize creating dead space that likely can't be filled later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post > 0.0 && post < 10.0 {
        score -= 12.0 * (1.0 - progress); // small dead space early is cheap, late is fine too
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let next_fit_gap = post - next_item_size as f64;
        score -= 20.0 * (-next_fit_gap / 15.0).exp();
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0; // next item won't fit here
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keep larger holes available).
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Crowding: with many open bins, prefer filling existing ones over new bins.
    let new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin {
        score += 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count > 0 {
            score += 10.0; // strongly prefer existing bins when any fit
        }
    }

    // Time horizon: early on, be pickier about wasted space.
    score += post * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual and item size
    let pr_norm = post_residual as f64 / cap;
    let item_norm = item_size as f64 / cap;

    // Non-linear polynomial coupling: penalize large post-residual quadratically as stream progresses
    score += progress * (pr_norm * pr_norm) * 40.0;

    // Cubic dead-space term: residuals that are small-but-unusable are heavily punished late
    score -= (pr_norm * pr_norm * pr_norm) * 30.0 * (1.0 - progress);

    // Interaction: item size vs residual fit quality
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // Lookahead coupling: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nxt = next_item_size as f64 / cap;
        score -= (1.0 - (post_residual as f64 - next_item_size as f64) / cap) * 15.0 * nxt;
    }

    // Last-chance bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress + item_norm * 10.0;
    }

    // Mean residual dispersion term
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small usable" classes (<= 10) are excellent; large odd leftovers are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fill
    } else if pr <= 10 {
        score -= 20.0;
    } else {
        // penalize leftovers that cannot host mid-range items (10..80)
        if pr < 10 {
            score += 0.0;
        }
        // class penalty grows with unusable fraction
        let unusable = if pr < 10 { 0.0 } else if pr > 80 { 1.0 } else { 0.0 };
        score += 15.0 * unusable;
    }

    // Integer-division thresholds: can post_residual host the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // harmonic match: leftover divisible-ish by next item
            score -= 10.0;
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            score += 8.0; // leftover too small for lookahead -> dead space risk
        }
    }

    // Capacity fraction classes of the bin's fill level
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let quarter = (fill_frac * 4.0).floor(); // 0..3
    score -= 6.0 * quarter; // prefer fuller bins (best-fit bias)

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // no open bin fits well, but allow it when open bins are very fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 15.0; // big lookahead item pairs well with a fresh bin
        }
    }

    // Fragmentation pressure: if mean residual is high, prefer consolidating
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Modulo-class tiebreak on item size vs residual (harmonic pairing)
    if item_size > 0 && (bin_residual % item_size.max(1)) < 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Dead space: residual too small for the smallest item (>=1).
            score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
        }
        // Reward tight fits (small but usable residual).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open.
    score += 2.5 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that almost-but-not-quite fits the next item.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= 100 {
        score += 8.0;
    }

    // New-bin candidate (residual == capacity): penalize slightly so we only
    // open a new bin when no open bin gives a decent fit; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress;
        // Opening is attractive if the item is large (small post residual anyway).
        score -= 0.3 * item_size as f64;
    }

    // Mild penalty when this bin's residual is far from the mean (imbalance).
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item fits snugly into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here after placement
        score += 25.0;
    }

    // Prefer bins whose residual is below mean (tighter bins get used first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving large dead space that nothing (avg item) can use
    if post_residual < 10 {
        score -= 80.0; // nearly perfect fill
    } else if post_residual as f64 > mean_residual * 1.5 {
        score += 15.0;
    }

    // Late in stream: consolidate aggressively, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit post residual but fits mean residual elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            // next item can still fit here; slight bonus scaled by leftover after next
            let post2 = post_residual - next_item_size;
            score -= 15.0 * (1.0 - post2 as f64 / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportionally to how much next exceeds
            let excess = (next_item_size - post_residual) as f64;
            score += 0.15 * excess;
        }
    }

    // Penalize creating small unusable gaps that few items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    }

    // Prefer filling bins with larger residual when mean residual is high (dispersion control).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Early in stream: be conservative, prefer new bins less; later: consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // New empty bin candidate: penalize mildly unless item is huge or few fitting bins.
    if bin_residual == bin_capacity {
        let base = 35.0;
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        score += base - big_item_bonus - scarcity_bonus;
        // Late in stream, opening new bins is more acceptable.
        score -= 15.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly * (1.0 + progress);

    // Penalize large dead space more as stream progresses (less time to fill it)
    score += 8.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: subtract when post_residual is small
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward if next item fits into the resulting post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 3.0 * norm_next * progress;
    }

    // Last-chance bonus: strongly favor using a bin when few can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * norm_item;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: make it attractive only for large items with poor fits
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += 20.0 * (1.0 - norm_item);
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space by
    // capacity fractions (integer division thresholds).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;   // 25
    let half = bin_capacity / 2;      // 50
    let three_quarter = 3 * bin_capacity / 4; // 75

    // Penalize residuals that fall into "awkward" harmonic classes:
    // tiny slivers (0..=10) are dead space; mid classes are reusable.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, best outcome
    } else if post_residual <= 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < quarter {
        score += 8.0;
    } else if post_residual < half {
        score -= 5.0;  // still useful for medium items
    } else {
        score -= 12.0; // large residual remains, very reusable
    }

    // Modulo arithmetic: residuals congruent to common item sizes mod 10
    // are more likely to be filled exactly by future items.
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m >= 8 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) / cap * 15.0;
        } else {
            // next item won't fit here; penalize more if this was last-chance bin
            score += 3.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are fragmented or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs() / cap;
        score += 14.0 + 20.0 * fragmentation - 10.0 * progress;
        // large items justify a fresh bin more often
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild preference to pack into bins with residuals close to item size
    // (tight fit reward), scaled by stream progress.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Slight tie-break noise-free ordering by bin index proxy via mean residual
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are
    // not necessarily dead, but gaps below typical item sizes are hard to fill.
    // Penalize post_residual in the "unusable small gap" band harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver: nearly dead space
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // The gap left cannot host the next item: mild extra penalty.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; the new-bin candidate has bin_residual == bin_capacity.
    let new_bin_penalty = 12.0 + 1.5 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Slight preference for filling bins that are already relatively full
    // (below-mean residual means this bin is emptier than average).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream tightening: as the stream progresses, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect two-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Reward when the next item can also fit into this bin's post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        // Penalize creating residual that the next item cannot use.
        score += 8.0;
    }

    // Penalize residuals relative to the mean residual: creating far-less-than-average
    // residual (tight fit) is good; leaving much more than average wastes space.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins could fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    // Mild preference early in the stream for keeping bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 0.6 * fit_ratio * (post_residual as f64);

    // Penalize large dead space quadratically when it can't fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // next item can chain into this bin: good
        } else {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.08 * waste * waste;
        }
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so we don't open bins frivolously.
        score += 8.0;
        // More open bins => prefer filling existing ones.
        score += 1.5 * open_bins_count as f64;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
        // If the new bin could host the next item too, slightly more attractive early.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (1.0 - progress);
        }
    }

    // Favor bins with below-mean residual (they are "tighter" and worth filling).
    if !is_new_bin {
        score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild reward for high occupancy of the chosen bin.
    score -= 0.02 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;
    let br = bin_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: residual penalty grows with progress,
    // dead space (small post_residual) penalized more late in the stream.
    let coupling = pr * pr * (0.5 + progress) - pr * progress * 0.3;
    score += 20.0 * coupling;

    // Smooth fill-quality term: reward tight fits via (1 - pr)^k shaping
    score -= 8.0 * (1.0 - pr).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64 / bin_capacity as f64;
        if next_item_size <= post_residual {
            score -= 6.0 * nx * (1.0 - pr) * (0.5 + progress);
        } else {
            score += 4.0 * nx * pr * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + 0.7 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln() * pr;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    score += 0.15 * (post_residual as f64 - mean_residual) * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 12.0 - 10.0 * waste * waste;
        if fitting_bins_count == 1 {
            score += 25.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes (<=20) are nearly perfect; reward them.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit
    } else if r <= 10 {
        score -= 25.0;
    } else if r <= 20 {
        score -= 12.0;
    } else if r <= 30 {
        score += 5.0;
    } else {
        score += 15.0;
    }

    // Modulo-class coupling: leftover that could pair with the lookahead item
    // is valuable. Reward when post_residual exactly or nearly matches
    // next_item_size (k=2 lookahead harmony).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 12.0;
            } else {
                score += (slack as f64) * 0.35;
            }
        } else {
            // leftover too small for next item: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Integer-division thresholds on capacity fractions: bins whose fill
    // crosses half-capacity are "committed" — prefer filling them further.
    let filled = bin_capacity - bin_residual;
    if filled >= bin_capacity / 2 && filled < bin_capacity * 3 / 4 {
        score -= 8.0;
    } else if filled < bin_capacity / 4 {
        score += 10.0; // lightly filled bin: deprioritize unless tight fit
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= bin_capacity * 3 / 4 {
            score -= 55.0; // big item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean-residual alignment: prefer bins near the mean (keeps bin profile
    // homogeneous, easier to pack future items).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Small tie-breaker on exact residue modulo classes to stabilize choice.
    score += (post_residual % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps too small for typical items (1..=100 range) are dead space.
    // A residual below ~20 is nearly unusable; penalize sharply with a
    // non-linear ramp as the gap shrinks toward zero.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 20.0 {
        // ramp: pr=20 -> 0, pr=1 -> ~38 (harsh penalty for near-full bins)
        score += (20.0 - pr) * (20.0 - pr) / 10.0;
    }
    // Exact fit is gold: strong reward.
    if pr == 0.0 {
        score -= 25.0;
    }
    // Tiny-but-nonzero gap is the worst outcome: extra crushing penalty.
    if pr > 0.0 && pr < 5.0 {
        score += 15.0;
    }

    // --- Prefer bins whose residual tightly matches the item ---
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // --- Open bins pressure: discourage opening/spreading when many bins exist ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += bin_pressure * 0.4 * (0.5 + progress);

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- Lookahead: reward if the next item fits the post residual ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit in leftover: mild penalty
        score += 3.0;
    }

    // --- New bin candidate: only attractive if no open bin fits well ---
    if bin_residual == bin_capacity {
        // neutral-ish baseline; fitting_bins_count pressure decides
        if fitting_bins_count > 0 {
            score += 8.0 + (fitting_bins_count as f64) * 0.5;
        } else {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 40.0 * fit_ratio;
    }

    // Reward tight waste (post_residual very small).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        }
        // Penalize dead space that the next item cannot use.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize residuals far below mean (unusable slivers).
    if (post_residual as f64) < mean_residual * 0.4 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: generally discouraged, but acceptable when the item
    // is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size > 70;
        let no_fitting_others = fitting_bins_count == 0;
        if large_item && no_fitting_others {
            score -= 15.0; // allow opening for large items with no alternatives
        } else {
            score += 45.0; // discourage opening new bins otherwise
        }
    }

    // Mild pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score;

    if is_new_bin {
        // Cost of opening a fresh bin: the residual we lock away.
        score = (cap - item) * 0.9;
        // No existing bin fits: opening is essentially forced.
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // Only prefer a new bin if existing fits would be very wasteful.
            let waste_threshold = cap * 0.5;
            if post > waste_threshold {
                score -= (post - waste_threshold) * 0.3;
            } else {
                score += 12.0;
            }
        }
        // Lookahead synergy: next item can join this fresh bin.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 14.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += t * 10.0;
    } else {
        // Base: prefer minimal leftover space.
        score = post;
        // Reward high fill ratio (tight packing).
        let fill = item / resid.max(1.0);
        score -= fill * 35.0;
        // Penalize squandering a large residual on a small item.
        if post > item {
            score += (post - item) * 0.15;
        }
        // Lookahead: if the next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= post {
                score -= 18.0 * (1.0 - (post - nxt) / cap);
            } else if post < 10.0 {
                // Bin is nearly closed; acceptable even if next item doesn't fit.
                score += 3.0;
            }
        }
        // Last-chance bin: strongly favor using the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 22.0;
        }
        // Dead-space penalty grows quadratically with unusable leftover.
        score += post * post / cap * 0.2;
        // Mild global pressure: when many bins are open, prefer consolidation.
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
        // Deviation from mean residual: prefer bins near the mean (keeps pool uniform).
        score += (post - mean_residual).abs() * 0.08;
        // Time horizon: early on, be slightly greedy for tight fits; later, be conservative.
        score *= 1.0 + 0.15 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-fit waste, with a convex (quadratic) penalty
    // so small residuals are strongly favored over medium ones.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth non-linear coupling with stream progress: waste matters more
    // later in the stream (less future to amortize it), scaled quadratically.
    let progress_coupling = (post / cap) * (progress * progress) * cap * 0.35;
    score += progress_coupling;

    // Interaction: reward bins whose residual is tightly coupled to item size
    // (near-perfect fill), via a smooth kernel on relative fit ratio.
    let fit_ratio = item / residual.max(1.0);
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 - (fit_ratio - 1.0).powi(2).min(1.0));

    // Lookahead coupling: if the next item fits the post-residual smoothly,
    // reward; penalize when next item is near-miss (creates dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // smooth reward decaying with the leftover after next item
            let leftover = gap;
            score -= 4.0 * (1.0 - leftover / cap) - 2.0 * (leftover / cap);
        } else {
            // near-miss: penalize proportionally to how much it misses
            score += 0.06 * (-gap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // unless post-residual is huge (would waste a nearly full bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // more acceptable late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) / ((open_bins_count as f64) + 3.0);
        score = cap * 0.55 + 0.3 * post - fragmentation * cap * (0.25 + 0.45 * progress);
        // If the item is large relative to capacity, opening fresh is cheap.
        score -= 0.2 * (item / cap) * cap * progress;
        // If next item is large too, a fresh bin keeps flexibility.
        if next_item_size > 0 {
            score -= 0.1 * (next_item_size as f64 / cap) * cap;
        }
    }

    // Mild penalty when this bin's residual is far above mean residual
    // (keeps a balanced family of bins for future items).
    score += 0.05 * ((residual - mean_residual) / cap).abs() * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items 1..100 -> capacity fractions.
    // Class boundaries at multiples of 25 (quarters of capacity).
    let quarter = bin_capacity / 4;
    let post_class = post_residual / quarter; // 0..4
    let item_class = item_size / quarter;

    // Reward placements whose post_residual falls into a "reusable" class:
    // residual in [25..50] or [50..75] tends to accept mid-size items later.
    match post_class {
        1 => score -= 12.0,                 // 25..49 residual: very reusable
        2 => score -= 18.0,                 // 50..74 residual: highly reusable
        3 => score -= 6.0,                  // 75..99 residual: only tiny items fit
        _ => {}                              // 0: perfect fit (already low score)
    }

    // Perfect-fit bonus: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Dead space below min item size (interface allows items >= 1, so
        // penalize only very small unusable slivers proportionally).
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (harmonic chain of two perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward by how much slack remains after both.
            let two_step = post_residual - next_item_size;
            score -= 10.0 + (two_step as f64).min(20.0) * 0.5;
        } else {
            // Next item will NOT fit here: penalize if post_residual is
            // large enough that we "waste" a reusable class.
            if post_residual >= next_item_size / 2 {
                score += 8.0;
            }
        }
    }

    // Last-chance logic: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: brand-new empty bin has bin_residual == bin_capacity.
    // Prefer it only when item is huge and no open bin offers good reuse;
    // otherwise penalize opening a new bin (keep packing into open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Huge items (> 3/4 capacity) justify a fresh bin; otherwise discourage.
        if item_size > bin_capacity * 3 / 4 {
            score -= 5.0 + 10.0 * progress;
        } else {
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — prefer consuming tight bins first (best-fit spirit).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let deviation = (res_f - mean_residual) / mean_residual;
        score += deviation * 8.0; // below mean => negative => favored
    }

    // Modulo harmonic touch: post_residual divisible by 10 aligns with
    // common item sizes (multiples of 10), making future fits likely.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division threshold: penalize leaving residual in the awkward
    // (quarter, half) band that few item classes can use efficiently.
    if post_class == 0 && post_residual > 0 {
        score += 4.0; // tiny sliver in (0, quarter)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 30 {
            score += 5.0;
        } else {
            // large gaps are reusable; mild reward proportional to size
            score -= (post_residual as f64 - 30.0) * 0.05;
        }
    } else {
        score -= 60.0; // perfect fit: strongly reward closing the bin
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that cannot fit the next item but is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 30 {
        score += 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // have poor fits (large mean residual spread) or many bins are open.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (best-fit core).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the
    // post residual (perfect chaining), mild reward when it fits, penalty otherwise.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: penalize proportional dead space
            score += 8.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64).min(1.0));
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that no plausible item can use,
    // unless the lookahead item exactly consumes it.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else {
            score += 25.0;
        }
    }

    // Lookahead synergy: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.2 * next_item_size as f64;
        } else {
            // Dead space relative to the next item's needs.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin alternative implicitly).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = 1.0 - fill_ratio;
        // Penalize opening a bin mildly; relax when many bins are open or item is huge.
        score = 40.0 + 30.0 * progress - 25.0 * item_size as f64 / bin_capacity as f64
            - 0.3 * open_bins_count as f64 * poor_fit;
        // If an existing bin is a great fit, discourage the new bin strongly.
        if fill_ratio > 0.8 {
            score += 60.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 15.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins that
    // reduce fragmentation by consuming more of the average slack.
    score -= 0.1 * mean_residual * fill_ratio;

    // Mild reward for using bins with larger residuals when few bins are open
    // (keeps small residual bins for small future items).
    if open_bins_count <= 3 {
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual.max(0.0);

    // Base: reward tight fits (small post_residual), normalized.
    let mut score = pr / cap;

    // Non-linear polynomial coupling: post_residual interacts with stream progress.
    // Later in the stream, small residuals become more valuable (harder to fill later),
    // so we penalize residual more aggressively as progress grows.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) * 2.0
        + pr_norm * it / cap * (1.0 - progress);
    score += coupling;

    // Penalize bins whose residual deviates strongly from mean residual
    // (prefer balanced residual landscape), weighted smoothly.
    let dev = (bin_residual as f64 - mean_r) / cap;
    score += 0.15 * dev * dev;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let tight_next = (nxt - pr).abs() / cap;
        score -= fits_next * (0.6 - 0.4 * tight_next);
        // If next item won't fit here, mildly penalize leaving a gap close to next size.
        score += (1.0 - fits_next) * (nxt / cap) * 0.1 * pr_norm;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Many open bins: encourage consolidation (prefer existing bins over new ones).
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += open_norm * 0.3 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so early (waste of capacity)
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 0.4 * (fitting_bins_count as f64).sqrt();
        }
        // Opening a bin is more attractive if the item is large (few future fit options).
        score -= (it / cap) * 0.7;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: residue classes modulo 10 and 25.
    let post = post_residual;
    let class10 = (post % 10) as f64;
    let class25 = (post % 25) as f64;
    // Penalize residuals whose harmonic class is "unusable" (small odd remainders).
    if post > 0 && post < 10 {
        score += 40.0 - class10 * 4.0; // tiny dead space heavily penalized
    }
    if class25 == 0.0 && post > 0 {
        score -= 15.0; // exact quarter-capacity harmonics are reusable
    }
    if post % 50 == 0 && post > 0 {
        score -= 10.0; // half-capacity harmonic
    }

    // Integer-division thresholds: post_residual bucket by quotient of capacity.
    let quot = post / (bin_capacity / 4).max(1);
    score -= match quot {
        0 => 0.0,
        1 => 8.0,
        2 => 14.0,
        3 => 20.0,
        _ => 25.0,
    };

    // Lookahead coupling: reward bins whose leftover matches the next item's harmonic class.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post >= nxt {
            // Next item can also fit here: reward proportional to match tightness.
            let tight = (post - nxt) as f64;
            score -= 12.0 - tight.min(12.0) * 0.5;
            if post % nxt == 0 && post > nxt {
                score -= 10.0; // perfect harmonic chain
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += (nxt - post) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should win only when fits are poor.
    if bin_residual == bin_capacity {
        // Base new-bin score: neutral-ish, scaled by how many bins could fit.
        score = cap * 0.5 + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large-then-large favors fresh bin
        }
        score += progress * 10.0; // late in stream, prefer consolidation
        score -= mean_residual.min(50.0) * 0.2; // if open bins are roomy, opening is cheaper to justify... inverted: roomy bins mean new bin less needed
        score += mean_residual.min(50.0) * 0.4;
        return score;
    }

    // Tightness reward: near-exact fill.
    let fill_frac = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill_frac * 20.0;

    // Prefer placing into bins with below-mean residual (balance leftovers).
    score += ((post as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define "useful" as >= typical small item (10)
    // or large enough to fit the lookahead item.
    let lookahead_fits = next_item_size > 0 && next_item_size <= post_residual;
    if post_residual > 0 && post_residual < 10 && !lookahead_fits {
        // Unusable sliver: dead space forever.
        score += 60.0 + 0.5 * (post_residual as f64);
    } else if post_residual == 0 {
        // Perfect closure — strongly reward.
        score -= 40.0;
    } else if lookahead_fits {
        // Residual can still host the next item: keep this bin attractive.
        score -= 12.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fill_ratio * fill_ratio;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.1 * item_size as f64;
    }

    // Open-bin pressure: when many bins are open, prefer packing into existing
    // bins (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 6.0 * open_bins_count as f64 + 15.0 * progress;
        // But if the item fits nowhere tightly and mean residual is low,
        // opening a fresh bin may be better — soften slightly.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Mild global pressure to consolidate into fewer bins.
        score += 0.05 * open_bins_count as f64;
    }

    // Alignment bonus: if post_residual exactly matches next item, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits in general: reward small post_residual nonlinearly.
    score -= 60.0 / (1.0 + post_residual as f64);

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect 2-item packing -> massive reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // next item fits inside leftover: mild reward, scaled by tightness
            let slack = post_residual - next_item_size;
            score -= 40.0 / (1.0 + slack as f64);
        } else {
            // next item won't fit in leftover: penalize large dead space
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: bins with residual below mean are "tighter"
    // and should be preferred targets for filling.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin (only fitting bin): strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no decent fit exists.
    // Penalize opening a new bin, more so early in the stream and when
    // many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 150.0 + 8.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is less wasteful.
        open_penalty -= 0.8 * item_size as f64;
        // If the next item is small, a fresh bin can host both: reduce penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            open_penalty -= 50.0;
        }
        score += open_penalty * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: penalize if the next item fits in post_residual (wasting a good residual),
    // reward if next item needs a bin and this residual would be dead space otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            // next item could reuse this residual -> mild penalty for consuming it now
            score += 6.0 * (nx / bin_capacity as f64);
        } else {
            // residual after placement is likely dead space for the next item
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 10.0 * dead * dead;
            // small reward if the next item nearly fits (residual is close but insufficient)
            let gap = nx - post_residual as f64;
            if gap <= 10.0 {
                score -= 4.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits even more
        score -= 3.0 * (fitting_bins_count.min(8) as f64) * tightness;
    }

    // New-bin candidate: opening a new bin is only attractive early in the stream
    // or when no open bin fits well (large post_residual on existing bins).
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - post_residual as f64).max(0.0);
        // penalize new bin late in the stream; reward when mean residual is small
        let new_bin_score = 40.0 + 30.0 * progress - 0.5 * mean_residual;
        score = score.max(new_bin_score) - 0.0;
        score += new_bin_score - post_residual as f64; // override base for new bin
        let _ = avg_waste;
    }

    // Slight preference to fill bins with larger residuals when many bins are open
    // (consolidation): favor bins below mean residual to drain outlier bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Mild penalty for very small placements into large residuals (fragmentation risk)
    if (item_size as f64) < 0.35 * bin_residual as f64 && post_residual > 40 {
        score += 5.0;
    }

    // Tiny exploration jitter-free regularizer to break ties deterministically
    score += (bin_residual as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial base: reward tight fits (small x), punish dead space super-linearly.
    let mut score = x.powf(1.0 + 1.5 * progress) * (10.0 + 20.0 * progress);

    // Smooth coupling: tightness bonus amplified as stream progresses.
    let tightness = (1.0 - x).powi(3);
    score -= 6.0 * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from mean residual (fragmentation avoidance).
    let dev = (pr - mean_residual) / cap;
    score += 2.5 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress + 0.3);
    }

    // Lookahead coupling: if next item fits exactly in post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 5.0 * (1.0 - gap).powi(2) * (1.0 - progress);
        // penalize leaving residual that neither fits next item nor is near zero
        score += 1.5 * gap * (1.0 - tightness);
    }

    // Mild penalty for many open bins to discourage sprawl early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate (empty bin): penalize unless residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (1.0 - progress) - 0.02 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // coarse buckets via integer division (residual / 10). Small classes
    // (dead space) are penalized extra; large classes are fine.
    let post_class = post_residual / 10;
    match post_class {
        0 => score += 22.0,                       // near-perfect fit
        1 => score += 14.0,                       // 10..19 left: poor for future items
        2 => score += 8.0,                        // 20..29 left
        3 => score += 4.0,                        // 30..39 left
        _ => {}                                   // 40+: usable space
    }

    // Harmonic compatibility: does the leftover pair well with the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportionality of the match.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
            // Exact harmonic match (next item consumes a clean fraction class)
            if post_residual % next_item_size.max(1) == 0 && next_item_size >= 10 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportional to gap class.
            let gap = next_item_size - post_residual;
            score += (gap / 10) as f64 * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        // Penalize opening new bins mildly; escalate when mean residual is still large.
        score += 30.0 - 10.0 * progress - 4.0 * (mean_residual / bin_capacity as f64);
        let _ = crowding;
        // If the item fits with big leftover in a new bin and nothing else fits well,
        // this stays competitive via the base post_residual term.
    }

    // Prefer tighter bins overall (residual before placement close to item).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness);

    // Mild diversity bonus: avoid leaving many bins in the same residual class.
    let mean_class = (mean_residual as u32 / 10) as f64;
    score += 0.15 * (post_class as f64 - mean_class).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable" small gap
    // band (1..=12) is heavily penalized since nothing can likely fill it.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness bonus: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Reward leaving residuals that match the lookahead item if it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad gaps
    // or few fitting bins exist and mean residual is low.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64
            + (mean_residual < item_size as f64) as i32 as f64;
        score = 55.0 - 30.0 * pressure - 0.5 * open_bins_count as f64;
        if post_residual >= 20 {
            score -= 10.0; // fresh bin leaves a usable gap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item fits the remaining residual exactly
    // or tightly (post_residual - next_item_size small and non-negative).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 800.0; // chain of two near-perfect placements
        } else if gap > 0 {
            score -= 400.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted space
            score += 0.5 * (-gap) as f64;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual after placement stays close to (but below) the mean,
    // penalizing bins that become outliers of dead space.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 600.0;
    }

    // New-bin candidate (empty bin) should only win when no open bin fits well:
    // penalize the fresh bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 250.0;
        // late in the stream, be even more reluctant to open new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Tightness bonus: the smaller the residual consumed fraction, the better.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 100.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is already the base; add a convexity
    // penalty on waste so small residuals are strongly preferred.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this bin strongly; if post-residual is smaller than the next
    // item but nonzero, the leftover is likely dead space -> penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            score -= 0.5 * (pr - nxt).min(20.0);
        } else if post_residual > 0 {
            score += 0.25 * pr;
        }
        // If next item fits only here (this residual is uniquely sized), extra reward.
        if next_item_size == post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Time horizon: late in the stream, consolidate aggressively into
    // existing bins; early, allow more freedom.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.6 * progress;

    // Global state: many open bins with high mean residual -> encourage
    // filling existing bins rather than spreading.
    if open_bins_count > 2 {
        let fill_bonus = (mean_residual / bin_capacity as f64) * open_bins_count as f64;
        score -= 0.15 * fill_bonus;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin fits well (large item, few fitting bins) or the
    // stream is early and future items may need clean space.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base cost of a new bin: high, but discounted early in the stream
        // and for large items with no good alternative.
        score = 30.0
            - 8.0 * early
            - 12.0 * desperation
            + 10.0 * item_frac * (1.0 - desperation);
        // If many open bins already fit, a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear emphasis on small residuals.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - norm_pr) * 4.0);

    // Smooth polynomial coupling: penalize large residuals more as stream progresses.
    let t = progress;
    score += norm_pr * norm_pr * (0.5 + 2.0 * t * t) * cap * 0.01;

    // Dead-space term: cubic penalty when residual can't fit typical items.
    let dead = if pr < next_item_size as f64 && next_item_size > 0 { 1.0 } else { 0.0 };
    score += dead * norm_pr * norm_pr * norm_pr * 10.0;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead synergy: reward leaving room close to the next item size.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= (1.0 - diff) * (1.0 - diff) * 5.0 * (1.0 - t);
    }

    // New-bin candidate: mildly discourage early, encourage when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        score += 8.0 - 6.0 * t - 4.0 * frag * frag;
    }

    // Slight preference for bins below mean residual (balance conservation).
    score += (pr - mean_residual) * 0.02 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common item granularities) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are harmonically compatible with future items.
        let mut harmony: f64 = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        score -= harmony;
    } else {
        // Perfect fit is the best outcome.
        score -= 60.0;
    }

    // Dead-space penalty: very small leftovers are nearly unusable.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score += slack as f64 * 0.5;
            if slack < 10 { score -= 8.0; }
        } else {
            // Next item cannot follow here; mild penalty scaled by overflow.
            score += (next_item_size - pr).min(30) as f64 * 0.3;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin offers a decent fit, or when open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 70.0 + fragmentation * 0.5;
        if fitting_bins_count == 0 { score -= 50.0; }
        if open_bins_count == 0 { score -= 60.0; }
        // Late in the stream, avoid spawning bins for marginal reasons.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer bins below the mean residual (tighter, more filled bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Small structural tiebreak using integer division class of item size.
    score += (item_size / 20) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let min_item = 1u32;
    let dead_threshold = min_item + 9; // gaps < 10 are effectively dead space
    if post_residual < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    }

    // Reward tight fits: small relative slack.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 25.0;

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize more when many bins are already open.
        score += 15.0 + (open_bins_count as f64) * 2.0;
        // But if the new bin would fit the lookahead item nicely, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let slack = bin_capacity - next_item_size;
            if slack < dead_threshold {
                score -= 8.0;
            }
        }
    } else {
        score -= 3.0;
    }

    // Lookahead coupling: penalize leaving a gap that neither the next item
    // nor any small item can use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 5.0; // gap too small for the known next item
        } else if post_residual == next_item_size {
            score -= 10.0; // gap exactly fits the next item: excellent
        }
    }

    // Mild mean-residual coupling: bins far below mean residual are less attractive.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Early-stream flexibility: keep bins openable early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // --- 2-step lookahead: does the NEXT item fit into the leftover space? ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Great: next item can slot in here -> strong reward.
            // Reward scales with how well the pair fills the bin.
            let pair_fill = (item_size as f64 + next) / bin_capacity as f64;
            score -= 25.0 * pair_fill.min(1.0);
            // Extra bonus for near-perfect two-item packing.
            let pair_slack = (post - next) / bin_capacity as f64;
            score -= 20.0 * (1.0 - pair_slack) * (1.0 - pair_slack) * 0.25;
        } else {
            // Next item won't fit here -> penalize leaving awkward dead space,
            // worse if the dead space is small-but-unusable (worst case).
            let dead = post / bin_capacity as f64;
            if dead > 0.0 && dead < 0.15 {
                score += 35.0 * (0.15 - dead); // small unusable gap
            } else {
                score += 8.0 * dead; // large gap still somewhat reusable
            }
            // If next item is large, opening a fresh bin for the pair is attractive.
            if next > 40.0 {
                score += 10.0;
            }
        }
    } else {
        // Last item: minimize residual as much as possible.
        score -= 15.0 * (1.0 - tightness);
    }

    // --- Relative-to-mean coupling: bins with residual below mean are "richer" fills ---
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        score += 6.0 * rel.clamp(-1.5, 1.5);
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate logic: only open a new bin when open bins are poor fits ---
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline plus mild penalty so it's used only when needed.
        score = bin_capacity as f64 * 0.5;
        if next_item_size > 0 {
            // A fresh bin always fits the next item; slight bonus when current
            // placement elsewhere would strand the next item.
            score -= 5.0;
        }
        // Early in stream, slightly prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress);
        // If many open bins already, a fresh bin is fine (they're fragmented anyway).
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // --- Progress-based consolidation pressure: late in stream, pack tighter ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize small dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by how badly
        score += 5.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
    }

    // Last-chance bin bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Bin consolidation pressure: more open bins -> favor using existing ones
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: empty bin gets a time-dependent penalty
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early stream: open bins freely; late stream: strongly prefer filling existing bins
        score += 20.0 + 80.0 * progress;
        // but if no open bin fits well, allow opening (post_residual == capacity here)
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
    }

    // Mild time drift: as stream progresses, tighten up
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post_residual, with non-linear shrinkage of large gaps.
    let mut score = post * (1.0 + 0.9 * post_norm * post_norm);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier).
    let tightness = (1.0 - post_norm).clamp(0.0, 1.0);
    let coupling = tightness * tightness * (3.0 - 2.0 * tightness); // smoothstep
    score -= 18.0 * coupling * (0.35 + 0.65 * progress);

    // Penalize bins whose residual deviates from the mean residual (imbalance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + progress);

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Slight penalty for spreading across many open bins.
    score += 0.35 * open_bins_count as f64;

    // Lookahead: reward leaving space usable by the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_kernel = (-gap / cap).exp();
        score -= 10.0 * fit_kernel * (0.4 + 0.6 * (1.0 - progress));
        // Penalize post_residual that is unusably small relative to next item.
        if post < nxt {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: neutral baseline with mild progress-dependent caution.
    if bin_residual == bin_capacity {
        score = cap * (1.05 - 0.25 * progress) + 0.35 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: residues modulo 10 define "dead space classes".
    let post_class = (post_residual % 10) as f64;
    // Small residues (<10) are nearly unusable for future items -> reward tight fits.
    if post_residual < 10 {
        score -= 60.0;
    } else {
        // Penalize residues that fall into awkward classes: 11..19 (too small for median items).
        if post_residual >= 11 && post_residual <= 19 {
            score += 25.0;
        }
        // Integer-division threshold: usable residual tiers.
        let tier = post_residual / 20; // 0..=4
        score -= tier as f64 * 8.0; // larger usable residual is somewhat valuable (new bin candidate competes)
    }

    // Coupling with next item: does the residual exactly host the lookahead item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain fit: perfect for lookahead
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 40.0; // near-exact hosting of next item
            } else {
                score -= (20.0 / slack as f64).min(10.0);
            }
        } else {
            // Next item cannot use this residual: dead space for lookahead.
            score += 15.0;
            // Extra penalty if residual is in a bad class AND next item is large.
            if next_item_size > post_residual && post_class < 5.0 && post_residual < 30 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base preference for reusing bins: penalize fresh bin.
        score += 70.0;
        // But if open bins have small mean residual (crowded) and this item is big, fresh bin is fine.
        if mean_residual < (item_size as f64) * 0.9 {
            score -= 65.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Reward filling bins that are already fairly full (harmonic fraction of capacity).
    let fill_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_fraction > 0.6 {
        score -= 20.0 * fill_fraction;
    }

    // Mild late-stream preference to close out bins rather than spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable dead space: heavy penalty, worse the smaller the gap.
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 35 {
            score += 5.0;
        } else {
            // Large leftovers remain useful: reward them.
            score -= 0.15 * post_residual as f64;
        }
    } else {
        // Perfect fit.
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        }
    }

    // New-bin candidate: only attractive when all open bins would leave dead space
    // or nothing fits well.
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) <= 10;
        let pressure = open_bins_count as f64 * 0.9 + mean_residual * 0.05;
        if dead && fitting_bins_count > 0 {
            score -= 10.0; // opening new bin beats creating dead space
        } else {
            score += pressure; // keep using open bins otherwise
        }
    }

    // Mean residual coupling: prefer bins close to mean (balanced packing).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Slight stream-progression tightening: later items favor tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, adjusted by stream context.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin when current item is large relative to capacity (poor fits elsewhere)
        // and when few bins can fit (fragmentation risk). Penalize otherwise.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 60.0
            - 25.0 * (1.0 - item_frac)
            - 15.0 * (fitting_bins_count == 0) as i32 as f64
            + 10.0 * progress;
        if next_item_size > post_residual && next_item_size > 0 {
            score -= 5.0; // next item won't fit here either; new bin still fine
        }
        return score;
    }

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size -> reward strongly.
        let exact = (post_residual as i64 - next_item_size as i64).abs();
        if exact == 0 {
            score -= 45.0;
        } else {
            // Reward closeness of post_residual to next_item_size (nonlinear).
            let diff = exact as f64;
            score -= 40.0 * (-diff / 12.0).exp();
        }
        // If next item fits exactly, this bin becomes "closed" effectively: extra reward
        if post_residual == next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a residual that is smaller than next item but tiny (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit (small post_residual).
        score = post_residual as f64 * 0.5;
    }

    // Relative-to-mean coupling: bins with residual above mean can absorb waste better.
    let resid = post_residual as f64;
    if resid > mean_residual {
        score -= 0.25 * (resid - mean_residual);
    } else {
        score += 0.35 * (mean_residual - resid);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (already via post_residual).
        score += 2.0 * (fitting_bins_count.min(5) as f64);
    }

    // Penalize very small unusable leftovers (dead space) nonlinearly.
    if resid > 0.0 && resid < 10.0 {
        score += 8.0 * (10.0 - resid);
    }

    // Mild preference to fill existing bins as stream progresses.
    score -= 5.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual gets strongly discounted.
    if post_residual > 0 {
        score -= 40.0 / post_residual as f64;
    } else {
        score -= 60.0; // perfect fill is highly desirable
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: bonus if next item fits into post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.25 * next_item_size as f64;
    }
    // Penalize if post-residual almost fits next item (near miss creates temptation).
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are quite full
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let pressure = (avg_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Early stream with many open bins: discourage new bins.
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 * (1.0 - pressure) + 20.0 * (1.0 - time_frac);
        // If many bins are open and mean residual is large, new bin is wasteful.
        score += 0.5 * open_bins_count as f64 + 0.2 * mean_residual;
        // But if this bin would be a terrible fit (large post_residual among open bins),
        // the base score already reflects it; give slight relief for big items.
        score -= 0.1 * item_size as f64;
    }

    // Mild preference for filling bins that are already low on space.
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 8.0 * norm_pr * (1.0 - progress);

    // Stream-progress coupling: later in stream, penalize wasted space more strongly
    score += 6.0 * progress * norm_pr * (item_size as f64 / cap);

    // Lookahead coupling: reward bins whose post-residual matches next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_gap = (post_residual - next_item_size as u32) as f64;
        score -= 10.0 * (1.0 - fit_gap / cap);
    } else if next_item_size > 0 {
        // post-residual unusable by next item: penalize proportionally
        score += 4.0 * norm_pr;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (1.0 - scarcity * 0.9) + 15.0 * (1.0 - tightness) + 20.0 * progress * scarcity;
        score -= 30.0 * scarcity * (1.0 - progress);
    } else {
        // Prefer filling already-open bins; mild penalty scaling with open bins
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues mod 10 define "usable" dead space.
    // Residuals that are multiples of 10 (or small) are likely reusable by future items.
    let residue = post_residual % 10;
    let harmonic_class = match residue {
        0 => -8.0,           // perfectly aligned leftover -> strong reward
        1..=5 => -2.0,       // small leftover, likely fillable
        6..=9 => 3.0,        // awkward leftover -> penalty
        _ => 0.0,
    };
    score += harmonic_class;

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 10.0; // bin nearly full -> excellent closure
    } else if frac < 0.15 {
        score -= 4.0;
    } else if frac > 0.5 {
        score += 6.0; // wasting more than half the bin
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chain
        } else if next_item_size <= post_residual {
            // harmonic match: next item shares residue class with post_residual
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            score += 1.5; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fit among many candidates (post_residual term already does)
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate handling: empty bin starts with full residual.
    if bin_residual == bin_capacity {
        // Prefer new bin only when the item barely fits anywhere else or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64) * 5.0 };
        let waste_penalty = (bin_capacity - item_size) as f64 * 0.35;
        let mean_gap = (mean_residual - item_size as f64).abs();
        score = waste_penalty + scarcity + mean_gap * 0.2 - progress * 3.0;
        // If next item is huge and current item small, opening fresh bin is fine.
        if next_item_size > 60 && item_size < 30 {
            score -= 5.0;
        }
    }

    // Dead-space nonlinearity: quadratic penalty for mid-range residuals.
    if post_residual > 20 && post_residual < 40 {
        score += (40 - post_residual) as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever be useful are heavily penalized.
    let min_item = 1u32;
    let next_fits_gap = if next_item_size > 0 { post_residual >= next_item_size } else { false };
    if post_residual > 0 && post_residual < 10 && !next_fits_gap {
        // Unusable sliver: strong penalty scaling with how close the fit was.
        score += 60.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if next_fits_gap {
        // The lookahead item can use the remaining gap: reward.
        score -= 15.0 + (next_item_size as f64).min(post_residual as f64) * 0.3;
    }

    // Tightness reward: relative fill of the bin by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when all
    // existing fits would create large dead space, or few bins are open.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slight pressure to reuse bins.
        score += 5.0;
        if fitting_bins_count > 0 {
            // If any open bin fits, discourage opening a new one unless the
            // open-bin fits are terrible (handled via dead-space penalties).
            score += 30.0;
        }
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // Open-bins pressure: when many bins are open, favor consolidating into
    // existing bins (penalize new-bin usage indirectly by rewarding reuse).
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Mean-residual coupling: bins with residual near the mean are "typical";
    // prefer bins with below-mean residual (tighter bins) for large items.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.08 * (item_size as f64 / 50.0);

    // Mild progression term: early in the stream, be slightly more willing
    // to open/keep bins flexible; late, prefer tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += progress * 20.0; // dead space worse late in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post residual (perfect chaining), penalize dead space otherwise.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64); // next fits well
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over; // next item cannot use this residual
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += 0.3 * post_residual as f64;
    }

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, slight penalty so we prefer
    // reusing open bins when the fit is reasonable.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the item is large relative to capacity, a fresh bin is attractive
        // since it leaves a large useful residual for future items.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Prefer tighter fits among open bins (best-fit flavor on top of lookahead).
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 100.0 * 0.01;

    // Early in the stream, encourage consolidation to build useful residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit signal: heavily reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fill
    }

    // Penalize small dead space that no typical item can use.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64 / 100.0) * 10.0;
        } else {
            score += 6.0; // bin likely closes after this item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins with slack: discourage spreading, favor consolidation.
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 1.5;
    }

    // Time horizon: early on, prefer opening fresh bins slightly less;
    // late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    // Global residual state: if mean residual is high, prefer filling existing bins.
    score += mean_residual * 0.15;

    // New-bin candidate handling: it's an empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if no open bin fits well
        // (i.e., this item would leave big waste elsewhere) or stream is early.
        let waste_penalty = (bin_capacity - item_size) as f64;
        score = 60.0 + waste_penalty * 0.6 - (1.0 - progress) * 20.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative, must open
        }
        if fitting_bins_count == 1 {
            score += 30.0; // an existing last-chance bin exists; don't open new
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * (1.0 - x) * t;
    score += 8.0 * poly;

    // Reward tight fits more aggressively as stream progresses (quadratic in fit quality)
    let fit_quality = (item_size as f64) / cap;
    score -= 12.0 * fit_quality * fit_quality * (0.5 + t);

    // Penalize creating dead space that cannot plausibly hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 - t);
        } else {
            score -= 3.0 * (pr - nx).min(20.0) / cap * (0.5 + t);
        }
    }

    // Last-chance bin bonus: strongly favor the single fitting bin to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + t);
    }

    // Mild penalty when many bins are open and residual is wasteful
    let waste = (pr - mean_residual).abs();
    score += 2.0 * waste / cap * (open_bins_count as f64).sqrt() * t;

    // New-bin candidate: keep neutral baseline, slightly penalized early, allowed late
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod common item sizes
    let r = post_residual;
    let n = next_item_size;

    // Reward residuals that are exact multiples of common size classes (10,20,25,50)
    if r > 0 && (r % 10 == 0 || r % 25 == 0) {
        score -= 6.0;
    }
    // Penalize "dead" residuals too small for the smallest plausible item
    if r > 0 && r < 10 {
        score += 25.0;
    }

    // Lookahead harmony: can the next item fit perfectly into post_residual?
    if n > 0 {
        if n == r {
            score -= 40.0; // perfect closure
        } else if n < r {
            let slack = (r - n) as f64;
            // harmonic bonus if remaining slack is itself a nice class
            let harmonious = ((r - n) % 10 == 0) || ((r - n) % 25 == 0);
            score -= 12.0 - slack * 0.05;
            if harmonious { score -= 5.0; }
        } else {
            // next item doesn't fit: penalize proportionally to wasted potential
            score += (n - r) as f64 * 0.15;
        }
    }

    // Capacity fraction classes of the current fill level
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill >= 0.9 {
        score -= 20.0; // nearly full bins are excellent
    } else if fill >= 0.5 {
        score -= 5.0;
    }

    // Last-chance bin: strong preference to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win if nothing fits well
    if bin_residual == bin_capacity {
        // base penalty so a new bin is only chosen when open bins score badly
        score += 30.0 + mean_residual * 0.1;
        if n > 0 && n >= 50 {
            score -= 10.0; // big next item: keep fresh capacity
        }
    }

    // Stream progression: later in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    // Mild tie-break by mean residual alignment
    if (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items (1..100 unknown distribution) are pure waste.
    // Penalize non-zero post_residual strongly, especially tiny gaps.
    if post_residual > 0 {
        // "Usable" threshold: gaps below ~10 are almost certainly dead space.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 40 {
            score += 6.0;
        }
        // Quadratic dead-space term: larger leftover gaps cost more.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64 * 4.0);
    } else {
        // Perfect fit: strongly reward.
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across too many bins,
    // but allow new bins when the fit is bad (handled via residual terms).
    score += open_bins_count as f64 * 0.35;

    // Mean residual coupling: if open bins are already quite full on average,
    // filling this bin further is valuable.
    score -= (mean_residual / bin_capacity as f64) * 4.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here; small leftovers become dead space.
            if post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // Late in the stream, waste matters more (less future to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how poor current fits are.
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space penalty: squared residual beyond a small tolerance
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) * 0.02;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
        // Exact chain fit: huge reward
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item doesn't fit here after placement: mild penalty for wasted lookahead
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative
    // to all residuals (poor fits everywhere) or stream is nearly done
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0;
        // If item fits poorly everywhere (few fitting bins relative to open bins),
        // opening fresh is more attractive
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // chain impossible in fresh bin either; less attractive
            score += 10.0;
        }
        let _ = progress;
    }

    // Prefer tighter bins overall (best-fit flavor with lookahead dominance)
    score += (bin_capacity - bin_residual) as f64 * (-0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full usage of residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward exact / near-exact fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (1..100, min observed 1)
    if post_residual > 0 && post_residual < item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let lookahead_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - lookahead_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; small penalty if this bin would become nearly full anyway
            if post_residual <= 10 {
                score += 4.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    let mean_res_gap = mean_residual - post_residual as f64;
    if mean_res_gap > 0.0 {
        score -= 3.0 * mean_res_gap / bin_capacity as f64 * (open_bins_count as f64).sqrt();
    }

    // Time horizon: early on, be conservative (keep bins flexible); late, close bins aggressively
    if progress > 0.5 {
        score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        // Early: penalize creating very small residuals (flexibility loss)
        if post_residual > 0 && post_residual < 20 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with stream progress (fewer chances to fill it)
        let new_bin_cost = 55.0 + 25.0 * progress;
        // Cheaper to open new bin if existing bins are crowded / item is large
        let relief = if fitting_bins_count == 0 {
            80.0
        } else {
            20.0 * (1.0 - fit_ratio) + 5.0 * (open_bins_count as f64).ln().max(0.0)
        };
        score += new_bin_cost - relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: quadratic post_residual scaled by stream progress.
    // Early on, small residuals are mildly penalized; late in the stream, dead space
    // becomes increasingly costly, so the quadratic term grows with progress.
    let x = pr / cap;
    let quad = x * x * (0.5 + 2.0 * progress);
    score += 20.0 * quad;

    // Cubic interaction: strongly reward near-perfect fits (small post_residual),
    // with a smooth bump rather than a hard threshold.
    let fit_reward = (1.0 - x).powi(3) * (1.0 + 0.5 * progress);
    score -= 15.0 * fit_reward;

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin
    // smoothly, scaled by how much room remains for it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - slack) * (1.0 - progress * 0.5);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a mid-sized unusable gap.
        let gap = x * (1.0 - x);
        score += 6.0 * gap * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Contextual adjustment: relative residual vs mean residual of open bins.
    // Bins with residual below the mean are closer to being closed out; favor them.
    let rel = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 4.0 * (rel - 1.0).tanh();

    // New-bin candidate: neutral-ish but slightly penalized early (avoid bin explosion),
    // more acceptable late when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 buckets
    let r_mod = post_residual % 10;
    // Dead-space penalty: residuals that no typical item (1..=10 classes) fits well
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver is nearly dead space
    }
    // Reward exact-class residuals: multiples of 10 are "harmonic" with capacity 100
    if r_mod == 0 {
        score -= 12.0;
    } else if r_mod <= 3 || r_mod >= 7 {
        score += 6.0; // off-harmonic residual, harder to fill
    }

    // Integer-division threshold: can post_residual hold next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fit: reward, scaled by how tightly next item fits
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.25 * tight.min(40.0);
        } else {
            score += 10.0; // this bin becomes dead after placement
        }
    } else {
        // last item: minimize leftover harshly
        score += post_residual as f64 * 0.5;
    }

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish unless open bins are crowded
    if bin_residual == bin_capacity {
        let base = 55.0;
        // penalize opening bins early in the stream; reward later when bins are full of small residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = base + progress * 10.0 - avg_tightness * 30.0;
        // if lookahead also fits the fresh bin, slightly discourage hoarding
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 5.0;
        }
    }

    // Prefer packing into bins with below-mean residual (tighter bins first)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Many open bins: discourage spreading, favor consolidation
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + 5.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gap: partial penalty.
        score += 8.0;
    }

    // Reward tight fits (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Reward using bins that are already quite full (residual small).
    let residual_ratio = bin_residual as f64 / bin_capacity as f64;
    score += 15.0 * residual_ratio;

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap it can't use.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if mean residual across open bins is high, a new bin is less harmful.
        score -= 2.0 * mean_residual / bin_capacity as f64;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: heavily reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5.0 - post_residual as f64) * 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item can also fit here afterwards: strong reward, tighter match = better.
            score -= 150.0 - gap.min(150.0);
        } else {
            // Penalize leaving a residual slightly smaller than next item (wasted sliver).
            score += (gap / 10.0).min(30.0);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin when decent open fits exist,
    // but allow it when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let open_penalty = if fitting_bins_count == 0 {
            -500.0 // must open a bin
        } else {
            let best_frag = (post_residual as f64) + item_size as f64; // = capacity
            let waste_if_open = 0.0;
            let waste_if_use = mean_residual - item_size as f64;
            if waste_if_use > 60.0 { -50.0 } else { 120.0 + waste_if_use }
        };
        score += open_penalty;
        // Early stream: prefer opening bins to spread load; late stream: consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (progress - 0.5) * 60.0;
    }

    // Mild preference for fuller bins overall.
    score += (bin_capacity - bin_residual) as f64 * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward good fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 8.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 - slack.min(20.0)) * 0.8;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Mild default cost for opening a new bin.
        score += 25.0;
        // Cheaper to open new bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // If many bins are open with scattered residuals, opening a fresh bin is fine.
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // If the current item is small relative to mean residual, new bin is wasteful.
        if (item_size as f64) < mean_residual {
            score += 20.0;
        }
    } else {
        // Prefer bins whose residual is already below the mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Penalize leaving residuals in the awkward zone (1..10) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: waste after placement, mildly compressed non-linearly.
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr) * cap;

    // Polynomial coupling of post-residual with stream progress:
    // early on, tolerate residual waste; late, penalize it harder.
    let progress_coupling = 1.0 + 1.8 * progress * progress + 0.9 * progress;
    score *= progress_coupling;

    // Reward near-perfect fits (small post_residual) with a smooth bonus.
    let tightness = (1.0 - norm_pr).powi(6);
    score -= 12.0 * tightness * (1.0 + 2.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if next item fits in the resulting residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - (nxt / cap).powi(2));
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling below-average-residual bins first keeps flexible bins open.
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev.abs();

    // Mild penalty for proliferating open bins early in the stream.
    score += 0.4 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Smooth tie-break toward larger fills (smaller post_residual) via cubic term.
    score += 0.5 * (norm_pr - fit).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 8.0)).floor(); // 0..8 harmonic octile class
    // Reward tiny residuals (near-perfect fit), penalize mid-range dead space.
    score -= 18.0 * (1.0 - class / 8.0) * (1.0 - class / 8.0) * (pr / cap);

    // Integer-division thresholds: residuals that are exact multiples of small
    // denominators are reusable by future items.
    let res = post_residual;
    if res > 0 {
        if res % 10 == 0 { score -= 6.0; }
        else if res % 5 == 0 { score -= 3.0; }
        else if res % 25 == 0 { score -= 8.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit: penalize leaving a stranded mid residual
            if post_residual < 10 {
                score += 4.0; // tiny dead space, mildly bad
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (item_size as f64) / cap;
        // New bin is attractive when item is large and mean residual is small.
        let new_bin_score = cap - 40.0 * tightness
            - 10.0 * (mean_residual / cap)
            - 15.0 * progress
            - 2.0 * open_bins_count as f64;
        // Blend: keep base residual but apply new-bin evaluation.
        score = 0.5 * score + 0.5 * new_bin_score;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // reserve space for a growing trend
        }
    }

    // Mild global pressure: prefer filling bins when many are open.
    score -= 0.5 * open_bins_count as f64 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are almost unusable
    // (min item size is 1, but small gaps rarely match future items well).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 - 2.0 * post_residual as f64; // worst for tiny gaps
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins whose residual is below the mean residual).
    if open_bins_count > 2 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);
        if (bin_residual as f64) < mean_residual {
            score -= pressure;
        } else {
            score += pressure * 0.5;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // residual too small for next item: mild penalty scaled by waste
            score += (post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate: only attractive when the current item is large
    // (fills a fresh bin well) or no open bin fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // opening a fresh bin is good if item is big and would waste little
            score = 60.0 - 50.0 * fill_ratio + (bin_capacity - item_size) as f64 * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact chain fit (next item fills bin completely) is ideal.
        if post_residual == next_item_size {
            score -= 800.0;
        } else {
            // Reward proportional to how well the chain fills the bin.
            let chain_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 300.0 * chain_fill;
        }
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize leaving awkward dead space,
        // scaled by how much slack is wasted.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 150.0 * waste;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items
    // (keeps flexibility); later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or early in stream.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 250.0 * item_frac * (1.0 - 0.5 * progress);
    } else {
        // Late in the stream, filling existing bins is more valuable.
        score -= 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: exact or near-exact fits are excellent.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine
    } else if post_residual >= 10 && post_residual < 40 {
        score += 3.0; // awkward mid-range gap
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 6.0 * chain_fit;
        } else {
            score += 4.0; // next item won't fit here; bin becomes dead-ish
        }
    } else {
        // Last item: minimize waste aggressively.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of options; be pickier
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = mean_residual / (bin_capacity as f64);
    if pressure < 0.25 && bin_residual < bin_capacity {
        score -= 10.0 * (0.25 - pressure);
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 15.0 - 8.0 * progress;
        // More open bins => cheaper to open another (spread state).
        open_cost -= 0.5 * open_bins_count as f64;
        // If no existing bin fits well (large post_residual would be big), opening is attractive.
        if next_item_size > 0 && next_item_size >= post_residual && bin_residual != post_residual + item_size {
            open_cost -= 5.0;
        }
        score += open_cost.max(2.0);
    }

    // Mild preference for bins with below-average residual (keeps big holes available).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 4.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, prefer tight fits less aggressively; late, chase tight fits hard.
    let phase = progress * std::f64::consts::PI;
    let tightness_reward = (x * x * (1.0 - x)) * (1.0 + 2.0 * phase.sin());
    score -= 30.0 * tightness_reward;

    // Polynomial penalty for medium dead space (worst around x ~ 0.4-0.6),
    // scaled up as the stream progresses.
    let dead = x * (1.0 - x); // peaks mid-range
    score += 25.0 * dead * dead * (0.5 + progress);

    // Last-chance bin bonus (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual (smooth fit measure).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // penalize post-residual that cannot host the lookahead item, mildly
        score += 5.0 * (1.0 - progress);
    }

    // Discourage spreading when many bins are open and mean residual is high.
    let open_pressure = (open_bins_count as f64).ln1p();
    score += 3.0 * open_pressure * (mean_residual / cap - x).abs();

    // New-bin candidate: make it slightly less attractive than a genuinely
    // good fit, but better than a poor fit (poor fits carry the dead-space penalty).
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "useful" residue class (multiples of 10 / small remainders) are favored.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if class == 0 {
        score -= 12.0; // round leftover, reusable by decade-sized items
    } else if class <= 3 {
        score += 6.0;  // sliver dead space
    }

    // Integer-division thresholds: leftover that can host the next item is gold.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 18.0;
            // harmonic pairing: pr % next_item_size small => chain continues
            let m = pr % next_item_size;
            if m == 0 { score -= 10.0; }
            else if m <= 5 { score -= 4.0; }
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Capacity fraction coupling: penalize leaving > half capacity idle.
    let half = bin_capacity / 2;
    if pr > half {
        score += (pr - half) as f64 * 0.6;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = item_size as f64 > mean_residual + 10.0;
        if tight || open_bins_count == 0 {
            score -= 20.0 + 10.0 * (1.0 - progress);
        } else {
            score += 30.0; // discourage sprawl when open bins can host
        }
    }

    // Mild tie-break: prefer filling bins below mean residual (denser bins).
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are nearly unusable; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal zone: only fits the smallest items; moderate penalty.
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits: the closer post_residual is to 0 (without being dead),
    // the better the packing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Open-bins pressure: penalize placements that keep many bins alive,
    // but only mildly, so tight fits still win.
    score += 2.0 * open_bins_count as f64;

    // If this bin's residual is far below the mean residual, it is a laggard
    // bin; filling it down is good (reduces fragmentation spread).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Lookahead: if the next item would fit exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits afterwards: mild reward.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this leftover; penalize proportionally.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin expensive unless the
    // current item is large relative to capacity or fits are all poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression
        // (early on, opening bins is cheaper / necessary).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 + 25.0 * progress;

        // If the item nearly fills a fresh bin, opening one is fine.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 55.0;
        }
        // If no open bin can fit the item at all, new bin is the only choice.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let remaining_after_next = post_residual - next_item_size;
        score -= 200.0 + remaining_after_next as f64 * 0.5;
        // Bonus if next item then fits tightly (chained lookahead)
        if remaining_after_next == 0 {
            score -= 300.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize leaving large dead space
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += dead * 0.8;
        }
    }

    // Reward bins tighter than the mean residual (better-than-average fit)
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 1.5;

    // Penalize bins looser than the mean (wasteful choice)
    if mean_gap < 0.0 {
        score += (-mean_gap) * 1.2;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty for opening a new bin
        score += 120.0;
        // If next item is large, a fresh bin is valuable (it can host both)
        if next_item_size > post_residual.min(bin_residual) {
            score -= 80.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mild penalty for large waste relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Slight preference to fill bins with more content already (fewer open bins is better)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward placements that fill the bin well.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Penalize large dead space non-linearly (waste grows super-linearly).
    let dead = post_residual as f64;
    score += 0.012 * dead * dead;

    // Lookahead: if the next item fits into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We block the next item that would have fit elsewhere-ish: mild penalty unless waste is tiny.
        if post_residual > 0 {
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 10.0 + 6.0 * fit_quality;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when existing fits are poor or no bins fit.
    if bin_residual == bin_capacity {
        score += 14.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is less attractive (fewer future items to fill them).
        score += 6.0 * t;
        // If the next item is large and current item small, a fresh bin is more useful.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 2.0;
        }
    } else {
        // Slight preference for bins with residuals below mean (consolidate small leftovers).
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Mild penalty for spreading across many bins early; encourage consolidation.
    score += 0.15 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress * (1.0 - progress);
    score += 40.0 * poly;

    // Penalize dead space more as stream progresses
    score += 30.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (low post residual) especially when few alternatives
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 15.0 * (1.0 - (ni / cap).powi(2)) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * ((ni - pr) / cap) * (0.5 + progress);
        }
    }

    // Mild penalty for proliferating bins early
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 3.0;

    // Attract toward mean residual to keep bins balanced
    score += 5.0 * (norm_pr * cap - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into coarse classes
    // via integer division; class 0 (very tight fit) is highly desirable.
    let class = post_residual / 10; // 0..=10 harmonic class
    score -= match class {
        0 => 40.0,                    // near-perfect fit
        1 => 22.0,                    // small gap, likely usable by small items
        2 => 10.0,
        3 => 4.0,
        4 => 0.0,
        5 => -2.0,                    // mid-range residual is flexible
        6 => 0.0,
        7 => 3.0,
        8 => 7.0,
        9 => 12.0,
        _ => 0.0,                     // full class handled below
    };

    // Exact-fill bonus: item perfectly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next_item_size fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain potential: reward proportional to how well next item fills the gap.
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * chain_fill;
            // Harmonic class of the remaining gap after the lookahead item.
            let post2 = post_residual - next_item_size;
            score -= match post2 / 10 {
                0 => 10.0,
                1 => 6.0,
                2 => 3.0,
                _ => 0.0,
            };
        } else {
            // Next item won't fit here: penalize proportionally to the wasted lookahead.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer keeping items out of fresh bins unless current open bins are poor fits.
        // Penalize more when many bins are open and mean residual is large.
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let slack = mean_residual / bin_capacity as f64;
        score += 25.0 + 30.0 * crowding * (1.0 - slack);
        // But if no other bin fits (last-chance), the new bin is fine: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Slight preference to fill older/more-populated bins as the stream progresses,
    // encouraging consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize tiny unusable slivers (1..=3 residual) unless exact fit already rewarded.
    if post_residual > 0 && post_residual < 4 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless current bin would leave severe dead space
    // or the next item fits better in a fresh bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 45.0; // opening fresh bin avoids creating dead space here
        }
        if next_item_size > 0 && next_item_size >= post_residual && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // fresh bin accommodates the lookahead item
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size <= post_residual + item_size {
        // Placing here leaves a gap the next item can't use but could use if we
        // packed differently — mild penalty.
        score += 10.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Deviation from mean residual: prefer bins with less residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward bins whose post_residual matches the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // Perfect chain fit: post_residual exactly equals next item size.
            let gap = pr - nxt;
            // Strong reward for small gaps; decays as gap grows.
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64)) * (gap / nxt).min(1.0).exp().recip();
            // Extra bonus if the residual after the lookahead item would also be small.
            let post2 = gap;
            if post2 <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Lookahead item cannot fit here: mild penalty proportional to overshoot.
            let overshoot = nxt - pr;
            score += 4.0 * (overshoot / 100.0).min(1.0);
        }
    }

    // --- Tightness reward: placing item into a nearly-full residual is excellent ---
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 25.0 * (tightness - 0.9) * 10.0;
    } else if tightness > 0.7 {
        score -= 10.0 * (tightness - 0.7) * 5.0;
    }

    // --- Dead-space penalty: small unusable post_residual (< 10, min item size) is wasted ---
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // --- Relative to mean residual: prefer bins already below-average fullness for big items ---
    if mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * rel;
    }

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling: opening a new bin is discouraged unless nothing fits well ---
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in the stream or when many bins exist.
        let penalty = 45.0 - 20.0 * progress - (open_bins_count as f64).min(20.0);
        // If lookahead item is large, a fresh bin is more attractive.
        score += penalty - 0.1 * next_item_size as f64;
    }

    // --- Slight preference for fewer open bins (bin consolidation pressure) ---
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = post;

    // Reward near-perfect fits with a non-linear bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Penalize creating dead space that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 + 0.05 * nxt;
        } else {
            // next item won't fit here; mild penalty scaled by waste
            score += 0.03 * (nxt - post);
        }
        // If next item exactly matches post_residual, big bonus.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance logic: only one bin fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: favor consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * crowding * (0.5 + 0.5 * progress);

    // Global residual state: if mean residual is low, conserve space aggressively.
    if mean_residual < 20.0 {
        score += 4.0 * (20.0 - mean_residual) / 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item is large and would leave a bad fit elsewhere.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // Large items pack cleanly in fresh bins; reduce penalty.
        new_bin_penalty -= 0.15 * item;
        // Late in the stream, prefer closing out existing bins.
        new_bin_penalty += 10.0 * progress;
        // If existing bins are fragmented (high mean residual spread vs item), allow new bin.
        if mean_residual > 0.0 && (item > mean_residual + 30.0) {
            new_bin_penalty -= 12.0;
        }
        // If no open bin fits well (this call reached as new-bin with few alternatives).
        if fitting_bins_count == 0 {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Slight time-horizon modulation: early stream, keep bins flexible.
    score += 3.0 * (1.0 - progress) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), with non-linear sharpening
    let mut score = 2.0 * pr as f64 + 60.0 * x * x * (1.0 - x);

    // Stream-progress coupling: later in the stream, dead space matters more
    let prog = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 90.0 * prog * x * x;

    // Reward using an existing bin when few bins can fit (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 45.0 * (1.0 - x);
    }

    // Penalize opening a new bin when plenty of open bins could fit
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).ln_1p();
        score += 30.0 + 25.0 * (1.0 - prog) - 20.0 * pressure;
        // A fresh bin is attractive if the next item is large
        if next_item_size > 0 {
            let nx = next_item_size as f64 / cap;
            score -= 50.0 * nx * nx * (1.0 - x);
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 40.0 * (1.0 - gap * gap);
    }

    // Mild coupling with mean residual: avoid bins far from the pack's average slack
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference for bins with more open competition (keep flexibility)
    score += 2.0 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference (lower post_residual wins), scaled.
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by 10 (capacity/10) are "harmonic" and more reusable.
    let cap_frac = bin_capacity / 10; // = 10
    let harmonic = post_residual % cap_frac == 0;
    if harmonic {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Perfect fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation; mild reward scaled by tightness
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * tightness;
            // harmonic coupling: post_residual - next_item_size divisible by 5
            if (post_residual - next_item_size) % 5 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize large dead residuals
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 20.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only if the item is huge and would leave tiny unusable
        // slivers in existing bins, or late in the stream when few bins fit.
        let sliver = post_residual < 10;
        if !sliver {
            score += 30.0; // discourage wasting a fresh bin
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
        // early stream: opening bins cheaply is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Many open bins with high mean residual: encourage consolidating into
    // bins with below-average residual (tighter bins).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 20; // 0..=5
    score += class as f64 * 2.0; // larger dead classes penalized

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap is "dead" if it's too small for typical future items
    // (assume minimum plausible item ~ 1..10). Penalize gaps in (0, 10]
    // super-linearly, and gaps in (10, 30] moderately.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap <= 10.0 {
            // worst kind of dead space: nearly zero residual
            score += 40.0 * (10.0 - gap) / 10.0 + 25.0;
        } else if gap <= 30.0 {
            score += 12.0 * (30.0 - gap) / 20.0;
        } else {
            // large residuals are mildly good (room for future items)
            score -= 6.0 * ((gap - 30.0) / (bin_capacity as f64 - 30.0)).min(1.0);
        }
    }

    // Perfect fit reward: leaving exactly zero residual is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: prefer filling existing bins over opening new ones,
    // scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as open_bins_count grows,
        // but relax when no open bin fits well (last-chance dynamics).
        score += 30.0 + 4.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open new bin
        }
    } else {
        // reward placing into existing bins
        score -= 3.0 + 0.5 * open_bins_count as f64;
        // last chance: strongly favor using the only bin that fits
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits into the post residual, reward;
    // if it leaves the next item stranded, penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Stream progression: early on, be more tolerant of opening bins;
    // later, tighten dead-space penalties since consolidation matters.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mild tie-break toward bins tighter than average (better fit quality)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (low post residual).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let gap = post_residual as f64 - next;
            // Exact match for next item is excellent.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Penalize leaving a gap that is too large relative to next item.
            score += 0.15 * gap;
        } else {
            // Post residual smaller than next item: dead space unless tiny.
            let dead = post_residual as f64;
            score += 0.25 * dead;
            if dead < 5.0 {
                score -= 8.0; // nearly perfect fill
            }
        }
        // If next item fits better in another bin, mild penalty for hoarding space.
        if next > item_size as f64 && (post_residual as f64) < next {
            score += 3.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (concentrate filling) when this placement is tight.
    let mean = mean_residual;
    if (post_residual as f64) < mean {
        score -= 4.0 * (mean - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * (post_residual as f64 - mean) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity or no good fit exists (post_residual of empty bin = capacity).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin when item is big (would leave large unusable gap elsewhere anyway)
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // Few open bins -> opening is fine.
        if open_bins_count < 3 {
            score -= 8.0;
        }
    }

    // Mild penalty for very small item into very large residual (wasteful).
    if (item_size as f64) < 0.25 * bin_residual as f64 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty, scaled by capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Strongly reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: big bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item would fit the post-residual,
    // reward this placement (chaining two items in one bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.3 * post_residual as f64;
            // If next item fits current residual but not post, prefer other bins.
            if bin_residual >= next_item_size {
                score += 8.0;
            }
        }
    }

    // Prefer bins with residuals close to the item (best-fit flavor)
    // while penalizing bins far from the mean residual (outliers).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.4 * gap;

    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Time horizon: early in the stream, be conservative (avoid opening
    // many bins); late in the stream, allow new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, discounted as stream progresses
        // or when existing bins are congested.
        score += 60.0 - 25.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0 - 15.0 * progress;
        }
        // If no open bin fits well, opening a bin is attractive.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else if progress < 0.3 {
        // Early: favor filling existing bins.
        score -= 10.0;
    }

    // Many open bins with high mean residual: encourage consolidation.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild penalty on large residuals (keep bins flexible).
    // Later: reward tight fits (small post_residual) more aggressively.
    let tightness = 1.0 - (pr / cap);
    let coupling = (1.0 - progress) * (pr * pr) / cap + progress * (1.0 - tightness) * (1.0 - tightness) * cap;
    score += 0.35 * coupling;

    // Smooth interaction: exact fit bonus amplified by progress.
    let exact = (pr == 0) as i32 as f64;
    score -= exact * (8.0 + 12.0 * progress);

    // Penalize bins with low residual relative to mean (wasted capacity elsewhere).
    let rel = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 0.15 * (rel - 1.0).abs();

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 4.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: penalize slightly more as stream progresses (prefer consolidation),
    // but allow early when many bins already open.
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * progress - 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue mod 10
    let pr = post_residual;
    let class = pr % 10;

    // Residues that pair well with common item sizes (multiples of 10) are less dead
    let class_bonus: f64 = match class {
        0 => 6.0,   // perfectly reusable
        5 => 4.0,   // half-class, still flexible
        2 | 8 => 2.0,
        1 | 9 => 0.5,
        _ => -2.0,  // odd/prime-ish residues are dead space -> penalize
    };
    score -= class_bonus;

    // Integer-division threshold: post_residual bucket by /10
    let bucket = pr / 10;
    if bucket == 0 {
        // tiny residual: nearly perfect fit, reward strongly
        score -= 8.0;
    } else if bucket <= 2 {
        score -= 3.0;
    } else if bucket >= 6 {
        // large residual left: wasteful placement of a small item
        score += 4.0;
    }

    // Exact fill is ideal
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic: next item lands here -> reward, scaled by fit tightness
            let tight = (pr - next_item_size) as f64;
            score -= 5.0 + 10.0 / (1.0 + tight);
        } else {
            // next item won't fit; penalize more if post_residual is awkward
            let gap = (next_item_size - pr) as f64;
            score += 1.0 + gap / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins are crowded
        // or the item is large and fits nowhere well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        if item_size > 60 || crowding < 0.15 {
            score -= 4.0 + 6.0 * progress;
        } else {
            // prefer existing bins otherwise
            score += 12.0;
        }
    }

    // Mild preference to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins near the mean (balanced packing)
    score += 0.02 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable item (1..=100 range, but practically small items) are dead
    // space. Penalize tiny unusable gaps harshly via a non-linear bump.
    let dead_threshold = 8.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0) * 12.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 6.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    }
    // Penalize if next item cannot fit in post residual but this bin was tight.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Open bins pressure: discourage spreading across many bins; favor filling
    // existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make empty-bin choice costly unless current bins are
    // very fragmented (high mean residual implies poor fits available).
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual > 40.0 {
            score -= mean_residual * 0.4;
        }
    }

    // Late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the leftover space (partial lookahead match)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post - nxt;
        score -= 25.0 * (1.0 - slack / cap);
    }
    // Penalize dead space that cannot host the next item, worse when residual is tiny
    if next_item_size > 0 && next_item_size > post_residual {
        score += 12.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Reward filling bins tighter than the current mean residual (good compaction)
    let mean_gap = post - mean_residual;
    score += 0.15 * mean_gap;

    // Penalize leaving large residuals early in the stream (keep bins flexible later)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * post;

    // Slight penalty when many bins are open: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is huge and no tight fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + 0.3 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of the bin consumed by this item
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward near-perfect fills strongly (subtract for low score)
    if post_residual == 0 {
        score -= 1000.0; // exact fill: always take it
    } else {
        // Reward leaving a residual that the next item can use
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else if next_item_size > 0 {
            // Penalize blocking the lookahead item
            score += 0.6 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }

        // Penalize small unusable dead space quadratically
        let dead = post_residual as f64;
        score += 0.02 * dead * dead / (1.0 + fit_ratio);

        // Reward high fill ratio, more so late in the stream
        score -= (1.0 - fill_ratio) * (20.0 + 30.0 * progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if existing bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * (0.9 + 0.4 * (1.0 - progress));
        // If many bins fit, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 60.0 + 15.0 * fitting_bins_count as f64;
        }
        // If mean residual across open bins is very low, opening fresh is fine
        score -= (mean_residual / 10.0).min(15.0);
        // Large items early: prefer a fresh bin to avoid fragmenting
        if fit_ratio > 0.6 && progress < 0.5 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight bonus when its residual is below average (tighter bin)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild penalty for accumulating too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits, amplified later in the stream
    let tightness = (item_size as f64) / cap;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals near next item size mismatch (dead space)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 4.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr * 0.5);
    }

    // Slight preference for bins below mean residual (consolidate waste)
    score += 0.05 * (mean_residual - pr) * (1.0 + progress);

    // Mild penalty for proliferating open bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let mut score = post_f;

    // Harmonic class of post_residual: bins whose leftover falls on
    // "nice" capacity fractions (0, cap/4, cap/2, 3cap/4) are ideal.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect closure
    } else if post_residual == quarter || post_residual == three_quarter {
        -12.0
    } else if post_residual == half {
        -15.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Modulo classes: leftovers divisible by common small sizes (10..=20)
    // are reusable by future items; penalize odd/dead remainders.
    if post_residual > 0 {
        let reusable = (10..=20).any(|s| post_residual % s == 0 && post_residual >= s);
        if reusable { score -= 6.0; }
        // integer-division threshold: dead space if post_residual < 10
        if post_residual < 10 { score += 40.0 * (10 - post_residual) as f64; }
        // mid-range dead zone (cap/3-ish) is hard to fill
        if post_residual > 25 && post_residual < 40 { score += 8.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 { score -= 5.0; } // chains toward closure
            score -= 4.0;
        } else {
            // next item won't fit here: leftover likely wasted
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes its full residual
    // unless current placements are bad. Make empty bin mildly attractive only
    // when this bin would leave a large dead remainder.
    if bin_residual == bin_capacity {
        // base cost of a new bin, discounted when item is large
        score = cap_f - 0.5 * item_size as f64;
        if post_residual_of(item_size, bin_capacity) <= 20 {
            score -= 8.0; // large item nearly fills a bin: open freely
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Progress scaling: early in stream, keep bins open/flexible; late, close tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * harmonic_bonus.abs() / 30.0;

    // Tie-break toward tighter bins when many are open
    score += 0.05 * open_bins_count as f64;
    score += 0.02 * (mean_residual - post_f).abs();

    score
}

fn post_residual_of(item_size: u32, bin_capacity: u32) -> u32 {
    bin_capacity.saturating_sub(item_size)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Threshold scales with a plausible minimum useful size.
    let dead_threshold = 10.0 + 0.05 * mean_residual;
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += 2.5 * (dead_threshold - post_residual as f64);
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fits (small positive residual) rewarded proportionally.
    score -= 0.6 * (bin_residual - post_residual) as f64 / bin_capacity as f64 * 20.0;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item nearly fits, small reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(2) && post_residual < next_item_size {
        score -= 3.0;
    }

    // Open bins pressure: penalize placements that keep many bins open mildly,
    // but reward using existing bins when many are open (avoid opening new bins).
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 1.5 * open_bins_count as f64;
        // If no open bin fits tightly, opening a new bin is less bad.
        if post_residual as f64 > dead_threshold {
            score -= 10.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Partial lookahead credit: how close post_residual is to next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize dead space more
        score += 20.0;
    }

    // Reward tight fills (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Compare against mean residual: prefer bins below mean residual (tighter than average)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins can fit the item
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
        // Early in stream, new bins are cheaper; late, avoid proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * tight * tight;

    // Penalize dead space that nothing can ever use: post_residual < 10 is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0 * (nxt / cap);
        } else {
            score += 6.0 * (nxt / cap);
        }
        // If next item fits exactly in post_residual, big bonus.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let fill_pressure = mean_residual / cap;
    if bin_residual != bin_capacity {
        score -= 10.0 * fill_pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: penalize proportionally to how well existing bins
    // could still absorb items, but allow it when item is huge and fits poorly.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / cap;
        score += 18.0 + 25.0 * waste;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open new bin
        }
    }

    // Time horizon: late in the stream, consolidate more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Mild penalty for leaving residual in the awkward 20-35 dead zone.
    if post_residual >= 20 && post_residual <= 35 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let compat = (pr - ns).abs();
        score += 0.2 * compat;
        if pr >= ns {
            score -= 10.0 * (1.0 - compat / cap);
        }
    }

    // Mild penalty for proliferating bins early in the stream
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let cap = bin_capacity;

    // Reward post-residuals that are exactly reusable by typical items
    // (residue classes modulo 10, since items are multiples of 10 in the
    // canonical setting; degrade gracefully otherwise).
    if pr > 0 {
        let m = pr % 10;
        if m == 0 {
            score -= 4.0; // perfectly reusable leftover
        } else {
            score += m as f64 * 0.6; // dead-space penalty grows with misalignment
        }
    } else {
        score -= 12.0; // perfect fill: strongly preferred
    }

    // Integer-division threshold: small post-residuals (< 10) are dead space.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Coupling with lookahead item: if next item fits exactly in the
    // post-residual, this is a harmonic pair — big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large or open bins are congested.
    if bin_residual == cap {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap as f64);
        score = cap as f64 * 0.5
            + congestion * 2.0
            - item_size as f64 * 0.3
            - progress * 3.0;
        if item_size > cap / 2 {
            score -= 5.0; // large items deserve fresh bins
        }
    }

    // Mild preference for bins tighter than the current mean residual
    // (waste-minimization tilt).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    // A gap is "dead" if it's too small for the smallest plausible item (<= ~10)
    // or too small for the lookahead item when it would otherwise fit nothing.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 120.0; // unusable sliver
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            // gap cannot host the next item: future dead space risk
            let waste_ratio = 1.0 - (next_item_size as f64 / post_residual.max(1) as f64);
            score += 25.0 + 40.0 * waste_ratio;
        }
    } else {
        score -= 60.0; // perfect closure is excellent
    }

    // Reward tight fits (low post_residual relative to item size).
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // mild penalty so the best-fitting bin wins among several
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: discourage proliferation of bins, but relax late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well,
        // i.e., when the best post_residual among open bins would be large.
        // Proxy: mean residual is high and item is large relative to it.
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 0.0 && mean_gap < 15.0 {
            score -= 20.0; // open bins fit well; keep item there
        } else {
            score += 35.0; // default: avoid opening new bins
        }
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity && (next_item_size as u32) > item_size {
            score -= 10.0; // fresh bin can host the larger next item
        }
    }

    // Mild alignment bonus: placing item so leftover matches typical item sizes.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact (or near-exact) fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let gap = (post_residual as f64 - nr).abs();
        if post_residual as f64 >= nr {
            // Next item can follow in this bin: reward proportional to tightness.
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 250.0; // perfect 2-item packing
            }
        } else {
            // Dead space the next item cannot use: penalize.
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: prefer filling bins below mean residual
    // (i.e., already tight bins) to keep wide-open bins available.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins
    // would leave large unusable residuals.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 { 0.0 } else { post_residual as f64 };
        score = 40.0 + best_possible * 0.4
            - (mean_residual - post_residual as f64).max(0.0) * 0.3;
        if fitting_bins_count == 1 {
            score += 400.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 1 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Lookahead: penalize residual that the next item cannot use (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can host the next item, scaled by tightness
            let usable = (next_item_size as f64) / (post_residual as f64);
            score -= 8.0 * usable;
        } else {
            // Dead space penalty grows with how close the next item is to fitting
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap / bin_capacity as f64;
        }
    } else {
        // Last item: prefer filling a bin as tightly as possible
        score += 2.0 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but relax the
    // penalty as the stream progresses (consolidation becomes more valuable)
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 * (1.0 - 0.5 * progress);
        // Extra penalty when many bins are open and fragmented
        let fragmentation = (open_bins_count as f64).ln1p() * 2.0;
        score += new_bin_penalty + fragmentation;
        // If the current item is large relative to capacity, a fresh bin is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Prefer bins tighter than the average residual (well-utilized bins)
    let avg_gap = mean_residual - post_residual as f64;
    score += 0.3 * avg_gap;

    // Mild reward for very tight fits (small leftover)
    if post_residual <= 5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Progress coupling: penalize large residuals more strongly late in stream
    let late = progress * progress;
    score += late * 30.0 * norm_pr * norm_pr;

    // Early stream: slight preference for consolidation (favor small post_residual extra)
    let early = (1.0 - progress).max(0.0);
    score -= early * 8.0 * (item_size as f64 / cap);

    // Penalize when post_residual cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 10.0 + (ni - pr) * 0.5;
        } else {
            score -= 5.0 * (1.0 - ((pr - ni) / cap));
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: encourage filling existing ones over opening new
    score += 0.05 * open_bins_count as f64 * (1.0 - early);

    // Mean residual coupling: prefer bins deviating from mean (tight fit)
    score += 0.3 * (pr - mean_residual).abs();

    // New bin candidate: penalize mildly so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: exact-fill classes are gold.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: residual can host the lookahead item exactly (harmonic pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64) * 0.5;
    }
    // Class C: residual smaller than next item -> dead space unless tiny.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + pr * 0.3;
    }

    // Integer-division thresholds on post_residual: classify dead space.
    let cls = post_residual / 10; // decade class 0..10
    match cls {
        0 => score -= 60.0,          // gap <= 9: nearly unusable, good packing
        1 | 2 => score += 5.0,       // awkward mid gap
        3 | 4 => score += 10.0,      // 30-49 gap: risky
        5 | 6 => score += 15.0,      // 50-69: large waste
        _ => score += 20.0,          // 70+: terrible placement
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10,20,25,50) are reusable "harmonic" slots.
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer tighter bins overall: closeness of fill to capacity.
    let fill = (bin_capacity - bin_residual) as f64;
    score -= fill * 0.6;

    // Mean-residual coupling: placing into a bin below mean residual
    // (tighter than average) is favored.
    score += (mean_residual - pr) * 0.4;

    // New-bin candidate: penalize opening a bin unless the item is huge
    // or no tight fit exists; keep it slightly worse than decent fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0
            - (item_size as f64) * 0.3
            - progress * 20.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // room for a harmonic pair in a fresh bin
        }
    }

    // Early stream: mild bias to consolidate into few bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // Gaps below the smallest plausible item (<= ~10) are pure waste; scale
    // the penalty so a 1-unit dead space is worse than a 40-unit gap.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += (11 - post_residual as f64) * 25.0; // unusable sliver
        } else if post_residual <= 20 {
            score += (21 - post_residual as f64) * 8.0; // marginal gap
        } else if post_residual == bin_capacity {
            // brand-new empty bin candidate: give it a neutral-ish baseline
            score += 30.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits generally: closeness of post_residual to 0.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (opening a bin is costly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // encourage filling existing ones; when few are open, be lenient.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += 15.0 * bin_pressure; // penalize opening bins when many open
    } else {
        score -= 5.0 * bin_pressure;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits (small miss), mild penalty for stranding it.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling the emptiest-ish bins less, tightening full ones first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Slight stream-progression tightening: later in the stream, be greedier
    // about perfect fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual == 0 {
            score -= 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect follow-up fit bonus: penalize score when next item fits snugly.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally to wasted pairing.
        score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is very tight
    // or the lookahead suggests a chain of large items.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * tightness;
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 30.0; // big items coming: fresh bin useful
        }
    }

    // Progress-based mild adjustment: as stream ends, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Deviation from mean residual: prefer bins that keep residual spread balanced,
    // but slightly favor emptier-than-average bins for large items.
    let dev = bin_residual as f64 - mean_residual;
    if item_size > 50 {
        score += 0.1 * dev;
    } else {
        score -= 0.05 * dev;
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 20.0 * (1.0 - progress);
        score += 20.0 * progress;
        // If no open bin fits well, new bin is reasonable.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Late-phase consolidation bonus for using existing bins.
        score -= 12.0 * progress;
    }

    // Slight preference for bins whose residual is close to a multiple-friendly size.
    let r = post_residual as f64;
    if r >= 20.0 && r <= 60.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear tightness reward: quadratic+quartic shaping of post_residual.
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * cap * (0.5 + progress);
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Reward exact-ish fits strongly (near-zero post residual).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0 * (1.0 - pr / 10.0);
    }

    // Dead-space penalty: residuals too small for typical future items.
    let dead_zone = 1.0f64.min(pr / 10.0);
    score += 8.0 * (1.0 - dead_zone) * (1.0 - dead_zone) * (0.4 + 0.6 * progress);

    // Lookahead: reward if next item fits the post residual, penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - (pr - nxt) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (1.0 - progress) * (nxt - pr) / nxt.max(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate handling: penalize opening a new bin when it wastes
    // potential, scaled by how many bins are open and mean residual.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score += 4.0 + 10.0 * waste * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0 * (1.0 - (mean_residual / cap).powi(2));
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in some residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual / 10; // integer division: harmonic class of width 10
    match class {
        0 => score -= 8.0,          // near-perfect fit: excellent fill
        1 => score -= 3.0,          // small dead space, still useful
        2 => score += 1.5,          // mid-low: mildly awkward
        3 => score += 4.0,          // awkward dead zone (~30-39)
        4 => score -= 2.0,          // ~40-49 leaves room for mid items
        5 => score += 3.0,          // half-full: mediocre
        6 => score -= 1.0,          // ~60-69: still flexible
        7 => score += 2.5,
        8 => score -= 0.5,
        9 => score += 1.0,
        _ => score += 0.0,
    }

    // Fractional coupling: reward when post_residual is a good divisor-like match
    // for the lookahead item (next item fits exactly or closely).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let waste = pr - nx;
            score -= 10.0 - waste.min(10.0); // lookahead perfect fit strongly rewarded
        } else {
            // next item will need another bin anyway; slight penalty for large leftover
            score += (nx / cap) * 4.0;
        }
    } else {
        // last item: minimize residual as hard as possible
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "tight" — filling it is good (keeps loose bins available).
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= diff * 0.15;
    } else {
        score += (-diff) * 0.05;
    }

    // New-bin candidate handling: empty bin gets a calibrated handicap so that
    // it only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 14.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: new bin is correct
        }
    }

    // Tight-fit bonus: item consuming most of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 {
        score -= 6.0;
    } else if fill > 0.75 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that cannot fit the next item is dead space unless tiny.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Reward residual that exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Prefer bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize mildly so it is chosen only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: good chaining
            score -= 150.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            score += 80.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Prefer tight fits relative to mean residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Mild penalty for very full bins when many bins open (keep flexibility early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && tightness < 0.15 {
        score += 30.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (consolidating fuller bins)
    score -= 10.0 * (mean_residual - post_residual as f64) / 100.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 800.0;
        } else {
            score += 350.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 8.0 * tightness;

    // Near-perfect fill bonus: residual below the minimum item size is dead space eliminated
    if post_residual < 10 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mildly prefer tighter ones (already via post_residual)
        score += 1.0;
    }

    // Lookahead coupling (k=2): prefer bins whose leftover can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            score += 3.0; // creates a gap the next item cannot use
        }
        // Chain fit: next item would exactly consume the leftover
        if next_item_size == post_residual {
            score -= 4.0;
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        // Default reluctance to open a new bin while open ones fit
        score += 6.0;
        // But if placing in any open bin would strand space the next item needs,
        // opening a fresh bin becomes attractive
        if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating nearly-empty bins
        let t = step_index as f64 / (total_items.max(1) as f64);
        if t > 0.85 {
            score += 5.0 * (t - 0.85) / 0.15;
        }
    }

    // Global state: when mean residual across open bins is high, prefer consolidating
    // into fuller bins (higher mean residual => open bins are emptier => penalize spread)
    let mean_ratio = mean_residual / cap;
    score += 2.5 * mean_ratio * (post_residual as f64 / cap);

    // Time horizon: early in stream, slightly favor keeping bins balanced;
    // late in stream, prioritize closing bins out completely
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * (1.0 - t) * (1.0 - mean_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = post * (1.0 + 0.8 * progress * pr);

    // Smooth tightness term: reward near-full fills (small post_residual) more
    // strongly as the stream progresses.
    let tightness = (1.0 - pr).powi(2);
    let reward = -30.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space: unusable residuals below the minimum item size (1)
    // are worthless; smooth sigmoid-like penalty around small residuals.
    let dead = 20.0 / (1.0 + (post / 8.0).powi(2));

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt) / cap;
        -15.0 * (-fits * 4.0).exp() * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 && bin_residual < cap {
        -25.0
    } else {
        0.0
    };

    // Mild crowding penalty: spreading across many open bins wastes capacity.
    let crowd = 1.5 * open_bins_count as f64 * pr;

    // Mean residual alignment: prefer bins whose residual is near the mean (balance).
    let align = 0.05 * (post - mean_residual).abs();

    base + reward + dead + lookahead + last_chance + crowd + align
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes capture
    // which item-size cohorts (10..80) can still tile the leftover space.
    let pr = post_residual;
    let class = pr % 10;

    // Reward residuals in "harmonic" classes that commonly pair with
    // arriving item sizes (multiples of 10 are the most reusable).
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if class == 0 {
        score -= 12.0; // residual is a multiple of 10 -> highly reusable
    } else if class == 5 {
        score += 6.0;  // half-class: only 5 or 15-sized follow-ups fit well
    } else {
        score += (10 - class) as f64 * 0.8; // penalize odd leftovers
    }

    // Integer-division thresholds: how many "typical" items (size 10..40)
    // could still fit in the post residual.
    let fits_small = pr / 10;
    let fits_mid = pr / 25;
    score -= fits_small as f64 * 3.0;
    score -= fits_mid as f64 * 2.0;

    // Lookahead coupling: does next_item_size land on the same harmonic class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strongly prefer this bin if classes align.
            let align = (pr % 10) == (next_item_size % 10);
            score -= if align { 18.0 } else { 8.0 };
            // Bonus for leaving a multiple-of-10 residual after the lookahead.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot follow here: penalize tight fills.
            score += 7.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to the average residual (poor fit everywhere else).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score = (bin_capacity - item_size) as f64 + 5.0;
        let tight = mean_residual < item_size as f64 * 1.15;
        if tight {
            score -= 20.0; // existing bins are too full -> new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.25 {
            score += 10.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.4;

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, the historic min item,
    // but sizes go down to 1 here, so treat gaps < 12 as "dead" and heavily penalize
    // only when nothing else can use them).
    if post_residual > 0 {
        let dead_threshold = 12.0f64;
        if (post_residual as f64) < dead_threshold {
            // Waste penalty proportional to how close the gap is to useless
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
        // Reward near-perfect fits
        if post_residual == 0 {
            score -= 25.0;
        } else if post_residual <= 5 {
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    // and this is a new-bin candidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = 15.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        score += pressure + 10.0 * progress;
        // But if the item would leave a tight residual in a new bin anyway,
        // opening a fresh bin is fine (it will pack future items).
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit relative to bin)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 12 {
        // this placement creates a gap the next item cannot use: extra penalty
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly matches
    // the next item size (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / 100.0).max(0.0);

        // Penalize dead space the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward leaving room exactly usable later.
            score -= 0.3 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize near-full bins only lightly; waste is what matters.
    if post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate: keep it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Mild late-stream consolidation: prefer reusing bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Strong penalty for large dead space (unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // perfect-ish fit bonus
    } else if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.8; // wasteful gap
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = post_residual as f64; // for new bin, post_residual = C - item
        score += 20.0; // base cost of opening a new bin
        if fit_quality < 20.0 {
            score += 30.0; // item nearly fills a fresh bin: fine
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // plenty of slack elsewhere: opening new bin is wasteful
        }
    } else {
        // Lookahead: reward if next item fits the post residual (chaining).
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 12.0;
            } else if next_item_size > bin_residual {
                // next item can't fit here anyway; mild bonus for dumping current item here
                score -= 4.0;
            } else {
                score += 6.0; // next item would fit now but not after placement
            }
        }
    }

    // Time horizon: early on, be conservative about opening bins; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += (1.0 - progress) * 15.0; // discourage new bins early
    } else {
        score -= progress * 5.0; // encourage using open bins late
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 && !is_new_bin {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a good dump target.
    if !is_new_bin {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    score += 18.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 14.0 * norm_pr * (1.0 - progress);

    // Penalize tiny residuals (dead space), more so late in stream
    let tiny = (1.0 - norm_pr).max(0.0);
    score += 10.0 * tiny * tiny * tiny * (0.5 + progress);

    // Last-chance bonus: prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Prefer reusing bins over opening new ones, scaled by open count
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in reusable classes
    // (multiples of 10 / large chunks), penalize tiny unusable slivers.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer division class (0..10)
        let remainder = (pr % 10) as f64;
        // Penalize the ragged part of the residual (dead-space risk)
        score += remainder * 1.5;
        // Reward coarse classes: residuals that can host mid-size items
        if class >= 2 { score -= (class as f64) * 2.0; }
        if pr <= 5 { score += 25.0; }          // near-dead sliver
        if pr > 0 && pr < 10 { score += 15.0; } // unusable for most items
    } else {
        score -= 30.0; // perfect fit: zero waste, best outcome
    }

    // Lookahead: does this placement leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // chain-friendly placement
            // extra reward if next item fits snugly in the new residual
            let snug = (post_residual - next_item_size) as f64;
            score -= (10.0 - (snug % 10.0)) * 0.5;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere here anyway; residual class matters less
            score += 3.0;
        } else {
            score += 10.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        let pressure = open_bins_count as f64 / 8.0;
        // small items: better to fill existing space; large items may justify a fresh bin
        let size_pull = (item_size as f64) * 0.3;
        score += 55.0 - size_pull - pressure * 10.0 - frag * 20.0;
        if item_size >= 60 { score -= 25.0; } // big items pair poorly with leftovers
    }

    // Stream maturity: late in stream, consolidate; early, allow exploration
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mild preference to spread load when many bins are open
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual that cannot fit even the smallest plausible item (<= 12)
    // is nearly guaranteed waste.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        // Small-but-usable gaps: moderate penalty scaled by how little
        // of the gap is actually exploitable.
        score += (25.0 - post_residual as f64) * 1.2;
    }

    // Reward near-perfect fits (tight packing is the core objective).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 8.0 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize if the next item can NOT use the leftover space (dead space risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening
    // new ones and encourage closing out existing residual capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += bin_pressure * 0.15;

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when
    // the current item fits poorly everywhere. Penalize the empty-bin
    // candidate proportionally to how many bins could already fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 55.0 + 10.0 * fitting_bins_count as f64;
        } else {
            // No open bin fits: opening a new bin is necessary; make it
            // attractive but keep a mild preference for tight future fits.
            score -= 20.0;
        }
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it is already "tight" — favor finishing it off.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.3;
    } else {
        score += (-residual_gap) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward when the next item could still fit with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0);
    }
    // Penalize leftovers that are too small for the next item (likely dead space),
    // scaled by how small they are relative to typical item sizes.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits relative to the mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(25.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(25.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream,
    // and when a reasonable fit exists elsewhere; allow it late when
    // post_residual would be large (poor fit) to preserve flexibility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 40.0 * (1.0 - progress);
        if post_residual as f64 > 60.0 {
            score -= 25.0 * progress;
        }
    }

    // Mild preference for keeping many open bins consolidated.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in wasted space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 60.0;

    // Penalize leaving residuals that are too small for typical future items
    // but reward residuals that are "dead" only when unavoidable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead slivers are bad
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item fits, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * (open_bins_count as f64 + 1.0));
    score -= pressure * 30.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize new-bin usage less later? Actually: keep bins consolidated early,
    // allow spreading late). Encourage compactness early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize based on progress and current bin count.
        score += 35.0 + 50.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual here is huge for new bin),
        // the base post_residual already favors it; add escape hatch:
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild bonus for filling bins that are already mostly full.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
