    let waste_curve = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * waste_curve * (0.3 + 0.7 * progress);

    // Reward tight fits via smooth quadratic term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

