    // Lookahead: if next item fits the post-residual, reward strongly (smooth)
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 20.0 * fit_frac * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize blocking the next item, scaled by how much it misses
        let miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * miss * miss;
    }

    // Mean residual coupling: prefer bins near the mean (keeps spread balanced)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Penalize opening new bins as stream progresses (soft)
    if bin_residual == bin_capacity {
