    let post = post_residual as u32;
    let class = post % 10;
    // Residuals that are "dead" (too small for smallest plausible item) are heavily penalized
    if post < 10 {
        score += 40.0;
    } else if post < 20 {
        score += 15.0;
    }

    // Reward residuals that are harmonic multiples of common size classes
    if post % 20 == 0 {
        score -= 8.0;
    } else if post % 25 == 0 {
        score -= 6.0;
    } else if post % 10 == 0 {
        score -= 4.0;
    } else {
        // odd/awkward classes get a small penalty scaled by distance to next multiple of 10
        score += (10 - class) as f64 * 0.4;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let leftover = post - next_item_size;
            if leftover % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: mildly penalize wasting a good bin
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Tight fits rewarded: near-zero post residual with the item being large
    let tightness = 1.0 - (post as f64) / cap;
    score -= tightness * 6.0;

    // Late in stream: prefer closing bins tightly, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins open or stream is late
        score += 5.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * progress;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
