        score += 18.0 - 12.0 * large;
        // if next item is huge and post_residual (= C - item) is tiny, opening
        // a new bin wastes capacity; penalize further
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Late in the stream, consolidate into fewer bins to avoid stragglers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / (total_items.max(1) as f64)).min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong bonus when the item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small useless post residuals lightly, reward exact fits heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a bin is only attractive when the item
    // is large and the lookahead also fits well in the fresh space.
    if bin_residual == bin_capacity {
        let open_penalty = 15.0 + 0.5 * open_bins_count as f64;
        score += open_penalty;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // lookahead fits in the fresh bin
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // lookahead would be stranded in a fresh bin
        }
        // Late in the stream, avoid spreading out: prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits this bin's post-residual,
    // this placement is doubly valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space relative to lookahead: penalize proportionally.
        score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Global state: prefer bins whose residual is below mean (denser bins),
    // gently steering toward filling fuller bins first.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Mild preference to keep number of open bins from exploding.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (1.0 - progress);
    score += 20.0 * poly;

    // Penalize dead space more strongly late in the stream (smooth cubic progress)
    score += 10.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Slight preference for bins deviating from mean residual (balance pressure)
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.1 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into 10-wide bands
    let band = post_residual / 10;
    // Small post_residual (tight fit) is good; large dead space is bad
    score += match band {
        0 => -30.0,                       // near-perfect fit
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        4 => 15.0,
        5 => 22.0,
        6 => 30.0,
        7 => 38.0,
        8 => 46.0,
        _ => 55.0,
    };

    // Harmonic bonus: post_residual exactly divisible by common small sizes
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50].iter() {
            if post_residual % d == 0 {
                score -= 6.0;
                break;
            }
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin -> strong reward, scaled by closeness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - (slack / bin_capacity as f64) * 10.0;
        } else {
            // next item won't fit -> penalize proportional to overshoot class
            let over = (next_item_size - post_residual) / 10;
            score += (over as f64) * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // no open bin offers a decent fit (post_residual would leave big dead space)
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so tight fits win
        score += 5.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // many open bins with slack mean we should use them instead
        if mean_residual > item_size as f64 {
            score += 12.0;
        }
    }

    // Penalize bins far from mean residual (fragmentation of bin states)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins as stream progresses
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (min size 1..100
    // but small gaps are hard to fill) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - (post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Smooth tightness reward for usable gaps.
        score -= 15.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 25.0; // chained perfect fit
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item cannot use this bin's gap
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream.
        score += 10.0 + 12.0 * bin_pressure + 15.0 * (1.0 - progress);
        // Only attractive if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Slight reward for filling existing bins as stream progresses.
        score -= 5.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.15 * ((mean_residual - bin_residual as f64).abs()) * 0.1
        - 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the leftover space: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack.min(200.0);
    }
    // Leftover space too small for the next item: penalize dead space, worse when small.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual: keeping bins balanced is good.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or current bins are very full on average.
    if bin_residual == bin_capacity {
        let fullness = mean_residual / bin_capacity as f64;
        score += 300.0 - item_size as f64 * 2.0 - fullness * 200.0;
    }

    // Late in the stream, prefer tighter packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small dead space (< 10) that no future item (min size 1..100) may use,
    // but only mildly since small items exist.
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // the item is large relative to capacity (good initial occupancy) and
    // existing bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 30.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 20.0 * (1.0 - progress);
        // Large items seed new bins well.
        penalty -= 0.3 * item_size as f64;
        // If mean residual of open bins is small, open bins are saturated -> new bin is fine.
        penalty -= 0.15 * mean_residual;
        // Lookahead: if the next item is large and this bin would leave a matching gap, ok.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            penalty -= 15.0;
        }
        score += penalty.max(0.0);
    } else {
        // Lookahead synergy: reward bins whose post-residual matches the next item size.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 12.0 * (-gap / 20.0).exp();
        }
        // Prefer bins with residual below mean (pack tight bins first, keep loose bins flexible).
        score += 0.1 * (residual - mean_residual);
    }

    // Mild global pressure: many open bins -> consolidate into existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    // Tighter packing valued more as stream progresses
    score -= 0.9 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (1.0 + 2.0 * t * t);
    // Cubic dead-space penalty: small residuals late in stream are costly
    score += 0.35 * fit_ratio * fit_ratio * fit_ratio * cap * (0.5 + t);
    // Reward near-perfect fits smoothly
    score -= 6.0 * (1.0 - fit_ratio).powi(4);

    // Lookahead coupling: smooth interaction of post_residual with next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        // Penalize when next item neither fits nor fills bin (smooth quadratic)
        score += 1.2 * gap_norm * gap_norm * cap;
        // Reward when next item exactly fills post_residual (smooth Gaussian-like)
        score -= 8.0 * (-40.0 * gap_norm * gap_norm);
        // Late-stream lookahead weight
        score += 0.8 * t * (pr - nx.min(pr)) / cap * cap * 0.01;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * t;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by residual waste
        score += 0.15 * (fitting_bins_count as f64).ln() * fit_ratio * cap;
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 0.5 * dev * dev * cap;

    // Open bins pressure: with many open bins, favor consolidation
    let ob = open_bins_count as f64;
    score += 0.05 * ob * fit_ratio * cap * (0.5 + 0.5 * t);

    // New-bin candidate handling: empty bin gets smooth adaptive threshold
    if bin_residual == bin_capacity {
        let threshold = cap * (0.35 + 0.4 * t * t) + 0.2 * mean_residual * t;
        score = threshold + 0.3 * (1.0 - t) * cap;
        if fitting_bins_count == 1 {
            score += 25.0; // never open new bin if this is the only fitting one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify by capacity fraction bands.
    let frac = post_residual as f64 / cap_f;
    if frac == 0.0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if frac < 0.05 {
        score -= 20.0;
    } else if frac < 0.15 {
        // Small dead space, mildly bad.
        score += 10.0 * (0.15 - frac) * 10.0;
    }

    // Integer-division thresholds on post_residual: residues mod 10.
    let rem = post_residual % 10;
    score += rem as f64 * 0.8;

    // Coupling with next item: reward if next item fits exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            if next_left == 0 {
                score -= 25.0;
            } else if next_left < 10 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize if residual becomes unusable waste.
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current residual is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (mean_residual / cap_f).min(1.0);
        // Prefer new bin when this bin's fit is bad relative to mean residual.
        if post_residual as f64 > mean_residual * 0.9 {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 8.0 + 6.0 * (1.0 - waste_pressure);
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 15.0;
    } else if tightness > 0.7 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Items are >= 10, so a post_residual in 1..10 is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that only a small item could use, but reward
    // gaps large enough to plausibly fit future items.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: opening a new bin should only win when this bin's fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Mild progression term: late in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Deviation from mean residual: bins far tighter than average are precious.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near matches within a tolerance band.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 25.0 * (1.0 - gap / 10.0);
        }
    }

    // Penalize small dead space that likely cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        let waste_ratio = dead / next_item_size as f64;
        score += 20.0 * waste_ratio.min(1.0);
    }

    // Penalize zero residual less than proportional dead space (perfect fill).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean residual; penalize loose bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New empty bin candidate: make it unattractive unless item is huge and
    // no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Early in the stream, allow opening bins more freely to build a pool.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes wasted space superlinearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize new bins early/mid stream; accept them when residuals are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // plenty of space elsewhere; don't open a new bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: reward leaving residual that can host the next item exactly or partially.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 8.0;
            if (post_residual as f64 - nxt).abs() < 1.0 {
                score -= 12.0;
            }
        } else if post_residual > 0 {
            // penalize dead space that next item cannot use
            score += (nxt - post_residual as f64) * 0.3;
        }
    }

    // Prefer filling bins with small residuals over large ones when ties occur.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Mild diversity pressure: many open bins -> prefer consolidating into low-residual bins.
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Global residual alignment: favor bins below mean residual (already tight).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Dead-space penalty: small post-residuals relative to item range are wasteful.
    let dead = (norm_pr - 0.2).max(0.0);
    score += 25.0 * dead * dead * (1.0 - progress);

    // Reward bins whose residual matches the next item (smooth coupling).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 12.0 * (1.0 - diff).max(0.0) * (1.0 - progress);
    } else {
        // Last item: strongly prefer zero post-residual.
        score += 10.0 * norm_pr;
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild penalty for many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Smooth deviation from mean residual: prefer bins near the mean (balanced fills).
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin when it would waste space,
    // but allow it when item barely fits no open bin well (post_residual small anyway).
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals that are "awkward" sizes.
    // Class A: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class B: post_residual divisible by 10 (typical item granularity) -> reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Class C: small dead space (1..=9) is nearly unusable -> heavy penalty.
        if post_residual < 10 {
            score += 25.0;
        }
        // Class D: mid-range residual (10..=30) can hold small items -> mild reward.
        if post_residual >= 10 && post_residual <= 30 {
            score -= 4.0;
        }
        // Class E: integer division threshold — residual >= 50 is half-empty, fine.
        if post_residual / 25 >= 2 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves awkward remainder
            let nxt = (post_residual - next_item_size) as f64;
            if nxt < 10.0 && nxt > 0.0 {
                score += 6.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's remainder: residual likely wasted
            score += (post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // spread pressure: prefer bins that are relatively full vs mean residual
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // Prefer filling nearly-full bins (tight packing) via capacity fraction coupling.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 20.0;

    // New-bin candidate: penalize opening a new bin unless remaining open bins
    // are all poorly utilized and stream is early enough to amortize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual / cap;
        let mut penalty = 35.0;
        // opening new bins late is expensive; early is cheaper
        penalty += progress * 30.0;
        // if open bins have lots of residual, discourage new bin
        penalty += avg_waste * 25.0;
        // if this is the only viable bin for the item, new bin is fine
        if fitting_bins_count == 0 {
            penalty -= 50.0;
        }
        score += penalty;
    }

    // Slight preference for compacting many open bins as count grows.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidation when many bins open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        if item_size >= 70 && post_residual < 10 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Penalize if next item cannot use the post residual (dead space likely).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: prefer bins close to mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
