pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * (post_residual as f64).sqrt();

    // Penalize leaving awkward gaps that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space below minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 2.0; // next item won't fit here; mildly deprioritize
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: when many bins are open, consolidate; when few, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 {
        score -= 1.5 * mean_residual / (open_bins_count as f64).sqrt();
    }
    // Early in the stream, be more willing to open new bins; later, consolidate.
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when no open bin fits well or mean residual is low.
    if bin_residual == bin_capacity {
        let escape_bonus = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 8.0 - escape_bonus - 3.0 * (mean_residual / bin_capacity as f64).min(1.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // new bin can host a chain of large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: minimize waste, with stream-progress-dependent curvature
    let mut score = pr as f64 * (1.0 + 0.5 * t * t);

    // Smooth non-linear penalty for small-but-nonzero residuals (dead space)
    // peaks near x ~ 0.15 via a smooth bump
    let bump = (-(x - 0.15) * (x - 0.15) / 0.02).exp();
    score += 12.0 * bump;

    // Reward tight fits: smooth coupling of fill ratio with progress
    let fill = 1.0 - x;
    score -= cap * fill * fill * (0.3 + 0.7 * t);

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits_next = (post_residual as f64 - next_item_size as f64).max(0.0);
        let fit_quality = (fits_next / cap) * (1.0 - (nx - x).abs());
        score -= 8.0 * fit_quality;
        // penalize if next item cannot use leftover
        if next_item_size as u32 > post_residual {
            score += 4.0 * nx;
        }
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x * x);
    }

    // Mean-residual coupling: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: smooth penalty growing with number of open bins,
    // relaxed when the item would leave awkward small residual elsewhere
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += 20.0 * openness * (1.0 - 0.5 * t);
        // but if this item is large (fills new bin well), soften penalty
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Slight penalty for many fitting bins competing (favor diversity of choice)
    score += 0.5 * (fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    // Class 1: leftover <= 10 -> still very useful (fits smallest items)
    // Class 2: leftover <= 25 -> moderately useful
    // Class 3: leftover <= 50 -> poor
    // Class 4: leftover > 50 -> dead space
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    } else if post_residual <= 50 {
        score += 8.0;
    } else {
        score += 20.0;
    }

    // Modulo harmonic classes on post_residual: multiples of 10 are "aligned"
    // with typical item sizes, making the leftover reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that matters too
            let chain_left = post_residual - next_item_size;
            score -= 8.0 + (chain_left as f64).min(20.0) * 0.4;
        } else {
            // next item will not fit here: penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.25;
        }
    }

    // Integer-division threshold on bin fill level (harmonic capacity fractions)
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 12.0; // strongly prefer completing nearly-full bins
    } else if fill >= 0.5 {
        score -= 4.0;
    } else if fill < 0.25 && open_bins_count > 2 {
        score += 10.0; // avoid scattering items across barely-used bins
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits (smaller post residual already does this)
        score += (fitting_bins_count as f64 - 1.0).min(4.0) * 0.5;
    }

    // New-bin candidate logic: an empty bin has huge residual; make it attractive
    // only when the item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // large items start fresh bins more readily; small items should reuse
        let item_frac = item_size as f64 / bin_capacity as f64;
        let pressure = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score -= item_frac * 40.0 + pressure * 30.0 + progress * 5.0;
        // but never let a fresh bin beat a perfect fit in an open bin
        if post_residual == 0 {
            score += 100.0; // this branch won't trigger for empty bin, safety
        }
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate
    if open_bins_count > 4 && mean_residual > 40.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Gaps below ~10 are nearly dead space; gaps 10..30 are only usable by small items.
    let dead = if post_residual == 0 {
        0.0 // perfect fit: reward strongly
    } else if post_residual < 10 {
        40.0 // unusable dead space
    } else if post_residual < 30 {
        12.0 // hard to reuse
    } else if post_residual < 50 {
        4.0
    } else {
        0.0
    };
    score += dead;

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // next item likely wasted
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the new-bin option via its own score path).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64 * 0.1;
    }

    // Prefer bins with residuals close to the item (tight fits).
    score += 0.1 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    // Slight preference for bins below mean residual (filling emptier bins less).
    if (bin_residual as f64) < mean_residual {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match between post_residual
    // and the next item's size (this bin becomes perfectly reusable).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch, scaled by how far the next item misses.
            score += diff * 0.6;
            // If the next item cannot fit into the post-residual, extra penalty
            // unless post_residual is small (near-full bin is fine).
            if (post_residual as i64) < (next_item_size as i64) {
                score += diff * 0.4;
            }
        }
        // Bonus when this placement leaves room for the next item while
        // current fit is also tight.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: only current fit matters; reward tight packing.
        score -= 10.0;
    }

    // Reward tight current fit (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize bins whose residual deviates strongly from the mean residual:
    // prefer keeping residuals homogeneous so future items fit somewhere.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when the stream is
    // early; encourages consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 3 && progress < 0.5 {
        score += 2.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no good
    // fit exists among open bins. An empty bin wastes nothing now, but
    // opening bins is costly, so keep a moderate default score.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the next item is large and no open bin will hold both,
        // a fresh bin is fine.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linear reward.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver (items >= 1, but tiny gaps are wasteful)
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0); // mild penalty, plenty of options
    }

    // Lookahead: if the next item fits into the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here anyway; slight penalty for large leftovers
            score += 3.0;
        }
    }

    // Prefer filling bins that are already relatively full vs. leaving many shallow bins.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio * fill_ratio;

    // Global state coupling: if mean residual is high, we have room to spare —
    // be pickier (penalize loose fits); if mean residual is low, accept tighter fits.
    let mean_dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_dev;

    // Time horizon: early in the stream, be more willing to open bins (penalize
    // cramming less); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Many open bins: discourage opening new bins / spreading items thin.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // but early in stream with few bins, opening is fine
        if open_bins_count < 3 && progress < 0.3 {
            score -= 6.0;
        }
        // never open a new bin if a decent fit exists elsewhere
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * progress * progress;
    score += 20.0 * poly;
    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - pr;
    score -= tightness * tightness * (1.0 + progress) * 10.0;
    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > post_residual {
        score += 5.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        let waste = (post_residual - next_item_size) as f64;
        score -= (1.0 - waste / bin_capacity as f64) * 8.0 * (1.0 - progress);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }
    // New-bin candidate: prefer it when residuals are fragmented
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) + mean_residual / 10.0;
    }
    // Penalty for spreading across many open bins with high mean residual
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // class sizes (e.g. multiples of 10, 20, 25) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        if pr % 50 == 0 { score -= 25.0; }
        else if pr % 25 == 0 { score -= 15.0; }
        else if pr % 20 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // small unusable dead space penalty (harmonic bottom class)
        if pr < 10 { score += 30.0 * (10 - pr) as f64; }
        // mid-range residuals are the most flexible
        if pr >= 20 && pr <= 60 { score -= 6.0; }
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward, scaled by how tightly it fits
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - 0.15 * slack;
            // harmonic bonus if next item lands post-residual on a round class
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here: penalize bins whose residual is
            // just barely too small (wasted potential)
            let gap = (next_item_size - pr) as f64;
            if gap <= 10.0 { score += 10.0; }
        }
    } else {
        // last item: any bin works, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a bin is usually wasteful unless
    // the item is large and no good residual class exists among open bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // large items benefit from a fresh bin (avoid fragmenting old bins)
        if item_size >= 51 { score -= 30.0; }
        if item_size >= 76 { score -= 15.0; }
        // early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if many bins already open, discourage one more
        score += 2.0 * open_bins_count as f64;
        // if open bins are on average nearly full, a new bin is fine
        if mean_residual < 15.0 { score -= 10.0; }
    } else {
        // prefer filling existing bins when they are relatively full
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Prefer bins that are already tighter than the average open bin.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // use it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base penalty: prefer filling existing bins when fits are decent.
        score += 6.0;
        // But if the lookahead item cannot fit in the resulting gap anyway,
        // opening a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
        // Late in the stream, avoid spawning bins that will stay nearly empty.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.9 {
            score += 8.0;
        }
    }

    // Mild pressure from number of open bins (ties broken toward consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strong reward (minimize score heavily).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Next item can still be placed here: mild reward proportional to snugness.
            score -= 50.0 * (1.0 - (post - next_item_size as f64) / cap);
        } else {
            // Dead space: post residual too small for the next item.
            // Penalize proportionally to how wasted the space is.
            let waste = post / cap;
            score += 80.0 * waste;
        }
    }

    // Penalize small unusable residuals relative to mean residual of open bins.
    if post > 0.0 {
        let rel = post / mean_residual.max(1.0);
        if rel < 0.5 {
            score += 40.0 * (1.0 - rel);
        }
    }

    // Last chance bin: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): make it moderately unattractive so it is
    // only chosen when all open fits are poor, but attractive when the item
    // is huge relative to typical residuals (avoid fragmenting big items).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score = cap * 0.75 - big_item_bonus + 100.0 * progress;
        // If no open bin fits at all, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Prefer bins whose residual is close to the item (snug fit overall).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Penalize dead space: post_residual too small to fit typical items
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // next item fits current bin but not after placing current item
            score += 5.0;
        }
        // penalize leaving exactly awkward space for next item
        if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Time horizon: early on, prefer opening new bins less (consolidate);
    // late in stream, avoid creating tiny residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus scaling with open bins and progress
        score += 15.0 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // early stream: new bins cheaper to build capacity for future items
        score -= (1.0 - progress) * 12.0;
        // if no open bin fits well, new bin more attractive
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // prefer bins with residual close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // crowded regime: prefer reusing bins over opening new ones
        if open_bins_count > 4 {
            score -= 6.0;
        }
    }

    // Reward filling bins more than half full
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Small penalty proportional to item size to prefer placing large items in large-residual bins
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual

    // Base: penalize leftover space, but with non-linear (quadratic/cubic) shaping
    let mut score = pr as f64 * (1.0 + 0.5 * x * x) - 20.0 * (1.0 - x).powi(3);

    // Smooth coupling of post_residual with stream progress:
    // early on, tolerate loose fits; later, punish residual more sharply
    score += pr as f64 * (0.6 * progress + 0.9 * progress * progress);

    // Reward tight fits (small post-residual) increasingly with progress
    score -= (cap - pr) * (0.3 + 0.5 * progress) * (x * x);

    // Dead-space penalty: residual too small for any plausible future item (1..100)
    let dead = ((20.0 - x * cap).max(0.0)) / 20.0;
    score += 25.0 * dead * dead * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // Lookahead: if next item fits exactly in post-residual, big reward
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= x * cap {
        score -= 8.0 * (1.0 - (next_item_size as f64 / (x * cap + 1.0)));
    }

    // New-bin candidate: mildly discourage opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 10.0 * x;
    }

    // Slight preference for bins below mean residual (keeps big holes open)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "small" class (<= 10) are nearly perfect; reward tight fits.
    let tight = post_residual <= 10;
    if tight { score -= 25.0; }

    // Modulo-class penalty: leftovers that are awkward (not multiples of 10
    // and not >= 50) are dead space; penalize mildly.
    let awkward = post_residual % 10 != 0 && post_residual < 50;
    if awkward { score += 6.0; }

    // Reward leftovers that can host common small classes (10,20,25,50).
    let reusable = post_residual == 50 || post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0;
    if reusable && post_residual > 0 { score -= 8.0; }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another residual; prefer classes
        // where the chain residual is again reusable.
        let chain = post_residual - next_item_size;
        if chain <= 10 { score -= 15.0; }
        if chain % 10 == 0 { score -= 5.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize bins that would strand it
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item is large and no open bin gives a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a bin unless item is huge relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * frac;
        // If many bins can fit the item, opening a new one is wasteful.
        score += 3.0 * fitting_bins_count as f64;
    }

    // Prefer fuller bins overall (lower residual relative to mean).
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in the stream, consolidate: fewer open bins is better.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (assume min size ~1..10)
    // are wasted; penalize heavily with a non-linear cliff.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // Moderately risky gap: could fit small items, but unlikely
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (post_residual near zero but usable)
    if post_residual == 0 {
        score -= 80.0; // perfect fill
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // If lookahead item fits exactly in the post residual, big bonus
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        let after = post_residual - next_item_size;
        if after < 10 && after > 0 {
            score += 10.0; // but avoid creating a dead gap for the item after
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // this bin becomes dead space for the next item
        score += 18.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 6.0;
        // but if this bin would be the only fitting one, new bin is fine
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    } else {
        // slight preference for fuller bins (lower residual)
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late in stream: tighten everything, avoid spreading
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + item_size as f64 * 0.5;
    }
    // Next item fits into the remaining space (good lookahead).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.4;
    }
    // Next item does NOT fit: penalize proportionally to wasted potential.
    else if next_item_size > 0 {
        score += (next_item_size as f64) * 0.25;
    }

    // Prefer bins whose residual is tighter than the average open bin.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: baseline high cost; only attractive when all open
    // bins would leave bad fits (large post_residual relative to mean).
    if bin_residual == bin_capacity {
        let mut nb = 55.0;
        // If the best alternative is poor (post_residual far above mean),
        // reduce the new-bin score so it can win.
        nb -= (post_residual as f64) * 0.0; // keep neutral on itself
        if next_item_size > 0 && fitting_bins_count > 0 {
            // slightly encourage new bin if item nearly fills a fresh bin
            if item_size as f64 >= 0.9 * bin_capacity as f64 {
                nb -= 30.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 20.0;
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that cannot fit the next item (lookahead waste)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }
    // Reward leaving exactly enough room for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last chance bonus: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening new bins when many bins can fit the item
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless current bin residuals are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 60.0 + 50.0 * (1.0 - progress) - 0.8 * fragmentation.min(50.0) as f64;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild penalty for using bins with much larger residual than the mean (preserve flexible bins)
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.3 * diff;
    }

    // Late-stream consolidation: prefer filling bins more completely over time
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * norm_pr * norm_pr * (1.0 + progress)
        - 20.0 * norm_pr * (1.0 - progress) * progress;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are open and mean residual is high
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + 0.05 * mean_residual;
    }

    // Lookahead: reward leaving space exactly matching next item
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - diff / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space class boundaries: 0, <=10, <=20, <=33, <=50, >50
    let class_penalty = if post_residual == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post_residual <= 10 {
        -35.0 // near-perfect: small item could still slot in
    } else if post_residual <= 20 {
        -10.0
    } else if post_residual <= 33 {
        8.0
    } else if post_residual <= 50 {
        20.0
    } else {
        35.0 // large unusable gap
    };
    score += class_penalty;

    // Harmonic coupling: does the lookahead item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain fit: reserve this bin
        } else if next_item_size <= post_residual {
            // reward proportionally to how tight the follow-up fit is
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 25.0 * tightness;
        } else {
            // next item cannot use this bin's remainder: penalize leftover size
            score += 0.15 * (post_residual as f64 - (post_residual % 10) as f64);
        }
    }

    // Modulo arithmetic on post_residual: multiples of small harmonics (5,10) are
    // more likely to be reusable by items drawn from rounded distributions.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: bin is in its "last third" of capacity used.
    let used = bin_residual - post_residual;
    if used * 3 >= bin_capacity * 2 {
        score -= 8.0; // prefer filling bins that are already well loaded
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 25 {
            score -= 30.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well,
        // or when many bins are open and fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_pressure = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        // Base new-bin score: slightly worse than a perfect fit, better than a bad one.
        score = bin_capacity as f64 * 0.5 + poor_fit_pressure
            - 10.0 * progress
            - (open_bins_count as f64).min(10.0);
        // If next item is huge, a fresh bin is valuable reserve.
        if next_item_size >= 70 {
            score -= 12.0;
        }
    }

    // Mild global pressure: when mean residual is high, prefer using existing space.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that few items can fill
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward perfect fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 * open_bins_count as f64;
        // But allow new bin if all fits are poor
        if post_residual as f64 > bin_capacity as f64 - item_size as f64 {
            // new bin case: post_residual = capacity - item_size
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Stream progression: early on, be more tolerant of opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_residual = post_residual - next_item_size;
        if chain_residual == 0 {
            score -= 400.0;
        } else {
            score -= 40.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to lookahead: penalize small unusable leftovers
        score += 30.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    if bin_residual == bin_capacity {
        score += 150.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio * fill_ratio;
    }

    // Penalize large dead space after placement, especially if next item cannot use it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual.min(next_item_size)) as f64;
        } else {
            score -= 0.3 * (post_residual - next_item_size).min(20) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 8.0 + 10.0 * progress;
        // If the item would leave a very awkward residual in any existing bin, soften the penalty.
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 10) {
            penalty -= 12.0;
        }
        // With many open bins, prefer consolidation into existing bins.
        penalty += 0.15 * open_bins_count as f64;
        // Large items relative to capacity are better placed fresh.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            penalty -= 5.0;
        }
        score += penalty.max(0.0);
    }

    // Mild pull toward bins with residual close to mean residual (keeps bin states homogeneous).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Slight time decay: later in the stream, waste matters more (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Penalty when post residual is small but nonzero (dead space), smoothed
    let dead = if pr > 0.0 { 1.0 / (pr + 1.0) } else { -10.0 };

    // Lookahead: reward if next item fits exactly in post residual
    let lookahead = if next_item_size > 0 && next_item_size <= post_residual {
        -2.0 * (next_item_size as f64 / cap)
    } else if next_item_size > post_residual {
        1.5 * progress
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    // Diverge from mean residual: prefer bins with low residual usage
    let mean_term = (mean_residual - pr) / cap;

    // New-bin candidate: make it moderately unattractive unless residuals are tight
    let new_bin_penalty = if bin_residual == bin_capacity {
        3.0 + 2.0 * (1.0 - progress) + (open_bins_count as f64) * 0.1
    } else {
        0.0
    };

    let mut score = pr + 10.0 * poly + 4.0 * dead + lookahead + last_chance + mean_term + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (divisible by common item granularities 10, 20, 25, 50).
    let pr = post_residual;
    if pr > 0 {
        let mut harmony_bonus = 0.0;
        for &g in &[10u32, 20, 25, 50] {
            if pr % g == 0 {
                harmony_bonus += (g as f64) * 0.35;
            }
        }
        score -= harmony_bonus;
    } else {
        // Perfect fill: strongly favored.
        score -= 200.0;
    }

    // Lookahead pairing: if the next item exactly fits the post residual,
    // this bin is a perfect chain — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // Next item fits: residual class after chaining
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 40.0;
            }
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // Next item will NOT fit here: penalize small leftover traps
            if pr < 10 {
                score += 30.0;
            } else if pr < 25 {
                score += 12.0;
            }
        }
    }

    // Dead-space penalty via integer division thresholds: residuals < 10
    // are nearly unusable (min item size ~10 in classic streams).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer tightest fit among many candidates: relative fill ratio.
    let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fill * 30.0;

    // Prefer bins below mean residual (consolidate emptiness).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late in the stream, discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 60.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post placement residual (dead space), with non-linear penalty
    // for "unusable" small gaps that few future items could fill.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are small but nonzero are the worst,
    // since item sizes are >= 1 and typical items are mid-sized.
    if post_residual > 0 {
        // Small gaps (1..=12) are nearly unusable -> quadratic penalty.
        if post_residual <= 12 {
            score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 1.5;
        }
        // Gaps below the minimum plausible item size are pure waste.
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: discourage spreading across many bins when
    // plenty of open bins exist; encourage using existing capacity.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward proportional to remaining flexibility.
            score -= 8.0;
        } else {
            // Next item will not fit here: mild penalty, worse if gap is wasted.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin is only preferred when
    // existing bins fit poorly. Penalize opening a new bin when any
    // open bin could hold the item, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Empty bin has maximal residual: neutralize the base residual advantage
        // so it never wins merely by having the largest residual.
        score += bin_capacity as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 45.0 * (1.0 - diff as f64 / bin_capacity as f64).powi(3);
        // Perfect 2-step fit gets a large bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving a gap that is too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste directly.
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty when many bins are open; encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if item is large or fit is poor elsewhere.
        let large_item_bonus = if item_size > bin_capacity / 2 { 18.0 } else { 0.0 };
        score -= 12.0 * (1.0 - progress) + large_item_bonus;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin leaves full capacity for the next item too.
            score -= 8.0;
        }
    }

    // Penalize very small post-residuals that can never fit the minimum item (size 1 range).
    if post_residual > 0 {
        score += 3.0 * (1.0 - post_residual as f64 / 10.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual is good, but avoid leaving
    // tiny unusable slivers (< 10) which are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.2 * (next_item_size as f64);
        // Chain bonus: next item fills bin almost exactly.
        let chain_post = post_residual - next_item_size;
        if chain_post < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual won't host next item; penalize proportionally to waste.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // fits poorly in every open bin (large waste) or few bins exist.
    if bin_residual == bin_capacity {
        let waste_in_open = (bin_capacity - item_size) as f64;
        // Prefer open bins when they can absorb the item reasonably well.
        score += 35.0;
        // Early in stream, opening bins is cheap; later, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        // If mean residual across open bins is large, opening a new bin wastes capacity.
        score += 0.3 * mean_residual;
        // Perfect fit in a fresh bin (item == capacity) is always great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // Large item with big waste in open bins: new bin more attractive.
        score -= 0.1 * waste_in_open;
    } else {
        // Prefer filling bins with larger residuals (larger items) to consolidate.
        score -= 0.05 * (bin_residual as f64);
        // Slight preference for bins below mean residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late in the stream, strongly prefer closing out existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (post_residual == 0) as i32 as f64;
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let size_n = item_size as f64 / cap;
    let next_n = next_item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), smooth polynomial shaping
    let x = post / cap;
    let mut score = x.powf(2.0) * 40.0 + x * 20.0;

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight fits.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += x * x * tightness * 30.0;

    // Reward using nearly-full bins (small post) more as progress grows
    score -= (1.0 - x).powf(3.0) * (10.0 + 25.0 * progress);

    // Coupling with mean residual: if this bin's post is far below mean,
    // we are concentrating waste well; reward it.
    let mean_n = mean_residual / cap;
    score -= (mean_n - x).max(0.0) * 15.0;
    score += (x - mean_n).max(0.0) * 8.0;

    // Lookahead: if next item fits exactly in post residual, strong reward
    if next_item_size > 0 && next_item_size as f64 == post {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        // penalize post residuals that are awkwardly close but not equal to next item
        score += (gap / cap).powf(1.5) * 25.0 * (1.0 - progress * 0.5);
    }

    // Last-chance bin bonus: if only this bin fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 45.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how well
    // existing alternatives exist and how much space a fresh bin wastes now.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste_penalty = (1.0 - size_n).powf(2.0) * 30.0;
        score += 55.0 + waste_penalty + 25.0 * progress;
        // but if next item is huge relative to item, a fresh bin may be wise
        if next_item_size > item_size {
            score -= 20.0 * (next_n - size_n);
        }
    }

    // Mild penalty for proliferation of open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets (capacity fractions).
    let post_class = post_residual % 10;
    // Perfect fits get huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Small dead space classes are bad: penalize residuals 1..=5 heavily.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0 - 8.0 * post_class as f64;
    }
    // Residuals that are multiples of 10 are "harmonic" — likely reusable.
    if post_class == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Class 5 residuals also reusable by typical mid-size items.
    if post_class == 5 {
        score -= 12.0;
    }

    // Integer-division threshold on next item: does the leftover fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic pairing: leftover class matches next item class.
            if post_residual % 10 == (next_item_size % 10) {
                score -= 30.0;
            }
            // Exact pair fit: post_residual == next_item_size.
            if post_residual == next_item_size {
                score -= 120.0;
            }
            // Pair leaves another harmonic (mod 10) remainder.
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 {
                score -= 15.0;
            }
            if r2 == 0 {
                score -= 60.0;
            }
        } else {
            // Leftover cannot host next item: penalize proportional dead space.
            score += 20.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Harmonic fraction of capacity: residual as fraction of 100.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * frac * frac; // reward large usable remainders superlinearly

    // Early stream: be slightly more open to spreading (keep bins balanced).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * ((post_residual as f64 - mean_residual) / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits harmonically.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when open bins score poorly.
        score += 70.0;
        // But if current item is huge relative to mean residual, opening fresh is wise.
        if (item_size as f64) > mean_residual {
            score -= 90.0;
        }
        // Harmonic item sizes (multiples of 25) pack cleanly in fresh bins.
        if item_size % 25 == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward residual that could still fit a typical future item.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post residual but could fit in current residual,
    // penalize consuming space the next item needed.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // and make opening a new bin relatively expensive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 15.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Slight preference for bins below mean residual (balance spreading).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly favor this bin (perfect chain match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this placement: mild reward proportional to fill.
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // Next item won't fit in this bin's residual: penalize leaving awkward gaps.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize placing into a fresh/nearly full open bin when many bins open (fragmentation).
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64);
    }

    // Prefer filling existing bins more as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish; only win if all open bins score poorly.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild reward scaled by fit quality
            let fill_after = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 8.0 * fill_after;
        } else {
            // next item won't fit here; penalize leaving a residual just under next_item_size
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.6 * (20.0 - gap);
            }
        }
    } else {
        // Last item: prefer filling bins as full as possible.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 20.0 * (1.0 - progress);
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is small, opening a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        // Mild penalty for bins whose residual deviates far above the mean (unbalanced use).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer reusing bins with smaller residuals overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover, but with non-linear shaping
    let mut score = pr as f64;

    // Non-linear penalty on very small residuals (dead space) that grows sharply
    score += (norm_pr * norm_pr).powf(2.0) * cap * 0.5;

    // Smooth stream-progress coupling: early on, keep bins flexible; late, pack tight
    let flex_bonus = (1.0 - progress) * (pr as f64 / cap) * 20.0;
    score -= flex_bonus;

    // Reward tight fits more as stream progresses (quadratic in fill ratio)
    let fill = 1.0 - norm_pr;
    score -= progress * fill * fill * 30.0;

    // Lookahead coupling: penalize if post_residual can't fit next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0);
        score += (gap / cap) * (gap / cap) * 25.0 * (1.0 - progress * 0.5);
        // Reward if next item fits exactly into the post residual
        if pr >= ns && (pr - ns) < 10.0 {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild pressure against opening new bins when many bins are open and mean residual is high
    let mean_fit = (mean_residual / cap).clamp(0.0, 1.0);
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0 * mean_fit;
        // But new bin is fine late in stream if item is large
        score -= (item_size as f64 / cap) * 12.0 * progress;
    }

    // Smooth interaction: residual squared vs mean residual deviation
    let dev = pr - mean_residual;
    score += (dev / cap) * (dev / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fractions and modulo arithmetic.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / c;

    // Perfect fit: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Class A: tiny leftover (<= 1/16 capacity) -> nearly perfect fill.
    if pr_frac > 0.0 && pr_frac <= 0.0625 {
        score -= 20.0;
    }
    // Class B: small but awkward leftover (1/16 .. 1/4) -> dead space zone.
    else if pr_frac <= 0.25 {
        score += 12.0 * (0.25 - pr_frac) * 4.0; // penalize awkward slivers
    }
    // Class C: medium leftover (1/4 .. 1/2) -> still usable for mid items.
    else if pr_frac <= 0.5 {
        score -= 6.0 * pr_frac;
    }

    // Modulo harmonic classes on post_residual (capacity 100 => classes mod 10).
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 4.0; // aligned leftovers pair well with aligned items
    } else if pr_mod <= 2 {
        score -= 2.0; // near-aligned
    } else if pr_mod >= 7 {
        score += 3.0; // ragged leftover, likely dead space
    }

    // Integer division thresholds: leftover big enough for a whole future item.
    if post_residual >= 40 {
        score -= 5.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 8.0; // unusable crumb
    }

    // Lookahead coupling: does the leftover exactly/nearly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // guaranteed perfect chain
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; leftover becomes dead unless large
            if post_residual < next_item_size {
                score += 4.0 * (post_residual as f64 / c);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin is a fresh resource.
    if bin_residual == bin_capacity {
        // Early in the stream, opening bins is cheap; late, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * progress;
        // But if no open bin fits well, a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Mild pressure toward consolidating residual mass.
    if (pr - mean_residual).abs() < c * 0.1 {
        score -= 2.0;
    }
    if open_bins_count > 8 {
        score -= 1.0; // encourage using many open bins rather than new ones
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Dead space that cannot fit even a small item (min size 1) is worst;
        // gaps below typical small-item threshold are penalized quadratically.
        if post_residual < 10 {
            score += 40.0 + (10.0 - pr) * 3.0;
        } else if post_residual < 20 {
            score += (20.0 - pr) * 1.5;
        }
        // Perfect fit is strongly rewarded.
        if post_residual == 0 {
            score -= 25.0;
        }
        // Reward if the leftover gap exactly accommodates the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize gaps that can't hold the next item (likely dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size as f64 - pr) * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across too many bins.
    let pressure = open_bins_count as f64;
    score += pressure * 1.2;

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by existing bin congestion.
        score += 30.0 + mean_residual * 0.3;
        // If many bins are open with slack, opening a new one is less attractive.
        score += pressure * 0.8;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
    } else {
        // Reward using bins that are already fairly full (tight packing).
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus (strong)
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits perfectly after this placement
            score -= 120.0 + 3.0 * (post_residual as f64 - next_item_size as f64).min(50.0).recip() * 10.0;
        }
        // penalize post_residual that is close-but-smaller than next item (dead space trap)
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // small residual gap is good (chain of fits)
        score -= (50.0 / (1.0 + gap)).min(50.0);
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Penalize leaving large unusable residuals relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score -= 60.0; // near-perfect packing
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // baseline penalty so open bins with decent fits win
        score += 30.0;
        if fitting_bins_count == 1 && post_residual as f64 > mean_residual {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.8 {
            score -= 50.0; // big next item: keep space clean
        }
    }

    // Mild early-stream exploration: prefer opening bins early, consolidating later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 20.0 * progress;
    }

    // Slight penalty per number of open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1), safe against division by zero.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits aggressively (superlinear waste penalty).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Reward filling bins deeply: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the leftover waste would be huge.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual < 10 {
            score -= 12.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        score -= (1.0 - next_fit_gap as f64 / bin_capacity as f64) * 15.0;
        if next_fit_gap == 0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward space.
        score += 4.0;
    }

    // Global state: when many bins are open with large mean residual,
    // discourage opening new bins; encourage consolidating into existing ones.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score += 10.0 + open_pressure * 6.0;
        // Late in the stream, opening bins is cheap-ish only if nothing fits well;
        // make new bins progressively less attractive as stream progresses.
        score += progress * 8.0;
    } else {
        // Reward using bins whose residual is close to the item (tightness).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= tightness * 10.0;
    }

    // Penalize bins that would leave residual below the minimum item size (dead space),
    // but only mildly, since perfect closure is actually ideal.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // closing a bin cleanly is good
    }

    // Mild preference toward bins with below-average residual (fill emptier bins first
    // keeps many large residuals available for large future items).
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Early stream: be slightly conservative, keep bins flexible for big items.
    score += (1.0 - progress) * (item_size as f64 / 40.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Strong non-linear penalty on wasted residual, amplified over stream progress
    score += 3.0 * norm_post * norm_post * cap * (0.5 + progress);

    // Reward tight fits (post_residual near zero) with smooth coupling to item size
    score -= 2.5 * cap * (1.0 - norm_post).powf(2.0) * norm_item * (0.5 + progress);

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * norm_next * cap * (1.0 - norm_post) * (0.3 + progress);
    } else if next_item_size > 0 {
        score += 2.0 * norm_next * cap * norm_post;
    }

    // Penalize opening a new bin when fitting alternatives exist
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 12.0 * (1.0 + progress) * (1.0 + scarcity)
            + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // Allow new bin when remaining dead space elsewhere is large
        score -= mean_residual * 0.05 * (1.0 - norm_post);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild preference for bins already below mean residual (consolidation)
    score += 0.3 * (post - mean_residual).max(-cap) * 0.1;

    // Smooth progress-scaled tiebreak on residual
    score += progress * norm_post * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // capacity fraction (mod arithmetic) to detect "usable" leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4; // 25
    let fifth = bin_capacity / 5;   // 20
    let tenth = bin_capacity / 10;  // 10

    // Reward leftovers that form nice harmonic classes (multiples of 10/20/25):
    // these are more likely to be exactly filled by future items.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if post_residual % quarter == 0 {
        score -= 12.0;
    } else if post_residual % fifth == 0 {
        score -= 8.0;
    } else if post_residual % tenth == 0 {
        score -= 4.0;
    } else {
        // Non-harmonic dead space: penalize proportionally to how small it is
        // (small non-class residuals are the worst kind of waste).
        score += (tenth as f64 - pr.min(tenth as f64)) * 0.5;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class match: next item exactly fills leftover class
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit: this bin becomes dead after placement.
            // Penalize more if leftover is small (unusable).
            if post_residual < tenth {
                score += 20.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; mitigate when mean residual is low
        // (existing bins are full) or early when consolidation is cheap.
        score = cap * 0.5 + 30.0 - mean_residual * 0.3 - (1.0 - progress) * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large items into fresh bins can help
        }
    }

    // Mild tie-breaking: prefer fuller bins (smaller residual) slightly more.
    score += (bin_residual as f64 / cap) * 0.1;

    // Slight preference to keep bin count low as stream progresses.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space for any future item (min size 1..100 but
            // typical items are chunky): strong penalty.
            score += 60.0 * (10.0 - post_residual as f64) / 10.0;
        } else {
            // Larger gaps: penalize quadratically but scaled down, since
            // they remain partially usable.
            let pr = post_residual as f64;
            score += 0.015 * pr * pr;
        }
    } else {
        // Perfect fit: big reward.
        score -= 40.0;
    }

    // Reward filling a bin heavily (high fill fraction of the residual used).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer the tightest (post_residual term
        // already does this); add mild diversity pressure.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.05 * bin_pressure;

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large relative
        // to capacity or no existing bin fits well.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 30.0 * large_item;
        // If this bin is the last chance anyway, don't open a new one.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // Late in the stream, prefer closing out existing bins.
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // leaving that gap; if next item cannot fit, penalize more.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Mild tie-break toward bins with residuals near the mean (keeps
    // distribution balanced).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is doubly rewarded).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: perfect chain with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            score -= 120.0 / (1.0 + gap as f64);
        }
        // Penalize leaving residual that fits next item poorly relative to mean residual.
        if (post_residual as f64) > mean_residual + 20.0 {
            score += 30.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large / fits are bad.
    if bin_residual == bin_capacity {
        let tight_fits = fitting_bins_count.saturating_sub(1);
        let pressure = item_size as f64 / bin_capacity as f64;
        let phase = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin for large items late in stream or when few alternatives.
        score += 400.0 - 300.0 * pressure - 100.0 * phase - 50.0 * (1.0 / (1.0 + tight_fits as f64));
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0; // stacking large items together
        }
    }

    // Mild tie-break: prefer fuller bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.1;
    // Slight preference to balance against mean residual.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tight) * (1.0 - tight);

    // Reward near-perfect fills strongly.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: penalize if post residual can't host the next item but bin_residual could have.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // leaves room for the follower
        } else if bin_residual >= next_item_size && next_item_size > item_size {
            score += 8.0; // better to save this bin for the bigger next item
        }
        // Dead-space penalty scaled by how much unusable space we'd strand
        if post_residual < next_item_size {
            score += 0.15 * post_residual as f64;
        }
    }

    // New-bin candidate handling: only open a new bin when all open fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let worst_open_threshold = item_size as f64 * 1.4;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if mean_residual < worst_open_threshold {
            score += 18.0; // existing bins fit decently, discourage new bin
        } else {
            score -= 3.0; // marginal: slightly favor fresh bin
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize stranding residual just above the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    // Mild preference for bins with larger residual among equals (pack small bins first).
    score -= 0.05 * bin_residual as f64;

    // Crowd penalty: with many open bins, discourage spreading.
    score += 0.3 * open_bins_count as f64 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let t2 = t * t;
    let t3 = t2 * t;
    let prog_weight = 0.6 + 1.4 * t2 - 0.8 * t3; // grows non-linearly with progress

    let mut score = pr * (1.0 - 0.45 * prog_weight);

    // Non-linear penalty on tiny residuals, scaled by progress
    let tiny = (1.0 - fill).powi(3); // large when residual small
    score += 12.0 * tiny * prog_weight;

    // Reward tight fits (small post_residual relative to item) with smooth term
    let fit_ratio = pr / (item_size as f64 + 1.0);
    score -= 8.0 * (-fit_ratio).exp() * (0.5 + t);

    // Last-chance bin: strong smooth bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + t2);
    }

    // Lookahead: penalize if next item could use this residual better
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let waste = (pr - nx) / cap;
            score -= 6.0 * (1.0 - waste * waste) * t;
        } else {
            score += 4.0 * ((nx - pr) / cap) * (1.0 - t);
        }
    }

    // New-bin candidate: penalize mildly early, more later (prefer consolidation)
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * t2 + 0.15 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins near mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it pairs with common small sizes (1..=20)
    let mut harmony = 0.0;
    for s in 1..=20u32 {
        if post_residual >= s {
            // reward residuals that are exact multiples / near-multiples of small sizes
            if post_residual % s == 0 {
                harmony += 2.0 / s as f64;
            }
        }
    }
    score -= 3.0 * harmony;

    // Integer-division thresholds on post_residual: classify dead-space quality
    let q = post_residual / 10; // decile class
    score += match q {
        0 => -25.0, // post_residual < 10: nearly perfect fit
        1 => -15.0, // 10..19: fits a medium item
        2 => -8.0,
        3 => -3.0,
        4 => 0.0,
        5 => 2.0,
        _ => 4.0 + 0.1 * q as f64,
    };

    // Modulo arithmetic on capacity fractions: residual close to half/quarter capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == half { score -= 10.0; }
    if post_residual == quarter { score -= 5.0; }
    if post_residual % half == 0 && post_residual > 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - 0.2 * slack as f64;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline score so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * mean_residual - (post_residual as f64);
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean (specialization)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs().powf(0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item (>=1) can use,
    // and especially gaps smaller than the smallest plausible item, are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable dead space under min item size
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // gap unusable by the lookahead item
        }
        // Diminishing-utility curve: large leftovers are cheap, mid leftovers waste potential
        score += 0.35 * (post_residual as f64).powf(0.5);
    } else {
        score -= 30.0; // perfect fit: strongly reward
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.15 * open_bins_count as f64;

    // Prefer bins tighter than average (compactness)
    score += 0.20 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score += desperation
            + 0.10 * open_bins_count as f64
            + if next_item_size > 0 && item_size < next_item_size { 8.0 } else { 0.0 };
    } else {
        score -= 5.0; // mild bias toward using existing bins
    }

    // Late-stream conservatism: keep residual flexibility as stream nears end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // Reward good two-item packing chains.
            score -= 80.0 + slack_after_next as f64 * 0.5;
            if slack_after_next == 0 {
                score -= 150.0; // exact two-item chain completion
            }
        } else {
            // Next item won't fit here; penalize leaving a residual that is
            // too small to be useful for the next item (dead space).
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 120.0; // tiny unusable sliver
            } else {
                score += 20.0 * (next_item_size - post_residual) as f64 / next_item_size as f64;
            }
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer filling bins that are already relatively full (low residual).
    let diff = post_residual as f64 - mean_residual;
    score += 0.6 * diff;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Less penalty late in the stream? Keep constant; but allow new bin if
        // lookahead shows next item is large and this item is large too.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 100.0;
        }
    }

    // Mild preference to consolidate among fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * progress * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize tiny unusable leftovers (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless it is
    // the only option or the item is large relative to typical residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_penalty = 55.0;
        if fitting_bins_count == 0 {
            new_penalty = -100.0; // must open
        } else if fitting_bins_count == 1 {
            new_penalty = 5.0; // competing with a last-chance bin
        }
        // Late in stream, prefer consolidating into open bins.
        new_penalty += 30.0 * progress;
        // Large items pack cleanly into fresh bins.
        new_penalty -= 0.3 * item_size as f64;
        score += new_penalty;
    }

    // Last-chance bin: strong reward so scarce capacity is used.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 45.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual as f64;
        score -= 14.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: mild penalty for stranding space.
        score += 6.0;
    }

    // Global state coupling: many open bins with high mean residual →
    // prefer filling existing bins rather than spreading.
    if open_bins_count > 2 {
        score += 0.8 * mean_residual * (1.0 - fit_ratio);
    }

    // Slight preference for bins already below mean residual (balanced packing).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial in normalized post-residual
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like: penalizes extremes
    let mut score = pr * (0.5 + poly);

    // Stream-progress coupling: later in stream, prefer tighter fits more strongly
    let tightness = 1.0 - x;
    score -= progress * tightness * tightness * cap * 0.35;

    // Dead-space penalty for unusable residuals relative to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.8 + progress);
        } else {
            score -= 0.4 * (1.0 - pr / (pr + nx));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced)
    score += 0.15 * (mean_residual - pr).abs() * (1.0 - progress);

    // Slight pressure to reuse open bins over opening new ones
    score += (open_bins_count as f64).ln() * 0.05 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover divides into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are multiples of small harmonics (usable leftovers)
    let harmonic_bonus = if post_residual > 0 {
        if post_residual % 10 == 0 { 6.0 }
        else if post_residual % 25 == 0 { 4.0 }
        else if post_residual % 5 == 0 { 2.0 }
        else { 0.0 }
    } else { 10.0 }; // perfect fit
    score -= harmonic_bonus;

    // Penalize tiny dead space (unusable residue) more than large usable space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does post_residual fit next item exactly or well?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.15 * slack;
        if post_residual == next_item_size { score -= 6.0; }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate penalty: prefer existing bins unless current is a bad fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
        if mean_residual > 0.0 && (bin_residual as f64) < mean_residual {
            score += 5.0;
        }
    }

    // Prefer tighter bins overall (smaller residual relative to item)
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Modulo threshold on item class: large items (harmonic 3 of capacity) pack urgently
    if item_size > bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
