    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Early in stream: mild preference for tight fits to establish good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: check if next item exactly fills post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: strongly reward
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: partial reward scaled by fill quality
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item won't fit in post residual: penalize dead space
            let dead = post_residual as f64;
            let dead_ratio = dead / bin_capacity as f64;
            score += 20.0 * dead_ratio * dead_ratio;
        }
    }

    // Compare post residual against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 10.0 * (0.5 - rel); // tighter than average: good
        } else {
            score += 8.0 * (rel - 0.5); // looser than average: mildly bad
        }
    }

    // Last chance bin: if this is the only bin that can fit, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to residual
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (add) wasted residual quadratically, scaled by capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste;

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize unusable remainder.
        score += 4.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let fill_bonus = (mean_residual - post_residual as f64).abs() / mean_residual;
        score -= 3.0 * (1.0 - fill_bonus) * (1.0 + progress);
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is terrible.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Prefer new bin late in stream or when existing bins have large residuals but bad fit.
        let penalty = 25.0 - 10.0 * progress - 5.0 * poor_fit - crowded.min(8.0);
        score += penalty.max(0.0);
    }

    // Small residual after placement is great: extra reward.
    if post_residual <= 5 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (1.0 - progress) * norm_pr.powf(2.0) + progress * (1.0 - norm_pr).powf(3.0);
    score += 40.0 * coupling;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to mean residual
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor residual that can host next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes (capacity fractions)
    let item_class = (item_size * 4) / bin_capacity; // 0..3
    let next_class = if next_item_size == 0 { 0u32 } else { (next_item_size * 4) / bin_capacity };

    // Reward near-perfect fits: post_residual small => strong discount
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) remain "usable" — reward them.
    let pr = post_residual;
    if pr > 0 {
        let usable = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if usable {
            score -= 8.0;
        } else {
            score += 4.0; // dead-space penalty for awkward residuals
        }
    }

    // Integer division thresholds: pair item class with next item class.
    // If the next item fits exactly into the post residual, big reward (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        }
        // harmonic class complementarity: e.g. small item after big item
        if item_class >= 2 && next_class <= 1 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot fit here: penalize closing this bin awkwardly
        score += 6.0;
        if post_residual < 10 {
            score += 10.0; // tiny stranded residual
        }
    }

    // Last-chance bin: strongly favor using it rather than wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer opening a
    // new bin only when this bin's fit is poor.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item then bigger item: fresh bin is fine
        }
        // early in stream, opening bins is cheap
        if (step_index as f64) / (total_items.max(1) as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Spread-awareness: many open bins with high mean residual => consolidate
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 3.0;
    } else if open_bins_count > 2 && mean_residual < 15.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size are pure waste -> heavy penalty proportional to their size.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    }
    // Residuals in the awkward mid-range (usable only by tiny items) get a
    // moderate penalty scaled by how deep into the stream we are.
    if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 25.0 * progress;
    }

    // Reward tight fits: near-exact fills are excellent.
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * tightness * tightness;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if it cannot fit, the residual is dead space for the lookahead -> penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 18.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing
    // bins; opening new bins should be less attractive.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline is full capacity; apply pressure and
        // mean-residual coupling so we only open when existing bins are messy.
        score = bin_capacity as f64 + bin_pressure + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 90.0; // never open when a last-chance bin exists
        }
    } else {
        // Existing bins get slight preference as open_bins_count grows.
        score -= bin_pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact match leaves zero waste
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size exactly
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }
    // Next item fits into the post residual: strong reward, scaled by tightness
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 300.0 * tightness;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: penalize residual that is too small to be useful
        let dead = post_residual as f64;
        score += 0.5 * dead;
        // Extra penalty if the dead space is smaller than the minimum useful item
        if dead < 10.0 {
            score += 50.0;
        }
    }

    // Small post_residual is generally good (tight packing), non-linear reward
    score -= 200.0 * (-post_residual as f64 / 20.0).exp();

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // New bin: neutral baseline, penalized more when many bins are open
        score += 100.0 + 5.0 * open_bins_count as f64;
        // But if no open bin gives a good lookahead fit, opening a new bin is fine
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            // fresh bin residual = capacity - item; check lookahead fit
            if next_item_size <= post_residual {
                score -= 150.0;
            }
        }
    }

    // Late in the stream: prefer closing out bins, slightly favor tight fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste, with non-linear penalty on small-but-nonzero residuals
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if pr < 10.0 {
        score += 12.0; // dead space penalty: tiny unusable gaps
    }

    // Lookahead: reward residuals that exactly accommodate the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 4.0; // next item can't use this bin's remainder
        }
    }

    // Tight-fit coupling: fraction filled
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 40.0 * crowding - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 100.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate emptier space)
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.05 * dev;
    }

    // Late-stream consolidation: fewer bins preferred near end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += 12.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space relative to mean residual
    let dead = (pr - mean_residual) / cap;
    score += dead * dead * 15.0;

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).sqrt() * norm_pr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are golden.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classes: residuals too small for any item (min size 1) are
    // still usable, but very small residuals relative to capacity are waste.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Fractional capacity tiers via integer division thresholds.
    let tier = post_residual / 10; // 0..10 harmonic class
    score += (tier as f64) * 2.0;

    // Penalize residuals that no plausible item can fill: post_residual < 10
    // is near-dead space (items are >=1 but small residuals rarely match).
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Reward residuals in "sweet spot" classes that common item sizes fill:
    // residuals divisible into clean fractions of capacity.
    if post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            score -= 25.0;
            if next_post == 0 {
                score -= 100.0;
            }
            // Harmonic class of the two-step remainder
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            if next_post < 10 && next_post > 0 {
                score += 20.0;
            }
        } else {
            // Next item won't fit here; residual becomes dead space for k=2.
            score += 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // in existing bins is poor. Penalize the fresh bin mildly by its "wasted"
    // capacity (capacity - item), but not catastrophically.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * (bin_capacity - item_size) as f64;
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Mild pressure against hoarding many open bins with scattered residuals.
    score += 0.5 * open_bins_count as f64;

    // Normalize against mean residual state: prefer bins below mean residual
    // (tighter bins get filled first).
    score += 0.2 * (mean_residual - post_f);

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
