    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in post_residual (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // Early stream: be slightly more conservative with existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
