        score += 30.0 * crowd + mean_residual * 0.4;
        // Late in the stream, opening new bins is less attractive.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * t;
    }

    // Prefer filling bins that are already more depleted (larger item fraction of capacity).
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Slight bonus for bins below mean residual (they need filling anyway).
    if (bin_residual as f64) > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - (pr / cap); // 0 = empty-ish, 1 = nearly full

    // Smooth non-linear polynomial coupling: reward tight fits, scaled by stream progress
    let fit_reward = tightness * tightness * (1.0 + 3.0 * progress);
    score -= 12.0 * fit_reward;

    // Cubic dead-space penalty on large residuals
    let dead = (pr / cap).powi(3);
    score += 8.0 * dead;

    // Lookahead coupling: bonus if next item fits the post residual (smoothly)
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as f64;
        let ratio = (next_item_size as f64 / pr.max(1.0)).min(1.0);
        score -= 6.0 * fits * (0.5 + 0.5 * ratio) * (0.5 + progress);
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.6 + 0.4 * progress);
    }

    // Mild penalty when bin is far below mean residual (keeps balance)
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate: penalize slightly unless item is huge and few bins fit
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 4.0 - 6.0 * big * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and near-exact fills are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else {
        // Dead space penalty grows super-linearly for unusable slivers
        if pr < 10 {
            // small but not tiny residual: worst dead space class
            score += 60.0;
        }
        // modulo classes: residuals that are multiples of common small sizes (5,10,20,25)
        // are more likely to be reused by future items -> reward them.
        let reusable = (pr % 5 == 0) as i32 as f64 * 8.0
            + (pr % 10 == 0) as i32 as f64 * 10.0
            + (pr % 20 == 0) as i32 as f64 * 8.0
            + (pr % 25 == 0) as i32 as f64 * 6.0;
        score -= reusable;
        // integer division thresholds: how many "typical" small items still fit
        let slots = pr / 10;
        score -= slots as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next fits: how tightly?
            let gap = pr - next_item_size;
            score -= 20.0 - (gap as f64).min(20.0);
            // harmonic pairing: next_item + item ~ nice fractions of capacity
            let sum = (item_size + next_item_size) as f64 / cap;
            if (sum - 1.0).abs() < 1e-9 {
                score -= 80.0;
            } else if (sum * 2.0 - 1.0).abs() < 1e-9 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last chance: only bin that fits -> strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; competitive with mediocre fits
        score = cap * 0.55 + (post_residual as f64 - cap) * 0.0;
        // discount slightly when stream is late (fewer future items to amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // open new bin if existing fit would leave a nasty sliver
        if bin_residual >= item_size && pr > 0 && pr < 10 {
            score -= 90.0;
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Mild pressure against bin proliferation
    score += open_bins_count as f64 * 0.5;
    // Prefer bins tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Threshold: gaps too small to hold the smallest plausible item (or the
    // lookahead item) are "dead" — penalize quadratically.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot host the next item either: extra penalty.
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= dead_threshold {
        // near-perfect fit already penalized above; keep base
    }

    // Reward tight fits relative to capacity (small post_residual fraction).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // make the new-bin candidate (bin_residual == bin_capacity) less attractive
    // unless it produces a great fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 10.0 + pressure;
        // But allow opening when it avoids dead space elsewhere: if this is the
        // last-chance bin scenario it will not be new-bin anyway.
        if post_residual == 0 {
            score -= 60.0; // impossible for empty bin, kept for symmetry
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin over opening a new one.
        score -= 40.0;
    }

    // Coupling with mean residual: if this bin is much tighter than average,
    // it is a good target (best-fit style); if looser than average, mild penalty.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: reward placements leaving room exactly for next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward post_residual matching next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement; reward closeness of match
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / 100.0);
        } else {
            // next item will not fit here afterwards; penalize wasted residual
            let waste = post_residual as f64;
            score += 60.0 * (1.0 - waste / 100.0);
        }
    }

    // Penalize small dead space below minimum item size (unusable)
    if post_residual < 10 {
        score += 120.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 80.0 + 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin can host the pair
        }
    }

    // Late in stream: consolidate into open bins more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 30.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item can fit into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Placing here blocks next item from joining this bin; penalize dead space.
        score += 4.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over opening new bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when item is large relative to residual
    // and existing bins are fragmented (mean residual low).
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Open a new bin if item is big and existing residuals are small.
        let new_bin_penalty = 30.0 + 40.0 * frag - 25.0 * large_item - 5.0 * progress;
        score += new_bin_penalty;
        // Never open a new bin for a tiny item.
        if item_size <= 30 {
            score += 25.0;
        }
    } else {
        // Existing bin: slight bonus scaled by how full it already is.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    // Early stream: be conservative, keep bins balanced.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += 2.0 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space (tight fits win)
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Non-linear coupling with stream progress: waste matters more later
    score *= 1.0 + 1.5 * progress * progress;

    // Reward bins whose residual is close to exactly consumed (smooth kernel)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * (fit_ratio * fit_ratio);

    // Lookahead: bonus if the post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins open,
    // but allow it when post_residual would be large and progress is late
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let openness = open_f / (open_f + 5.0);
        score += 8.0 + 15.0 * openness * (1.0 - progress);
        score += 0.02 * open_f;
    } else {
        // Prefer bins below mean residual (consolidate emptier space usage)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets reward "clean" residuals
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.8; // residual near a multiple of 10 is reusable

    // Penalize dead space below smallest plausible item class
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Integer-division threshold: post_residual / item_size ratio
    let ratio = post_residual as f64 / (item_size.max(1) as f64);
    if ratio >= 2.0 {
        score -= 6.0; // bin could hold another item of same size later
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize wasting space it could have used elsewhere
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is bad (post_residual small).
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    // Late-stream consolidation: prefer tight fits as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Penalize bins far below mean residual (fragmented outliers)
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // possible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score -= 120.0; // perfect fill, strongly preferred
    } else if post_residual <= 20 {
        score -= 25.0;  // nearly dead space, mildly favored
    } else if post_residual <= 35 {
        score += 10.0;  // awkward mid gap
    } else {
        score += 20.0;  // large leftover: wasteful unless item is huge
    }

    // Reward tight fits relative to residual (low fragmentation).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize so it only wins when no decent fit exists,
    // but relax pressure as the stream progresses (endgame consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; mild penalty for stranding space
        score += 5.0;
    }

    // Prefer bins below the mean residual (more filled than average).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how much will remain after two placements
            let two_step_residual = post_residual - next_item_size;
            score -= (two_step_residual as f64) * 0.5;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Reward using bins tighter than average (consolidation), penalize loose bins.
    let residual_f = bin_residual as f64;
    score += (residual_f - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize wasting space in nearly-full bins when item is small.
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= tightness * (item_size as f64) * 0.2;

    // New-bin candidate: keep it neutral-to-slightly-high unless leftovers are hopeless.
    if bin_residual == bin_capacity {
        let hopeless = post_residual > 0 && post_residual < 10;
        score += if hopeless { 50.0 } else { 200.0 };
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_capacity as f64);
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.8;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how snugly it fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 30.0 * snug;
        } else {
            // next item won't fit here: penalize leaving a gap that's too small for it
            score += 15.0;
        }
    }

    // Penalize opening a brand-new bin when good open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let waste = post_residual as f64; // = capacity - item_size
        score += 80.0 + waste * 0.5;
        // Early in the stream, opening bins is cheaper; late, avoid it.
        score += progress * 40.0;
        // If many bins are open, discourage more bins unless necessary.
        score += (open_bins_count as f64).sqrt() * 10.0;
    } else {
        // Using an existing bin: mild reward scaled by how far below mean residual it lands
        // (prefer consuming bins with more residual to balance residuals? no — prefer
        // consuming bins with LESS residual to keep large residual bins flexible).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
        // Slight reward for keeping mean residual high across bins.
        if (bin_residual as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Discourage creating tiny unusable gaps (dead space below min plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: reward small post-residual via smooth non-linear decay
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post-residual with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier)
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Reward last-chance bins (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * progress;
    }

    // Penalize bins much tighter than average (waste potential elsewhere)
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 2.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for very tight residuals that become dead space (< 10)
    score += 3.0 * (1.0 - norm_pr / 0.1).max(0.0) * norm_pr / 0.1;

    // Slight preference for consolidating into fewer bins
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by integer division into
    // "dead space" severity classes (0..=4). Larger class = worse waste.
    let dead_class = (post_residual / 20) as f64; // 0..=5
    score += dead_class * dead_class * 2.0;

    // Exact fit is perfect regardless of class.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic fraction of the bin filled by this item (capacity fractions).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly reward, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * fill_frac;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_frac = next_item_size as f64 / post_residual as f64;
        score -= 12.0 + 8.0 * chain_frac;
    } else if next_item_size > 0 {
        // Next item cannot use the remainder: penalize proportionally to wasted class.
        score += 5.0 + dead_class;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin
    // fits well. Penalize opening a bin early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // pair big items with big followers in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        }
    }

    // Prefer bins whose residual deviates from the mean in a "complementary" way:
    // placing into a bin with residual far below mean leaves big chunks elsewhere.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Modulo harmonic bonus: remainders that are multiples of common item
    // granularity (10) are more reusable than odd remainders.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 3.0;
    }

    // Mild preference for tighter fits as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever be useful are heavily penalized.
    // A residual is "dead" if it is below the smallest possible item (1) threshold zone
    // and below the lookahead item size.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 1 };

    if post_residual < min_useful {
        // Truly unusable gap for the next item: strong penalty.
        score += 60.0 * (1.0 + 0.5 * (1.0 - progress));
    } else if post_residual < 10 {
        // Small gap unlikely to be filled by typical items (>=10 originally, now 1..100):
        // moderate penalty scaled by gap smallness.
        score += 25.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Reward near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Exact fit for the lookahead item: very desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins; encourage filling
    // existing bins when many are open.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-average residual (tighter bins get filled first),
    // leaving larger residuals for larger future items.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.3 * diff;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // and no good fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Partial lookahead credit: residual after next placement
        let after_next = post_residual - next_item_size;
        score -= 30.0 - (after_next as f64).min(30.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize waste
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.4;
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual - 5.0 {
        // This bin leaves less slack than average -> tight fit, reward
        score -= (mean_residual - pr).min(25.0) * 0.5;
    } else if pr > mean_residual + 10.0 {
        // Leaves unusually large slack -> wasteful, penalize
        score += (pr - mean_residual).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably
    if bin_residual == bin_capacity {
        let open_frac = open_bins_count as f64 / (open_bins_count + 3.0) as f64;
        score += 12.0 + 20.0 * open_frac;
        // New bin is fine if item barely fits elsewhere
        if fitting_bins_count > 0 && item_size as f64 > bin_residual as f64 * 0.0 {
            let best_alt_gap = (bin_capacity as f64 - item_size as f64);
            if best_alt_gap > 30.0 { score -= 8.0; }
        }
        // Late in stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Small bonus for very tight fits overall
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: bonus if next item fits exactly into the resulting residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving a residual that wastes space.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is penalized, but justified when
    // the item fits poorly everywhere (large post_residual in the best bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 12.0 + 6.0 * (1.0 - progress);
        // If existing bins are crowded (low mean residual), opening is cheaper.
        open_cost -= 10.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // If many bins can fit the item, no reason to open a new one.
        open_cost += 3.0 * (fitting_bins_count as f64);
        score += open_cost;
    } else {
        // Mild preference for fuller bins among open candidates.
        score -= 1.5 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    // Slight preference for fewer open bins (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    let mut score = post;

    // Smooth non-linear coupling of dead space with stream progress:
    // early on, small residuals are acceptable; late, they become costly.
    let dead_weight = 1.0 + 2.0 * progress * progress;
    score -= dead_weight * cap * (x - x * x) * 0.5;

    // Penalize tiny residuals more strongly as the stream progresses (quartic bowl).
    score += dead_weight * cap * (1.0 - x).powi(4) * 0.15;

    // Reward tight fits (small post_residual) with a smooth exponential-like term.
    score -= cap * (-(1.0 - x) * 4.0).exp() * 0.3;

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for bins below mean residual (consolidating space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty for proliferating bins early.
    score += (open_bins_count as f64) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residue mod 10 (dead-space classes) ---
    let pr = post_residual as i64;
    let residue = pr % 10;
    // Perfect-fit residues (0, 10) are ideal; small residues (1..5) are dead space.
    score -= match residue {
        0 => 14.0,
        1 => -6.0,
        2 => -4.0,
        3 => -2.5,
        4 => -1.0,
        5 => 0.5,
        _ => 2.0,
    } as f64;

    // --- Integer division thresholds: post_residual buckets ---
    let pr_bucket = pr / 10;
    score += match pr_bucket {
        0 => -8.0,          // near-perfect fill
        1 => -3.0,          // small gap
        2..=4 => 0.0,       // mid gap
        5..=7 => 3.0,       // large gap, wasteful
        _ => 5.0,           // almost empty bin used
    } as f64;

    // --- Coupling: can next item (k=2 lookahead) exactly fill post_residual? ---
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni == pr {
            score -= 10.0; // perfect chaining
        } else if ni <= pr && (pr - ni) % 10 == 0 {
            score -= 5.0; // harmonic chain leaving class-0 residue
        } else if ni <= pr {
            score -= 1.5; // next item still fits
        } else {
            score += 2.0; // next item won't fit here; bin will strand
        }
        // modulo-5 harmonic match between next item and post residual
        if ni <= pr && (pr - ni) % 5 == 0 {
            score -= 2.0;
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 3 {
        score += 1.0; // plenty of alternatives; be picky
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost, discounted early when few bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 22.0 - 8.0 * (1.0 - progress) - (open_bins_count as f64).min(6.0) * 0.5;
        // If item is large, new bin is fine (it leaves small residue anyway)
        if item_size >= bin_capacity * 3 / 4 {
            score -= 6.0;
        }
        // If next item is large too, prefer fresh bin
        if next_item_size >= bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // --- Mean residual drift penalty: avoid scattering into high-residual pool ---
    let diff = post_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // --- Item size fraction coupling: big items prefer tight bins ---
    let frac = item_size as f64 / bin_capacity as f64;
    score -= 4.0 * frac * (1.0 - post_residual as f64 / bin_capacity as f64);

    // --- Small tie-breaker against exact ties ---
    score += (bin_residual as f64 % 3.0) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // If post_residual is nonzero but smaller than the smallest plausible item,
    // this bin's remaining space becomes dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Prefer exact/tight fits: reward small post_residual relative to item size.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score += (post_residual as f64) * 1.5;
    }

    // Dead-space pressure scaled by stream progression: late in the stream,
    // avoid leaving awkward gaps even more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 30 {
        score += progress * (30 - post_residual) as f64 * 1.2;
    }

    // Open-bins pressure: when many bins are open, favor filling existing bins
    // (penalize new-bin candidate implicitly via this bin's attractiveness).
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "hole" bin; filling it is good (penalize less).
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.5;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins unattractive unless the fit would be
    // very poor in all open bins (handled by dead-space penalties above).
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is large and this item leaves a gap the next item
        // could fill, opening fresh may be fine — slight relief.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead: reward placements whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.4;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0 + item_size as f64 * 0.5;
    }
    // Next item fits with small slack: strong reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack.min(30.0) * 0.5;
    }
    // Next item does NOT fit the leftover: penalize creating dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward using bins whose residual is already tight (avoid wasting large residuals)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize leaving unusable tiny residuals (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bin would leave large waste
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 30.0 - waste * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // As stream progresses, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins below mean residual (consume the scattered small spaces)
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= 4.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 10.0;

    // Penalize dead space: post_residual that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // If next item does NOT fit but would fit the bin's original residual elsewhere,
    // penalize slightly to encourage saving space for it.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins over opening new ones.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or the item
    // barely fits anywhere / current bins are quite full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 - 15.0 * progress - 10.0 * avg_fullness;
        // Item is large relative to capacity: new bin may be reasonable.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Global residual balance: prefer bins whose residual is below the mean
    // (fill fuller bins first), keeping large residuals for future large items.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Time horizon: late in the stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64 / cap); // how full bin becomes
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64; // 1.0 = perfect fit

    // Reward tight fits, more aggressively later in the stream
    let tight_reward = (fit_tightness * fit_tightness) * (1.0 + 6.0 * progress);
    score -= tight_reward;

    // Penalize large post-residual dead space non-linearly, weighted by progress
    let dead = post_residual as f64 / cap;
    score += 3.0 * dead * dead * (1.0 + 4.0 * progress);

    // Interaction: residual relative to mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 2.0 * (rel - 1.0) * (rel - 1.0) * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize early, allow later when existing fits are poor
    if bin_residual == bin_capacity {
        let new_bin_penalty = 6.0 * (1.0 - progress) * (1.0 - progress)
            + 2.0 * (open_bins_count as f64).sqrt();
        // If next item can use the fresh bin's full capacity, soften penalty
        let lookahead_soft = if next_item_size > 0 {
            (next_item_size as f64 / cap) * 2.0
        } else { 0.0 };
        score += new_bin_penalty - lookahead_soft;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5 + 2.0 * progress * (post_residual as f64 / cap);
    }

    // Slight preference to fill bins with more current residual when many bins open
    score -= 0.3 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 buckets dead-space quality
    let pr = post_residual as i64;
    let class = pr % 10;
    // Dead space penalty: quadratic in post_residual, modulated by class
    let class_penalty = match class {
        0 => -6.0,   // perfectly divisible residual -> reusable by many sizes
        5 => -3.0,   // half-class residual still useful
        2 | 4 | 6 | 8 => -1.0, // even classes moderately reusable
        _ => 2.0,    // odd classes: awkward dead space
    };
    score += 0.02 * (pr as f64) * (pr as f64) / 10.0 + class_penalty;

    // Integer-division threshold: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fit: reward proportionally to how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.05 * snug;
            // harmonic bonus if next item also lands in a good class
            if (pr - next_item_size as i64) % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot follow here: mild penalty unless this bin is nearly full
            if post_residual > 20 { score += 3.0; }
        }
    } else {
        // last item: just minimize waste
        score += 0.5 * pr as f64;
    }

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is huge
    // or no open bin fits well (post_residual would be small = tight fit).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        // opening is attractive for large items or when many bins already open & mean residual low
        let item_frac = item_size as f64 / cap;
        score += 12.0 + 6.0 * openness;
        score -= 30.0 * item_frac;
        if mean_residual < 15.0 && open_bins_count > 0 { score -= 10.0; }
        if next_item_size > 0 && next_item_size >= item_size { score -= 3.0; }
    }

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable gaps harder than large gaps.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 40 {
            score += 8.0;
        }
    }

    // Reward gaps that can still fit the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0; // dead space for the next item
    }

    // Pressure on number of open bins: favor filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when existing bins have plenty of residual space.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * mean_residual;
        if fitting_bins_count > 0 {
            score += 80.0;
        }
    }

    // Prefer bins with residual close to the mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when the post residual matches
    // the next item size (chaining placements), penalize mismatched gaps.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.9;
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // If next item can't fit anywhere else and this bin could chain it,
        // strongly favor keeping the residual exactly usable.
        if next_item_size <= post_residual && fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // Dead space: residual too small for next item and unlikely for anything.
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    // (best-fit style), but avoid extremely empty bins unless necessary.
    let resid_f = post_residual as f64;
    score += (resid_f - mean_residual).max(0.0) * 0.4;
    score -= (mean_residual - resid_f).max(0.0) * 0.2;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it's genuinely
    // needed (no fitting open bins) or item is huge.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let relief = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        let big_item = if item_size >= 70 { 20.0 } else { 0.0 };
        // A new bin is attractive if the next item is large and open bins are tight.
        let lookahead_relief = if next_item_size > mean_residual as u32 && open_bins_count > 0 { 10.0 } else { 0.0 };
        score += base - relief - big_item - lookahead_relief;
    }

    // Slight stream-position adaptation: later in the stream, be more
    // conservative about residual waste (less room to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += resid_f * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post-residual,
    // penalty if the next item would fit but the residual is too fragmented.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item won't fit after this placement; mild penalty unless perfect fit already
            score += 50.0;
        }
        // Reward leaving residual that pairs well with a typical next item
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual >= 10 && post_residual < next_item_size {
            score += 20.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize large dead space relative to the smallest plausible item (1..100 interface).
    // Waste that can never be reused (post_residual < 1 means nothing fits) is bad.
    if post_residual > 0 {
        // dead space score: quadratic in smallness of post_residual
        let usable = if post_residual >= 100 { 0.0 } else { 1.0 };
        score += usable * (50.0 - post_residual as f64).max(0.0) * 0.5;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize the fresh bin mildly so tight fits in open bins win,
    // but reward it when all open-bin residuals are poor.
    if bin_residual == bin_capacity {
        let poor_open = if open_bins_count == 0 {
            0.0
        } else {
            // mean residual large relative to item => open bins are roomy, fine to use them
            ((mean_residual - item_size as f64).max(0.0) / bin_capacity as f64)
        };
        // Base penalty so new bins are not opened frivolously.
        score += 120.0;
        // But if open bins have very little usable residual (mean_residual small),
        // opening a new bin is attractive: reduce penalty.
        let tightness = (item_size as f64 - mean_residual).max(0.0);
        score -= tightness * 1.5;
        // Early in stream, keep bin count low; later, allow spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * (1.0 - progress);
        // If the next item is large and this item is small, prefer a fresh bin
        // to preserve big residuals elsewhere.
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 60.0;
        }
        let _ = poor_open;
    } else {
        // Non-empty bins: reward using bins whose residual is close to the item
        // (best-fit sharpening).
        let tightness = (bin_residual as f64 - item_size as f64).max(0.0);
        score += tightness * 0.3;
        // Slight reward for keeping mean residual balanced: prefer bins with
        // residual near the mean (avoid systematically draining one bin).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing bins
    // over opening new ones even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual < bin_capacity {
        score -= 40.0 * (progress - 0.8) * 5.0;
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize small residuals quadratically as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + t);

    // Cubic term: reward tight fits more strongly late in the stream
    score -= 20.0 * (1.0 - norm_pr).powi(3) * t;

    // Penalize large residuals that leave dead space, weighted by stream progress
    score += 8.0 * norm_pr * norm_pr * (0.3 + 0.7 * t);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: bonus if next item fits in post_residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / cap;
        score -= 6.0 * chain * (1.0 + t);
    } else if next_item_size > 0 && next_item_size <= item_size {
        // next item similar to current; small residual still useful
        score -= 2.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(1.0);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when many bins open
    let mr = mean_residual / cap;
    score += 5.0 * (norm_pr - mr) * (1.0 + open_bins_count as f64 / 10.0).ln();

    // Mild penalty for opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - t) + 3.0 * open_bins_count as f64;
        // but allow new bin if all existing fits would be terrible
        if fitting_bins_count >= 1 && norm_pr < 0.15 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into buckets.
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -40.0,                       // perfect fit: strongly reward
        1..=5 => 60.0,                    // tiny unusable sliver: heavily penalize
        6..=15 => 25.0,                   // small dead space
        16..=30 => -5.0,                  // moderate space, mildly reusable
        31..=50 => -12.0,                 // good reusable range
        _ => -18.0,                       // large residual, most reusable
    };
    score += class;

    // Integer-division harmonic penalty: residual that is not a "useful" multiple
    // of common item sizes (10/20/25) is harder to fill later.
    let useful = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
    if !useful && pr > 0 {
        score += 8.0 + (pr % 10) as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64 * 0.3).min(15.0);
        } else {
            // next item cannot use this residual; slight penalty proportional to gap
            score += ((next_item_size - pr) as f64 * 0.15).min(10.0);
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post residual tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if pr >= 5 {
            score -= 10.0;
        }
    }

    // New-bin candidate: neutralize base residual so an empty bin scores by its
    // future potential; prefer it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 12.0 + mean_residual * 0.2 - (pr as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer fuller bins slightly (best-fit flavor) via residual-to-mean coupling.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.25;
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: attractive only if this item would leave a large
    // dead gap in every existing bin context; a fresh bin preserves a full 100
    // residual. Judge by whether placing here creates a bad small gap while
    // the new bin would keep a large usable residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with the number of open bins.
        score += 8.0 + open_bins_count as f64 * 0.5;
        // But if the current item is large, a fresh bin wastes little.
        score -= item_size as f64 * 0.15;
        // If next item is small, a fresh bin can absorb it; slight bonus.
        if next_item_size > 0 && next_item_size <= 15 {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is already below the mean (tighter bins),
    // keeping larger residuals available for larger future items.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post-placement residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0; // dead space confirmed unusable by lookahead
    }

    // Early in the stream, be slightly more willing to open bins (flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual closely matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how much space is wasted.
        score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Prefer bins tighter than the mean residual (waste less usable space).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure toward consolidation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Discard near-full bins slightly (they're almost done anyway).
    if post_residual <= 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize high post_residual, especially small dead space.
    if post_residual > 0 {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 20.0;
        // Dead space penalty: residuals too small to fit typical items are wasted.
        if post_residual < 10 {
            score += 15.0; // tiny slivers are nearly useless
        }
    } else {
        score -= 25.0; // perfect fit
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the bin that leaves the most usable remainder.
        score -= (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if post_residual - next_item_size stays small (chained fits).
            let chain_left = post_residual - next_item_size;
            score += (chain_left as f64) * 0.15;
        } else {
            score += 8.0; // cannot host the next item
        }
    }

    // Global state: prefer filling bins when mean residual is high (fragmentation risk).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Time horizon: early in the stream, opening new bins is cheap; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0; // late stream: favor existing bins (larger score for new bin)

    // New-bin candidate handling: empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early, or when item is large relative to capacity.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += 10.0 - progress * 10.0 - large_item_bonus;
        // Never open a new bin when a perfect fit exists elsewhere is handled by perfect-fit bonus.
    }

    // Prefer bins with lower current residual among equals (fill emptier bins first).
    score += (bin_residual as f64) * 0.02;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted post-residual, with a non-linear (quadratic) dead-space term.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth polynomial coupling: tight fits are more valuable as the stream progresses.
    let tightness = 1.0 - post / cap; // 0 = empty, 1 = perfect fit
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residuals that are awkward: small but nonzero leftover space.
    let awkward = (post / cap) * (1.0 - post / cap) * (post / cap);
    score += 4.0 * awkward * (1.0 + 2.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate handling: discourage opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        // If the next item could combine well with this item's post-residual, favor opening.
        if next_item_size > 0 {
            let next = next_item_size as f64;
            if next <= post {
                score -= 4.0 * (1.0 - next / post);
            } else {
                score += 3.0 * (next - post) / cap;
            }
        }
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        // Reward placements that leave room for the lookahead item.
        score -= 3.0 * (1.0 - (next_item_size as f64) / post);
    } else if next_item_size > 0 {
        // Slight penalty if the lookahead item won't fit the leftover.
        score += 2.0 * ((next_item_size as f64) - post) / cap;
    }

    // Mild pressure to consolidate across many open bins early on.
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress) / (1.0 + mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into deciles of capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let harmonic_class = (post / cap * 10.0).floor(); // 0..10

    // Dead-space penalty: small leftover slots are hard to reuse later.
    if post_residual > 0 {
        // Harmonic penalty peaks when leftover is small but nonzero (unusable slivers).
        let sliver = ((8.0 - harmonic_class) / 8.0).max(0.0);
        score += 12.0 * sliver * sliver;
    } else {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Modulo coupling: leftover compatible with common item sizes (multiples of 10)
    // is reusable; leftover with odd remainder is penalized.
    let mod10 = post_residual % 10;
    if post_residual > 0 {
        score += match mod10 {
            0 => -6.0,
            1 | 9 => 5.0,
            2 | 8 => 3.0,
            _ => 1.5,
        } as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Partial reward scaled by how much of the leftover the next item consumes.
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 15.0 * fill;
        } else {
            // Next item cannot use this leftover: mild penalty, scaled by wasted potential.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large relative
    // to capacity or when existing bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.3;
        let big_item = item_size as f64 > 0.55 * cap;
        if (big_item || crowded) && fitting_bins_count > 0 {
            score -= 10.0 + 15.0 * progress;
        } else {
            // Prefer placing into existing bins by default.
            score += 30.0;
        }
    }

    // Mild preference for tighter bins when many bins are open (bin consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap) * 3.0;

    // Early stream: keep bins balanced to preserve flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Gaps too small for the smallest plausible follow-up item (1..100 range),
    // but still "medium" — moderate penalty proportional to waste.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 2.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones; penalize the new-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.5;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 3.0 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post gap smaller than next item: dead space for the lookahead.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Prefer bins whose residual is already below average (filling fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (low post_residual is already good; amplify it).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 200.0;
        } else if diff <= 5 {
            score -= 60.0;
        } else if diff <= 10 {
            score -= 25.0;
        } else {
            // Penalize large wasted gaps relative to next item.
            score += diff as f64 * 0.5;
        }
        // If next item cannot fit anywhere after this placement, and this bin
        // can't host it either, mild penalty for creating fragmentation.
        if next_item_size as u32 > post_residual && diff > 10 {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins that are unusually roomy.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening a new bin is more acceptable than
        // fragmenting existing ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
        // If next item is small, a fresh bin has good future potential.
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 * 0.25 {
            score -= 30.0;
        }
    }

    // Slight preference for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: heavily favor bins where the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically, but only if it's truly unusable.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: residual exactly consumed next step
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // Next item cannot fit here; slight penalty proportional to mismatch.
            let miss = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 8.0 * miss;
        }
    } else {
        // Last item: closing a bin as tightly as possible is ideal.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes open-bin capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with how many bins are already open
        // (consolidation pressure) and how much residual is stranded on average.
        score += 20.0 + 2.5 * open_bins_count as f64;
        score += 0.3 * mean_residual;

        // Early in the stream, opening bins is cheap; late in the stream,
        // prefer packing into existing bins aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;

        // If next item is small, a fresh bin has room to chain; soften the penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // If no open bin fits well (this is the only fitting candidate anyway),
        // opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        // Mild reward for using open bins, scaled by how crowded the bin is.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    // Global state coupling: if mean residual is high, prefer bins that reduce
    // dispersion (i.e., bins with residual far below mean get a nudge).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear emphasis on tight fits.
    let mut score = post;

    // Quadratic coupling: waste below half a bin is mildly bad, near-full fills are great.
    score += 40.0 * pr * pr - 60.0 * pr;

    // Smooth interaction of fit quality with stream progress: later in the stream,
    // demand tighter fits (waste compounds over many placements).
    let progress_coupling = 30.0 * progress * (pr - 0.5) * (pr - 0.5) * 4.0;
    score += progress_coupling;

    // Reward bins whose residual is close to the item size (smooth sigmoid-like term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;

    // Penalize leaving residuals that no typical next item can use, smoothed.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let usable = 1.0 / (1.0 + (gap / 20.0) * (gap / 20.0));
        score += 15.0 * (1.0 - usable);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening bins when existing ones fit well,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let mut open_penalty = 55.0 * (1.0 - crowding);
        // As stream progresses, slightly prefer consolidating into open bins.
        open_penalty *= 1.0 + 0.5 * progress;
        score += open_penalty;
    }

    // Mild penalty for many open bins: encourage finishing bins before opening more.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 define "usable" vs dead zones
    let r = post_residual % 10;
    // Dead-space penalty grows for residues that are hard to fill (e.g. 1..3)
    if r > 0 && r <= 3 {
        score += (4.0 - r as f64) * 8.0;
    } else if r >= 8 {
        score -= 4.0; // nearly-full residue is fine
    }

    // Integer-division thresholds: post_residual bucketed by /10
    let bucket = post_residual / 10;
    score += bucket as f64 * 0.8;

    // Lookahead coupling: if next item fits the post residual exactly, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual % next_item_size == 0 {
            score -= 10.0; // divisible: future perfect fits likely
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0; // next item can't use this bin's remainder
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline, penalize slightly
    // so we prefer good fits into open bins, but allow it when residuals are bad.
    if bin_residual == bin_capacity {
        score = 45.0 + (post_residual as f64);
        if post_residual > 0 {
            score += 30.0; // should never happen for empty bin, safety
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is attractive when stream is early/many items remain
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Prefer bins tighter than the mean residual (good packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Many open bins: encourage consolidation into existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in [1, 9] is unusable
    // for any item (min size 1, but tiny gaps rarely reused) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave a gap reusable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for next item: mild penalty proportional to waste.
        score += 0.25 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins slightly.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize mildly so it only wins when open bins
    // have very poor fits (their dead-space penalties push them above).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in stream, new bins are cheap; late, conserve by raising cost.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Waste ratio term: penalize wasting a large residual on a small item.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space relative to the lookahead item: waste that can't host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
