        }
    }

    // Prefer bins with more residual consumed overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < item_size.min(60) {
        score += 3.0; // moderate dead space
    } else {
        score += 8.0; // large dead space relative to item
    }

    // Lookahead: if the next item fits in the post residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless residual is highly fragmented
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when open bins are crowded/fragmented
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0;
