        // Early in stream, new bins are cheap; later, consolidation matters
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Global state: many open bins -> favor consolidation into existing bins
    score -= 1.5 * (open_bins_count as f64).sqrt();
    score += 0.4 * (mean_residual - post_residual as f64).abs();

    // Time horizon: as stream nears end, prioritize perfect fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer low post-residual, with non-linear emphasis on tight fits.
    let mut score = r
        - 8.0 * (1.0 - rn * rn) // reward near-full fills smoothly
        + 20.0 * rn * rn * rn;  // penalize large dead space cubically

    // Smooth interaction: tight fits matter more as the stream progresses.
    score -= 12.0 * progress * (1.0 - rn) * (1.0 - rn);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // with a smooth quadratic decay of usefulness as residual shrinks.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = ((r - nx) / cap).max(0.0);
        score -= 10.0 * usable * (1.0 - usable);
        // Penalize leaving residual just below the next item's size (dead zone).
        if r < nx {
            score += 6.0 * (nx - r) / cap;
        }
    }

    // Mild penalty when this bin is far from the mean residual (fragmentation),
    // smoothly damped by number of open bins.
    let frag = (r - mean_residual) / cap;
    score += 5.0 * frag * frag / (1.0 + open_bins_count as f64);

    // New-bin candidate: make it attractive only when no open bin fits well,
    // via smooth interaction with mean residual and progress.
    if bin_residual == bin_capacity {
        score = cap - 10.0 * mean_residual / cap - 5.0 * progress;
        if fitting_bins_count == 1 {
            score += 30.0; // keep using the last-chance bin instead of a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
