    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        if dead {
            score += 30.0; // undo some reward if fit creates dead space
        }
    }

    // New-bin candidate (empty bin): make it attractive only when open bins
    // are crowded or the fit would create dead space.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / 8.0;
        score -= 10.0 + 15.0 * crowd;
        if dead {
            score -= 40.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Modulo-class tiebreak on item size: large items (size % 20 in upper half)
    // should prefer tight packing into existing bins.
    let size_class = item_size % 20;
    if size_class >= 10 {
        score -= 6.0;
    }

    // Prefer bins below mean residual (compact bins) to keep others flexible
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable gaps
    // since item sizes >= 1 but realistically small leftovers waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // heavy penalty for creating dead space
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    } else {
        // Reward tight fits proportionally: fill ratio of the bin
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Penalize leaving a gap that the next item could have used
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 8.0; // residual closely matches next item: reserve it
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; smaller residual is fine
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral baseline, penalized slightly so it only
    // wins when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (consolidate fuller bins)
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact chain fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: post_residual exactly equals next item size
        let chain_bonus = (50.0 - gap.min(50.0)) * (1.0 + progress);
        score -= chain_bonus;
        // Penalize leaving residual that is slightly larger than next item (dead space)
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0;
        }
        // Reward residual that leaves room for next item with tight fit
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer minimal residual
        score += (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64).abs() > 40);
        if bad_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Slight penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot host a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 40.0 + 30.0 * pressure + 15.0 * (1.0 - progress);
        // Allow new bin if the item is huge and would leave a very awkward remainder.
        if item_size >= 70 && post_residual <= 20 {
            score -= 35.0;
        }
    }

    // Global residual balance: prefer bins whose residual is near the mean (keeps spread even).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Penalize spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic coupling of post-residual with stream progress.
    // Early in the stream, waste is cheap; later, tight fits matter more.
    let mut score = x * x * (1.0 + 2.0 * t) + x * (1.0 - t);

    // Reward very tight fits (post residual near zero) increasingly over time.
    let tightness = (1.0 - x).powi(3);
    score -= 3.0 * tightness * (0.5 + t);

    // Penalize bins that can't fit the next item when post-residual is small
    // but nonzero (dead space relative to lookahead).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && pr < nx {
            score += (nx - pr) / cap * (1.5 + t);
        }
        // Bonus if the leftover exactly accommodates the next item.
        if (pr as u32) == next_item_size {
            score -= 2.0 + 2.0 * t;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 + t);
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // landscape is crowded or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        let mean_gap = (mean_residual - pr).abs() / cap;
        score += 5.0 + 3.0 * (1.0 - t) * crowding - 2.0 * mean_gap;
        // Late in the stream, opening a fresh bin is less attractive.
        score += 2.0 * t;
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate similar bins), scaled by progress.
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score -= 0.5 * dev * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post / cap; // capacity fraction left over

    // Harmonic class of post_residual: bins whose leftover falls on
    // "useful" residue classes (divisible into small chunks) are favored.
    let pr = post_residual;
    if pr > 0 {
        let class = match pr % 10 {
            0 => -6.0, // perfectly reusable chunk size
            5 => -3.0,
            2 | 4 | 8 => -1.5,
            7 => -2.0,
            _ => 0.0,
        };
        score += class;
        // Integer-division threshold: leftover that can host a mid-size item
        if pr / 25 >= 1 {
            score -= 2.0;
        }
    } else {
        // Perfect closure is excellent.
        score -= 12.0;
    }

    // Penalize large dead space nonlinearly (quadratic waste).
    score += 0.05 * frac * frac * cap;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 0.04 * next_item_size as f64;
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += 0.02 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // would waste badly. Penalize opening new bins mildly, more early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 + 4.0 * (1.0 - progress);
        // But if the item is huge relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 5.0;
        }
    }

    // Prefer filling bins below mean residual (consolidating waste).
    score -= 0.03 * (mean_residual - post).max(0.0);

    // Mild pressure to reduce number of open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item size (1..=10)
    // are effectively unusable; penalize them hard, scaled by tightness.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting into an existing bin when few bins can take the item
    // (avoid opening a new bin when this is nearly the last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are already open and the mean residual is large (existing slack exists).
    if bin_residual == bin_capacity {
        score += 25.0 + 1.5 * open_bins_count as f64 + 0.15 * mean_residual;
        // But if the item is large and would leave a big usable gap anyway,
        // a fresh bin is less harmful.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next <= 10 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
