pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: early in stream, be conservative (favor new bins less);
    // late in stream, consolidate to avoid opening bins for few remaining items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 20.0 * (1.0 - 0.7 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Crowding: many open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins with residual below mean (drive them to closure).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // on wasted space that grows over the stream.
    let mut score = post + 0.35 * (post / cap).powi(2) * cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness.powi(3) * (1.0 + 0.5 * progress);

    // Penalize dead space that no future item (min size 1, typical >= 10) can use:
    // residuals just below typical small items are worst.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 8.0 * dead * (0.4 + 0.6 * progress);

    // Lookahead: bonus if next item fits in post_residual (chain packing).
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 4.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Penalize if next item almost fits but not quite.
        let gap = next_item_size as f64 - post;
        if gap <= 10.0 {
            score += 3.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless mean residual across open bins is very low (all nearly full).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let mean_tight = (mean_residual / cap).clamp(0.0, 1.0);
            score += 10.0 * (1.0 - mean_tight) * (0.6 + 0.4 * progress) + 5.0;
        } else {
            score -= 20.0; // first bin is always good
        }
    }

    // Mild dispersion penalty: bins far from mean residual are less attractive.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward placements leaving residuals
    // in "useful" classes (multiples of common item sizes).
    let harmonic = |r: u32| -> f64 {
        if r == 0 { return -40.0; } // perfect fill, best possible outcome
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50, 5, 100 / 3 + 1] {
            if r % m == 0 { h -= 6.0; }
        }
        if r < 10 { h += 25.0; } // dead space under smallest item
        h
    };
    score += harmonic(post_residual);

    // Lookahead: penalize if next item cannot fit the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else if next_item_size == post_residual {
            score -= 30.0; // chain of perfect fills
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New empty bin candidate: keep it neutral-to-penalized so we only open
    // new bins when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * post_residual as f64;
    }

    // Progress coupling: late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Prefer placing into bins already below mean residual (balancing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "unusable" if it's too small for typical future items (1..=100 unknown,
    // so treat gaps below a soft threshold as waste, with worst zone around 1..=20).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            score += 40.0; // tiny gap: pure waste
        } else if pr < 20.0 {
            score += 18.0; // likely dead space for medium/large items
        } else if pr < 30.0 {
            score += 6.0; // marginal
        }
    }

    // Reward very tight fits (item nearly fills the bin).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: the gap becomes dead space.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into fresh bins;
    // this also makes the new-empty-bin candidate (residual == capacity) less attractive
    // unless its raw post_residual advantage is large.
    score += (open_bins_count as f64).sqrt() * 2.0 * ((bin_residual as f64) / (bin_capacity as f64));

    // Slight preference for bins with above-average residual when many bins are open
    // (consume the fullest bins first is the opposite; here we prefer bins whose
    // residual is close to the item, i.e. small residual, via base term already).
    let residual_frac = (bin_residual as f64) / (bin_capacity as f64);
    score -= residual_frac * 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    // New-bin candidate: opening a new bin should only win if it avoids big dead space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: post_residual = capacity - item_size already large;
        // add a mild opening cost so existing bins with decent fits win.
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
