            score -= 15.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize proportionally to mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins that become tight relative to average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it early or for large items
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let next_fits = next_item_size > 0 && post_residual >= next_item_size;
        let mut penalty = 12.0;
        if post_residual == 0 { penalty += 30.0; } // impossible for new bin; keeps new-bin score high
        if next_fits { penalty += 10.0; }
        if progress < 0.2 { penalty -= 5.0; }
        if item_size >= 70 { penalty -= 8.0; }
        score += penalty;
    }

    // Mild preference for filling bins when many are open (consolidation)
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Base: prefer tight fit (small post_residual), with mild convexity
    score += 0.35 * (post * post) / cap;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: penalize if post residual can't host next item but another bin could,
    // reward if this bin can also host the next item (chaining)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * nx;
        } else {
            score += 6.0 + 0.1 * nx;
            // dead space that next item cannot use
            score += 0.25 * (post / nx) * (nx - post);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).max(1.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 10.0 * pressure + 20.0 * (1.0 - progress);
        // But if item is large relative to mean residual, opening may be fine
        if item > mean_residual * 0.85 {
            score -= 35.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    if open_bins_count > 3 {
        let gap = (mean_residual - post).abs();
        score += 0.05 * (open_bins_count as f64) * (gap / cap);
        // prefer bins below mean residual (tighter than average)
        if post < mean_residual {
            score -= 4.0;
        }
    }

    // Time horizon: early stream, be flexible; late stream, pack tightly
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * t * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Normalized post-residual, non-linearly coupled with stream progress.
    let pr_norm = pr / cap;
    let base = pr_norm.powi(2) * (1.0 + 1.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tight_reward = -(1.0 - pr_norm).powi(2) * (0.5 + 2.0 * progress);

    // Penalize dead space that cannot fit the lookahead item.
    let dead = if next_item_size > 0 && post_residual < next_item_size {
        ((next_item_size - post_residual) as f64) / cap
    } else {
        0.0
    };
    let dead_pen = dead * (1.0 + 2.0 * (1.0 - pr_norm));

    // Last-chance bin: reward using it to avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -1.0 } else { 0.0 };

    // New-bin candidate: mildly penalize when decent fits exist, reward when few.
    let new_bin_pen = is_new * (0.3 + 0.5 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)));

    // Coupling with mean residual: prefer bins close to mean to balance load.
    let mean_coupling = ((mean_residual - pr).abs() / cap) * 0.4 * progress;

    let mut score = base + tight_reward + dead_pen + last_chance + new_bin_pen + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // (dead-space "harmonics" — small residuals are hard to fill later).
    let post = post_residual as i64;
    let class = post % 10;

    // Penalize small awkward residuals (dead space) non-linearly.
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 3.0;
    } else if post == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Modulo-class shaping: residuals that are multiples of 10 or 25 are
    // more "usable" for future items; reward them mildly.
    if post % 10 == 0 && post > 0 {
        score -= 4.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 3.0;
    }
    // Odd, prime-hostile residues get slight penalty.
    if class == 1 || class == 3 || class == 7 {
        score += 1.5;
    }

    // Integer-division thresholds on post_residual.
    let half = bin_capacity / 2;
    if post <= half {
        score -= 2.0; // bin becomes "small" — good, nearly committed
    } else {
        score += (post - half as u32) as f64 * 0.05; // staying large is wasteful
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // big reward; if next item can't fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tight = (post_residual - next_item_size) as f64;
            score -= 6.0 - tight * 0.05;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or stream is early (many items remain to fill it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // A fresh bin wastes its capacity if opened late; penalize more
        // as the stream progresses. Reward early when many items remain.
        score += 20.0 * progress + 2.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits — new bin is necessary
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // next item may also want a big bin
        }
    } else {
        // Prefer denser bins (lower residual relative to mean).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize "nearly full" leftovers that can never be used.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver: worse than leaving a moderate gap
    }
    // Perfect or near-perfect closure is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward tight fits relative to the residual before placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // If this bin is the only one that fits the item, strongly favor using it
    // (avoid opening a new bin when the item would otherwise be homeless).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 2.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if the fleet of open bins already has lots of
    // slack, penalize leaving yet another large residual here.
    if post_residual as f64 > mean_residual {
        score += 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement; if it would not fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 0.15 * next_item_size as f64;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit, by scaling its
    // baseline with stream progression (early on, prefer new bins to keep
    // flexibility; later, prefer filling existing bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 12.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact 2-step match: strong bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item cannot fit here anyway, mild penalty for wasting tight space
        if post_residual < next_item_size && post_residual < 10 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Penalize dead space relative to mean residual (fragmentation avoidance)
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current item leaves huge dead space in every fit
    if bin_residual == bin_capacity {
        // Prefer new bin when item is large and would leave awkward residual elsewhere
        let awkward = (post_residual as f64) > 40.0 && post_residual > 0;
        if awkward && fitting_bins_count >= 1 {
            score -= 55.0;
        } else {
            score += 40.0;
        }
    }

    // Slight preference for fuller bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Post residual too small for the next item: dead-space penalty,
            // scaled by how dead it is relative to the smallest useful item.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins can fit the item, prefer the one with the least residual left
    // (best-fit pressure), mildly.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins whose residual deviates above the mean (fragmentation control),
    // but only for existing bins.
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    // New-bin candidate: opening a fresh bin should only win when the item is large
    // relative to typical residuals, or late in the stream. Penalize otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        // Opening a new bin is attractive when item is big and existing residuals are small.
        let attraction = item_frac - mean_frac;
        score += 40.0 - 55.0 * attraction.max(-1.0) - 15.0 * progress;
        // A fresh bin leaves a huge residual; penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Slight preference for filling bins with larger residual when few bins are open
    // (consolidation) vs. many bins (spread load).
    if open_bins_count > 0 {
        let load_pressure = open_bins_count as f64 / 10.0;
        score += load_pressure * (bin_residual as f64 / bin_capacity as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: waste penalty grows polynomially as stream advances.
    score += prn * prn * (2.0 + 6.0 * p) * cap * 0.5;
    // Cubic coupling: mid-stream favors tight packing more strongly.
    score += prn.powi(3) * cap * (1.0 + 3.0 * p * (1.0 - p));

    // Lookahead: reward residual that can host the next item (subtract).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= (nxt / cap) * (3.0 + 4.0 * p) * (1.0 - prn);
        } else {
            // residual too small for next item: penalize dead space smoothly.
            score += (1.0 - nxt / cap) * (1.0 + 2.0 * p);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * p;
    }

    // Deviation from mean residual: prefer bins near mean to keep balance,
    // with non-linear (quadratic) coupling scaled by progress.
    let dev = pr - mean_residual;
    score += (dev * dev) / cap * (0.5 + 1.5 * p);

    // Mild reward for using existing bins vs opening new ones, stronger early.
    if bin_residual != bin_capacity {
        score -= 1.5 * (1.0 - p);
    } else {
        // New-bin candidate: penalize more late in the stream, smoothly.
        score += 2.0 + 4.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "friendly"
    // to common item sizes via modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty grows super-linearly for small, awkward residuals.
    if pr > 0 {
        let awkward = (pr < 10) as f64 * 30.0
            + (pr >= 10 && pr < 20) as f64 * 12.0;
        score += awkward;
    } else {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    }

    // Harmonic class: residuals congruent to 0 mod 25 or 0 mod 20 pair well
    // with typical item sizes drawn from capacity fractions.
    let friendly = (pr % 25 == 0) as f64 * 15.0 + (pr % 20 == 0) as f64 * 10.0;
    score -= friendly;

    // Penalize residuals that are just below a "hard" threshold class
    // (integer division bands: pr in [51..59] etc. are hard to fill).
    let band = pr / 10;
    let band_penalty = match band {
        5 => 8.0,
        6 => 5.0,
        7 => 3.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportionally to how tight the fit is.
            let tightness = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 10.0 * tightness;
        } else {
            // Next item won't fit here: slight penalty if it would have fit
            // the pre-placement residual (we "wasted" a compatible bin).
            if next_item_size <= item_size {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper (builds inventory).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many open bins already, discourage one more unless stream is long.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild preference for bins with residual close to the mean (balance load).
    score += (prf - mean_residual).abs() * 0.05;

    // Small tie-breaker favoring tighter fits overall.
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward tight fits relative to bin capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Penalize bins whose residual is far above mean (fragmentation pressure).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, new-bin candidate is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open or stream is early
        // (early stream: keep bins compact to build future tight fits).
        score += 25.0 + open_bins_count as f64 * 1.5 + (1.0 - progress) * 10.0;
    } else {
        // Existing bin: mild reward scaled by how crowded the bin already is.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 6.0 {
            score -= 20.0 - slack * 2.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use at all.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (low post_residual).
    score -= (post_residual as f64).powi(3) / (bin_capacity as f64).powi(2) * 2.0;

    // Aggressive 2-step lookahead: if the next item fits the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0 + (slack_after_next as f64).powi(2) / 100.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a gap that the next item cannot use (dead space).
        score += (next_item_size as f64 - post_residual as f64).min(next_item_size as f64) * 0.5;
    }

    // Relative residual context: bins tighter than the mean are better fill targets.
    let rel = (bin_residual as f64) - mean_residual;
    score -= rel * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (large item relative to mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = item_size as f64 / bin_capacity as f64;
        let mean_tight = mean_residual / bin_capacity as f64;
        let bonus = 25.0 * (pressure - mean_tight) + 10.0 * progress;
        score += bonus; // negative bonus makes new bin attractive when open bins are tight
    }

    // Mild penalty for wasting a very roomy bin on a small item.
    if item_size < 30 && bin_residual > 70 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: post-residual too small to ever be useful (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits in the post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Time horizon: early in the stream, prefer opening new bins to keep flexibility;
    // later, prefer packing into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = (1.0 - progress) * 15.0;
    if bin_residual == bin_capacity {
        score += new_bin_bias;
        // Opening a new bin is fine when mean residual across open bins is high (all loose).
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: tight fits rewarded super-linearly.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize large dead space with a quadratic blow-up term.
    score += 0.02 * pr * pr / cap;

    // Early stream: prefer filling existing bins aggressively (open fewer bins).
    // Late stream: allow new bins when fit is poor (progress coupling).
    let new_bin_bias = 8.0 * (1.0 - progress) * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += 6.0 + new_bin_bias;
    }

    // Last-chance bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many open bins with high mean residual: discourage spreading waste.
    if open_bins_count > 0 {
        score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual / cap).max(0.0);
    }

    // Lookahead synergy: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let synergy = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * synergy;
    } else if next_item_size > 0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: class = post_residual / 10
    let class = post_residual / 10;
    // Penalize dead space in the "awkward" harmonic classes (1..=9 residual),
    // reward residuals that are multiples of 10 (likely to pair with future items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    } else {
        // mid-class residuals get graded penalty by distance to nearest multiple of 10
        let dist = (post_residual % 10).min(10 - post_residual % 10);
        score += dist as f64 * 0.8;
    }

    // Reward tight fits (small post_residual in a good class)
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item's class divides post_residual class
            let nc = next_item_size / 10;
            let pc = post_residual / 10;
            if pc > 0 && nc > 0 {
                if pc % nc == 0 {
                    score -= 12.0;
                } else {
                    score += 4.0;
                }
            }
        } else {
            // next item can't use this residual: penalize wasted harmonic classes
            score += (next_item_size.min(post_residual) as f64) * 0.1 + 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately unattractive unless residual space
    // management is bad (many open bins with large mean residual).
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 10.0;
        }
        // early stream: allow new bins more readily
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already more depleted than average
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward residual close to item size (tight but usable fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 40.0 / (1.0 + tightness);

    // Penalize bins whose residual is much larger than needed (wasteful use of big space).
    if bin_residual as f64 > item_size as f64 * 2.0 {
        score += 0.35 * (bin_residual as f64 - item_size as f64 * 2.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap < 10 {
            score -= 30.0;
        }
    }
    // If next item would NOT fit here, mild penalty for delaying a better bin.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Mean residual coupling: prefer bins below mean residual (consolidate fullness).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if post_residual > 60 {
            score -= 30.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 500.0; // never open a bin for an item creating tiny dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal dead space after placement.
    score = post_residual as f64;

    // Strong penalty for leaving dead space that no future item can likely use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // 2-step lookahead: exact match is a jackpot.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward, stronger the tighter it is
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item of the stream: just minimize residual
        score = post_residual as f64;
    }

    // Relative-to-mean residual coupling: bins below mean residual are "tight"
    // and valuable; wasting them is costly. Bins far above mean are roomy and
    // can absorb awkward placements.
    let diff = mean_residual - post_residual as f64;
    score += 0.25 * diff;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: among many fitting bins, keep the discrimination
        // driven by residual/lookahead terms only.
        score += 0.0;
    }

    // New-bin candidate handling: an empty bin has full residual. It should
    // only win when no open bin offers a decent fit. Penalize opening a new
    // bin mildly, more so when good fitting bins exist and the stream is
    // still early (waste compounds over a long stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            new_bin_penalty += 12.0 * (fitting_bins_count.min(5) as f64);
        }
        // lookahead: opening a fresh bin is fine if next item is large
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference to fill more crowded bins (fewer open bins overall).
    score += 0.05 * open_bins_count as f64;

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 8.0 * (fill_ratio - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows quadratically as post_residual shrinks.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += post_residual as f64 * 0.5;
        } else if post_residual == next_item_size {
            // Perfect chain fit: strongly reward.
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is attractive early or
    // when the item fits badly everywhere, but expensive when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let badness = (item_size as f64 / bin_capacity as f64).powi(2);
        // New bin baseline score: moderate; cheap when few bins open or item large.
        score = 30.0 + open_pressure * 4.0 - badness * 15.0 - (1.0 - progress) * 5.0;
        // If the item leaves a residual that matches a common small size, opening is fine.
        if post_residual >= 10 && post_residual <= 30 {
            score -= 6.0;
        }
        return score;
    }

    // Global state coupling: prefer filling bins with above-average residual
    // (draining the "fattest" bins first keeps the bin set compact).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Late in the stream, consolidation matters more: penalize leftover space harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += fit_ratio * progress * 10.0;

    // Many open bins: encourage aggressive packing into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = post * post / cap;

    // Smooth polynomial coupling with stream progress: early on, tolerate slack;
    // later, demand tighter packing (post_residual penalized more heavily).
    score += post * (0.5 + 1.5 * progress) * (post / cap);

    // Penalize post_residuals that are "dead space" relative to the next item:
    // if the next item cannot fit in the leftover, the leftover is likely wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // unusable for next item -> penalty growing non-linearly
            score += (nxt - post) * (nxt - post) / cap * 2.0;
        } else {
            // reward leaving room exactly usable by the next item
            score -= (post - nxt).min(20.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin (smooth exponential reward).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate (empty bin): only attractive when it beats poor fits.
    // Make it costly by default, but cheaper when residuals across open bins
    // are already fragmented (high mean residual, many open bins).
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * (1.0 - progress));
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score -= 40.0 * fragmentation * (open_bins_count as f64).sqrt().min(5.0);
    }

    // Mild preference for filling fuller bins (lower residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // Harmonic class of post_residual modulo capacity quarters: reward residuals
    // that fall into "usable" classes for typical small items.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    match class {
        0 => score -= 60.0,          // tiny residual, nearly full bin
        1 => score += 30.0,          // awkward quarter leftover
        2 => score += 10.0,          // half leftover, moderately useful
        _ => score -= 20.0,          // large residual, flexible
    }

    // Reward if the lookahead item fits exactly into post_residual (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 80.0;
        } else {
            // next item won't fit here: penalize proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
        if post_residual > quarter {
            score += 50.0;
        }
    }

    // New-bin candidate handling: only open a new bin when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing else fits: new bin is required
        } else {
            // discourage opening new bins when existing bins fit decently
            let best_possible_waste = 100u32; // worst-case item size
            score += 150.0
                + (open_bins_count as f64) * 5.0
                + (mean_residual.max(0.0) * 0.3);
            let _ = best_possible_waste;
        }
    }

    // Prefer filling bins with larger residuals early in the stream (keep tight bins tight).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 - mean_residual) * (0.4 - 0.2 * progress);

    // Mild pressure to reduce number of open bins as stream progresses.
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Penalize creating residuals in the "dead zone" (1..10 minus exact small classes)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // any plausible future item (<= 10) are pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the lookahead item are semi-dead if lookahead exists.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins;
    // expressed as a penalty relative to whether this IS a new bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or
        // the item is large relative to the mean residual (poor fit elsewhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 45.0 * open_bins_count as f64 - 20.0 * progress;
        if next_item_size > 0 && item_size >= 60 && mean_residual < item_size as f64 {
            score -= 50.0; // big item with poor fits elsewhere: new bin is fine
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps a balanced portfolio of residuals for future items).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small leftover: strong reward
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.5;
    }
    // Next item cannot fit: penalize proportionally to wasted lookahead potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize tiny dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative residual alignment with mean residual
    score += (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: make it unattractive unless post_residual is huge
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    // Early in stream: prefer filling few bins well
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how full the bin becomes
    score -= 1.5 * fill * fill * (bin_capacity as f64);

    // Lookahead coupling: if the next item would fit exactly in post_residual,
    // strongly reward; if next item barely misses, penalize dead space creation.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    } else {
        // Last item: prefer zero residual absolutely
        score += 0.0;
        score -= 2.0 * fill;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead space penalty: very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 5.0 + 10.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with low mean residual -> consolidate,
    // favor bins below mean residual (tighter bins) to close them out.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 4.0 * dev;
        if mean_residual < bin_capacity as f64 * 0.25 {
            score -= 3.0;
        }
    }

    // Early in the stream, allow opening new bins for large items to keep
    // flexibility; late in the stream, strongly prefer existing bins.
    let new_bin_bias = (1.0 - progress) * (item_size as f64 / bin_capacity as f64) * 12.0;
    if bin_residual == bin_capacity {
        score += 4.0 - new_bin_bias;
        // Empty-bin candidate: penalize if plenty of fitting bins exist
        if fitting_bins_count > 0 {
            score += 2.0 * fitting_bins_count as f64;
        }
    }

    // Mild penalty for wasting a large residual on a small item
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 2.0 * waste * waste * (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth quadratic falloff)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).powi(2) * progress;

    // New-bin candidate: prefer it only when post_residual is full capacity and few bins fit
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (fitting_bins_count as f64).powf(0.5) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, with a quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of post_residual: dead space that is "harmonically useful"
    // (divisible into small chunks) is less bad than odd dead space.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                       // perfect fit
        1..=10 => -6.0,                 // small waste, likely reusable
        11..=25 => 4.0,                 // awkward mid-range dead space
        26..=50 => 0.0,
        _ => -2.0,                      // large residual still fairly usable
    };
    score += class;

    // Modulo arithmetic on post_residual: residuals divisible by small common
    // item sizes (5, 10, 20) are more likely to be filled later.
    let div_bonus = if pr > 0 {
        let mut b = 0.0;
        if pr % 10 == 0 { b -= 5.0; }
        else if pr % 5 == 0 { b -= 3.0; }
        if pr % 20 == 0 { b -= 2.0; }
        if pr % 25 == 0 { b -= 2.0; }
        // odd residuals that are not multiples of 5 are worst
        if pr % 2 == 1 && pr % 5 != 0 { b += 3.0; }
        b
    } else { 0.0 };
    score += div_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let gap = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit into
    // open bins is poor (large post_residual relative to capacity) or the item
    // is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frac_used = item_size as f64 / bin_capacity as f64;
        // Penalize new bins early; allow them more when many bins are open
        // (amortized) or when mean residual is small (open bins are full).
        score += 30.0 - 20.0 * progress - (open_bins_count as f64).min(10.0) * 0.8;
        if mean_residual < frac_used * bin_capacity as f64 {
            score -= 15.0;
        }
        if item_size > 50 {
            score -= 5.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (keep a spread
    // of residual sizes for future items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever hold another item
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, ideal
    } else if post_residual <= 15 {
        // small unusable gap: dead space penalty grows as gap shrinks
        score += (16 - post_residual) as f64 * 4.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Reward bins whose residual is consumed to a value matching the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // leaves exact space for lookahead
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 5.0; // lookahead cannot use this bin afterwards
        }
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (their space is still broadly useful; avoid wasting large residuals).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score -= (-dev) * 0.1;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild stream-progression bias: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * fill;

    // New-bin candidate: make it unattractive unless this bin would be a near-perfect fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fill > 0.7 {
            score -= 20.0; // allow opening a bin for big items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post - nxt;
        // perfect match bonus: gap 0 => subtract a lot; decays quickly
        let match_bonus = (60.0 * (-gap / 8.0).exp()) * (1.0 + 0.5 * progress);
        score -= match_bonus;
    } else if next_item_size > 0 {
        // dead space for the next item: penalize proportionally
        let dead = nxt - post;
        score += 0.6 * dead * (1.0 + progress);
    }

    // Penalize creating very small unusable residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post / 10.0);
    }

    // Prefer tighter fills relative to mean residual of open bins
    if post < mean_residual {
        score += 0.3 * (mean_residual - post);
    } else {
        score -= 0.15 * (post - mean_residual).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (item / cap) < 0.5 && fitting_bins_count > 0;
        score += if poor_fit && next_item_size > 0 && next_item_size >= item_size {
            -10.0 // open a fresh bin to keep space for the upcoming item
        } else {
            30.0 + 20.0 * (1.0 - progress)
        };
    }

    // Mild reward for high fill ratio
    score -= 0.2 * (item / cap) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that nothing could ever fill: post_residual too small
    // for the smallest plausible item (assume >= 1, but weight small leftovers).
    if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use leftover: mild penalty for hoarding space.
            score += 2.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins over opening new ones.
    if open_bins_count > 0 {
        let crowding = mean_residual / bin_capacity as f64;
        score -= 3.0 * crowding;
    }

    // Time horizon: early in stream, encourage compact packing; late in stream,
    // be more tolerant of opening bins to reduce risk.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when the item fits
    // poorly everywhere else (large item or many open bins with poor fits).
    if bin_residual == bin_capacity {
        score += 5.0;
        if item_size > 60 {
            score -= 3.0;
        }
        if open_bins_count > 3 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (norm_pr * cap - mean_residual).abs();

    // Lookahead coupling: reward bins whose residual matches next item
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let match_term = 1.0 - (norm_pr - next_norm).abs();
        score -= 15.0 * match_term * match_term;
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Smooth new-bin handling: empty bin gets a moderate default score
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common item
    // sizes (harmonic classes) are more reusable than odd leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        // Harmonic check against small modulus classes (5, 10, 20, 25, 50)
        if pr % 50 == 0 { harmony_bonus += 30.0; }
        else if pr % 25 == 0 { harmony_bonus += 22.0; }
        else if pr % 20 == 0 { harmony_bonus += 18.0; }
        else if pr % 10 == 0 { harmony_bonus += 12.0; }
        else if pr % 5 == 0 { harmony_bonus += 6.0; }
        // Perfect-fill potential: next item exactly consumes the residual
        if next_item_size > 0 && next_item_size == pr {
            harmony_bonus += 60.0;
        } else if next_item_size > 0 && next_item_size <= pr {
            // next item leaves another harmonic residual
            let npr = pr - next_item_size;
            if npr % 10 == 0 { harmony_bonus += 15.0; }
            else if npr % 5 == 0 { harmony_bonus += 7.0; }
        } else if next_item_size > pr && next_item_size > 0 {
            // dead space: next item cannot use this residual at all
            harmony_bonus -= 20.0;
        }
    } else {
        // bin closed perfectly — best possible outcome
        harmony_bonus += 80.0;
    }

    // Integer-division thresholds on post_residual: classify usability
    let usable = pr / 10; // largest standard item class that fits
    let usability = match usable {
        0 => -25.0,                       // dead space < 10
        1 => 8.0,                         // fits only tiny items
        2..=4 => 3.0,                     // medium leftovers
        _ => 10.0,                        // large residual, very reusable
    };

    score -= harmony_bonus;
    score -= usability;

    // Tight fit reward: residual nearly consumed
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.7 { score -= 15.0 * (fill_ratio - 0.7); }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // heavily fragmented (mean residual too small for typical items).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bin only when open bins are fragmented or stream is late
        if fragmentation < 0.30 || progress > 0.85 {
            score += 5.0;
        } else {
            score += 40.0 + 25.0 * fragmentation;
        }
        // slight damping when very few bins are open (cheap to open early)
        if open_bins_count < 3 { score -= 10.0; }
    }

    // Mild preference for bins whose residual is below the mean (consolidate
    // small leftovers into fewer bins).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Tie-break: prefer bins with smaller index-equivalent residual noise via
    // modulo signature (favor residuals in the same decade class as item).
    let decade = item_size / 10;
    if pr >= 10 && (pr / 10) >= decade { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are unusable dead space: heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 50.0;
    }
    // Small gaps that likely can't fit typical future items (unknown distribution):
    // penalize residuals in the "awkward" band proportionally.
    if post_residual > 0 && post_residual <= 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // --- Reward tight fits ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Lookahead: does the residual still fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0; // residual remains useful
        } else {
            score += 3.0; // residual becomes dead space for the next item
            if post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // --- Last-chance bin: strongly favor using it before opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Open bins pressure: many open bins -> discourage spreading, encourage packing ---
    let open_pressure = open_bins_count as f64 / 10.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // --- Mean residual coupling: prefer bins whose post-residual is below mean
    // (packing into fuller bins first) ---
    score += (post_residual as f64 - mean_residual) * 0.2;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable when no open bin fits well,
        // or when open bins are nearly full (their residuals are small anyway).
        let stream_progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_alternatives = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of a new bin grows with number of already open bins
        // (discourage bin proliferation), but relaxes early in the stream.
        score = 30.0 + open_bins_count as f64 * 2.0 - stream_progress * 5.0;
        // If the only fitting bins have large residuals (wasteful fits),
        // a fresh bin becomes more attractive.
        if fitting_bins_count > 0 && mean_residual > 40.0 {
            score -= 10.0;
        }
        if poor_alternatives > 0.0 && next_item_size > post_residual && next_item_size > 0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect 2-step fit: post_residual exactly matches next item.
        if (post_residual as u32) == next_item_size {
            score -= 40.0;
        }
        // Near-perfect 2-step fit: next item fits snugly with small slack.
        else if next_item_size <= post_residual {
            let slack = pr - nxt;
            // Reward proportionally to how snug the follow-up fit is.
            score -= 25.0 * (1.0 - slack / nxt.max(1.0));
            // Extra reward if slack is tiny (<= 5).
            if slack <= 5.0 {
                score -= 10.0;
            }
        }
        // Next item would NOT fit in this bin: penalize proportionally to
        // how much dead space is left relative to next item size.
        else {
            let gap = nxt - pr;
            score += 8.0 * gap.min(30.0) / 10.0;
        }

        // Coupling with mean residual: bins far below mean residual are
        // already tight; placing here is cheap. Bins far above mean
        // residual waste space; penalize.
        score += 0.15 * (post_residual as f64 - mean_residual);

        // If the next item cannot fit anywhere else well, prefer keeping
        // this bin's residual compatible with it.
        if next_item_size <= post_residual && post_residual <= next_item_size + 8 {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize leftover dead space strongly.
        score *= 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (< 10) that likely
    // become dead space for typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect closure is great.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Late in the stream, prefer tightening existing bins over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor filling existing bins.
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Never favor opening a new bin unless current bins are truly bad fits.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: neutral residual minus a mild bonus
        // so it only wins when open bins have large residuals.
        score += 5.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0; // open bins can't host the next item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: smaller post_residual is already lower, amplify it
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight_fit * tight_fit;

    // Penalize dead space that no future item can plausibly fill:
    // small residuals (< smallest plausible item) are wasted
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - next_tight / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to how much
            // space is stranded relative to the next item
            score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post residual, no future to worry about
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading; if this bin's residual is below
    // the mean, it is a "fuller" bin, reward it.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.10 * residual_gap * (1.0 + progress);

    // When few bins are open, opening new bins is cheap; when many are open,
    // penalize the new-bin candidate more (it increases open_bins_count).
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        score += 20.0 + 3.0 * crowding * (0.5 + progress);
        // But if mean residual is very low (all bins nearly full), new bin is fine
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Early stream: slightly favor keeping large residuals for flexibility
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly scaled
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste is heavily penalized.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += 0.5 * pr * norm_pr * progress_weight;

    // Reward near-perfect fits with a smooth quadratic bonus
    let fit_quality = 1.0 - norm_pr;
    score -= 2.0 * fit_quality * fit_quality * (1.0 + progress);

    // Penalize bins whose residual is far below mean residual (wasteful use of a roomy bin)
    score += 0.1 * (mean_residual - pr).max(0.0) * (1.0 + progress);

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if post residual
    // is smaller than next item, mildly penalize creating dead space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (pr - nxt) / cap;
        } else {
            score += 0.3 * (nxt - pr) * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals near multiples of
    // common item sizes (or capacity fractions) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Distance to nearest "harmonic" residual class (multiples of 10
        // and common sizes 20/25/30/40/50) gets a discount.
        let mut best = 10u32;
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80, 100].iter() {
            let d = (*m as i64 - pr as i64).abs() as u32;
            if d < best { best = d; }
        }
        score -= (10 - best) as f64 * 0.6;

        // Exact modulo structure: leftover divisible by 10 is highly usable.
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 1.5; }
        // Very small awkward leftovers are dead space; penalize.
        if pr < 10 { score += (10 - pr) as f64 * 2.0; }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            if chain_left % 10 == 0 { score -= 4.0; }
            score -= (chain_left as f64).sqrt() * 0.3;
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; decay over the stream (later items
        // tolerate more bins since stream is long).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 25.0 - 8.0 * progress + open_bins_count as f64 * 0.5;
        // If the item fills a large fraction of a fresh bin, opening is fine.
        new_bin_score -= (item_size as f64 / cap) * 10.0;
        // If next item pairs well with the leftover of a fresh bin.
        if next_item_size > 0 && (cap - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            new_bin_score -= 8.0;
        }
        score = new_bin_score;
    }

    // Tight fits (small post_residual relative to item) are excellent.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    // Slight preference for packing into emptier-than-average bins when many
    // bins are open (balance residual distribution harmonically).
    if bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) / cap;
        score += dev * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never serve typical
    // future items are heavily penalized (non-linear blowup).
    let dead_threshold = 10u32.min(bin_capacity / 2);
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 40.0 * (1.0 + (dead_threshold as f64 - post_residual as f64) / dead_threshold as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits generally (small waste relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage scattering items when
    // many bins are open; encourage consolidating into existing bins.
    score += 2.0 * open_bins_count as f64;
    score -= 1.5 * fitting_bins_count as f64;

    // New-bin candidate handling: only attractive when current bins are
    // badly fragmented or this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.5 && post_residual > 0 && post_residual < 20;
        if fragmentation > 0.6 || poor_fit {
            score -= 45.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= dead_threshold {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit here anyway, dead space here is less costly
    // only if it is tiny; otherwise slightly penalize blocking.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early in the stream, allow slightly more freedom to open bins to
    // build a good spread; late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item also fits: good chaining
            score -= 40.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit: residual becomes dead space for the lookahead
            score += 25.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize small unusable residuals relative to item size floor
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.3;
        // but if no existing bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Penalize leaving small unusable slivers (dead space < next item size or tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can fit into the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if (item_size + next_item_size) as f64 == bin_residual as f64 {
            score -= 30.0;
        }
    } else {
        // Last item: prefer fullest possible fill.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a needless new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, mild competition pressure toward tighter fits.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: if mean residual is high, prefer using existing space
    // rather than opening new bins; penalize scattering into low-residual bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (bin_residual as f64) < mean_residual {
        score += 6.0 * (1.0 - progress);
    } else {
        score -= 4.0 * mean_residual / bin_capacity as f64;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if fitting_bins_count == 1 {
            // Existing sole candidate is poor: allow a new bin if it would leave
            // less dead space than squeezing here.
            penalty -= 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            // A fresh bin pairs well with the lookahead item.
            penalty -= 10.0;
        }
        if open_bins_count == 0 {
            penalty = -100.0;
        }
        // Late in the stream, opening bins is less costly (tail truncation risk low).
        penalty -= 5.0 * progress;
        score += penalty;
    }

    // Mild reward for bins that are already partially loaded (consolidation).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += 0.35 * coupling;

    // Penalize wasted space more strongly later in the stream (smooth ramp)
    score += 12.0 * progress * norm_pr * cap * 0.1;

    // Reward tight fits: subtract when post_residual is small relative to item size
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: reward bins whose residual could host the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = ((pr - ns) / cap).max(0.0);
        score -= 10.0 * (1.0 - fit_next * fit_next) * (pr >= ns) as i32 as f64;
    } else {
        // Last item: strongly prefer exact fills
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus (only bin that fits)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to reuse bins when many are open
    score -= 0.5 * open_bins_count as f64 * (1.0 - norm_pr);

    // New-bin candidate: neutral-ish baseline with smooth discouragement early
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) * pr / cap * cap / cap * cap;
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals divisible by common item sizes are more usable
    let r = post_residual;
    if r > 0 {
        // residual that is an exact multiple of 10 (harmonic with capacity 100) is more reusable
        if r % 10 == 0 {
            score -= 8.0;
        }
        // check divisibility by next item size -> guarantees next item fits exactly
        if next_item_size > 0 && r % next_item_size == 0 && r >= next_item_size {
            score -= 25.0;
        }
        // residual exactly equal to next item size is a perfect lookahead fit
        if next_item_size > 0 && r == next_item_size {
            score -= 60.0;
        }
        // penalize residuals in awkward bands (too small to hold min item)
        if r < 10 {
            score += 30.0 * (10 - r) as f64;
        }
        // integer division thresholds: classify residual into harmonic buckets
        let bucket = r / 20; // 0..5
        score -= bucket as f64 * 2.0;
        // modulo coupling with capacity fraction
        let half = bin_capacity / 2;
        if r > half {
            score -= 5.0; // keep large-capacity bins attractive
        }
    }

    // lookahead: penalize if next item cannot fit in this bin's post-residual
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 {
        // reward leaving room for the next item
        score -= (next_item_size - (post_residual - next_item_size).min(next_item_size)) as f64 * 0.1;
    }

    // last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // new-bin candidate: prefer opening a new bin only when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 15.0;
        // if current bin would leave lots of dead space, prefer new bin
        if post_residual < 20 && bin_residual < bin_capacity {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // stream progression: as stream nears end, close bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * mean_residual / 100.0;

    // slight preference for fuller bins among equals
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest plausible item (<= 10) are pure waste; punish them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 25 {
        // Small gaps are only usable by tiny items; penalize proportionally.
        score += (25.0 - post_residual as f64) * 1.2;
    } else {
        // Large usable residuals are mildly attractive.
        score -= 5.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * fill_ratio * 40.0;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement creates a chain — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap; if gap is small it becomes dead space.
        if post_residual < next_item_size && post_residual < 30 {
            score += 15.0;
        }
    }

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: its post_residual is large, but add explicit cost.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // If this is the only fitting bin, opening a new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    // but only among open bins; for the new bin this term is ~0.
    if !is_new_bin {
        score -= (bin_residual as f64 - item_size as f64).abs().max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: next item fills this bin exactly.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits here: prefer leaving a tight-but-usable remainder.
            let rem_after_next = post_residual - next_item_size;
            score -= 20.0 - (rem_after_next as f64).min(20.0);
            score += (rem_after_next as f64) * 0.15;
        } else {
            // Next item won't fit after this placement: penalize proportionally.
            let overflow = next_item_size as f64 - post_residual as f64;
            score += overflow * 0.35;
        }
        // Smooth penalty on absolute mismatch to lookahead demand.
        score += gap * 0.08;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // placing here uses scarce space efficiently.
    let rel = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += rel * 25.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating small unusable dead space (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin gives a good fit
    // (i.e., this call's residual is full and existing fits are poor).
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a tight fit, but below heavily
        // mismatched lookahead placements.
        score = 55.0 + (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can serve the next item too.
            if next_item_size + item_size <= bin_capacity {
                score -= 12.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit reward: strongly favor bins where the item exactly fills the residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: the smaller post_residual is relative to capacity, the better.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Lookahead coupling: if the next item can fit into post_residual, reward this placement;
    // if next item would be stranded by a large post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 0.10 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 20 {
            score -= 15.0;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, accept fits more readily to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Global state: when many bins are open, prefer consolidating into existing bins
    // rather than opening new ones; when few bins are open, new-bin is cheaper.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring: penalize when many bins already open,
        // and when mean residual suggests existing bins could absorb items.
        score += 10.0 + open_bins_count as f64 * 1.5 + mean_residual * 0.05;
        if next_item_size > 0 && next_item_size <= mean_residual {
            score += 8.0; // existing bins likely fit next item too
        }
    } else {
        // Fitting an existing bin: slight extra reward when bins are numerous.
        score -= open_bins_count as f64 * 0.5;
    }

    // Mean residual alignment: prefer bins whose residual is close to the item size
    // (minimizes leftover deviation from the fleet average).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual warped by stream progress
    let warp = 1.0 + 2.0 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= warp;

    // Smooth penalty for large unusable residuals, amplified with progress
    let dead = (norm_pr * norm_pr) * cap;
    score += dead * (0.5 + progress);

    // Reward tight fits via smooth saturating term
    let tight = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 30.0 * tight * tight * (1.0 + progress);

    // Last-chance bin bonus (smooth, not hard threshold)
    let last_chance = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 20.0 * last_chance * last_chance;

    // Lookahead: penalize if post_residual can't fit next item smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 15.0 * (1.0 - fits_next) * (0.5 + progress);
        let snug = 1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64 / cap);
        score -= 10.0 * snug.max(0.0) * snug * fits_next;
    }

    // Mean residual coupling: prefer bins deviating below mean late in stream
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress) - 5.0 * dev * progress;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small divisors.
    let pr = post_residual;
    let class3 = pr % 3;   // tiny residues -> near-perfect fit bonus
    let class5 = pr % 5;
    let class10 = pr % 10;

    // Reward post-residuals that fall into "harmonically clean" classes
    // (residual divisible by common item granularity -> more reusable).
    if class3 == 0 { score -= 6.0; }
    if class5 == 0 { score -= 4.0; }
    if class10 == 0 { score -= 5.0; }
    // Penalize awkward residues (1 or 2 mod 3, non-zero mod 5)
    score += (class3 as f64) * 1.5 + (class5 as f64) * 0.8;

    // Integer-division thresholds on post_residual: bucket the leftover space.
    // Buckets: 0 (perfect), 1..=10 (tight), 11..=30 (usable), 31..=60 (awkward), >60 (wasteful)
    let bucket = match pr {
        0 => 0.0,
        1..=10 => 1.0,
        11..=30 => 2.0,
        31..=60 => 3.0,
        _ => 4.0,
    };
    score += bucket * 7.0;

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward exact divisibility classes between leftover and next item
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
            // Reward when next item nearly fills the leftover (tight chain)
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 6.0;
            }
            score -= (next_item_size as f64) * 0.15;
        } else {
            // Next item cannot use this residual: penalize proportionally
            score += 8.0 + (next_item_size - pr) as f64 * 0.1;
        }
    } else {
        // Last item: prefer minimal leftover strongly
        score -= 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish, but slightly worse than a good fit
    if bin_residual == bin_capacity {
        score += 3.0;
        // If stream is early and mean residual is low, opening fresh bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 && open_bins_count < 4 {
            score -= 2.0;
        }
    }

    // Prefer filling bins with larger relative occupancy
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is a "small leftover" bin -> good to consume it now.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to ever be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing efficiency.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Coupling with mean residual: prefer bins whose residual is close to the
    // item (avoid wasting large residuals on small items).
    let waste = bin_residual as f64 - item_size as f64;
    score += (waste / bin_capacity as f64) * 25.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    score += bin_pressure * 0.4;

    // New-bin candidate handling: an empty bin starts with full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is acceptable only if it is early in the stream,
        // few bins are open, or the item would leave a big dead gap elsewhere.
        let big_gap_penalty = if post_residual > 0 && post_residual < 10 { 100.0 } else { 0.0 };
        score += 45.0 + bin_pressure * 0.6 - big_gap_penalty;
        // Late in the stream, avoid opening new bins unless nothing fits well.
        if progress > 0.7 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = (post_residual - next_item_size) as f64;
        score -= (1.0 - chain_quality / bin_capacity as f64) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fills the residual left behind
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item fits into this bin's post residual: strong reward
            score -= 50.0 * (1.0 - (pr - ni) / bin_capacity as f64);
            if ni == pr as u32 {
                score -= 500.0; // exact chain fit
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.5 * (ni - pr).min(pr);
        }
    }

    // Relative residual vs mean: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep neutral-ish unless nothing fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        // open new bin early in stream less penalized
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: later items should tighten packing (waste less).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core waste term: quadratic penalty on large leftover space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead coupling: reward bins whose post_residual can host the next item exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits here too: strong reward, scaled by tightness.
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to overshoot.
            score += 0.08 * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer fuller bins (small residual before placement) — best-fit flavor.
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    // Global pressure: when many bins are open, discourage new-bin tendencies
    // by rewarding placements that consume mean residual efficiently.
    let openness = open_bins_count as f64;
    score -= 0.5 * (mean_residual - post_residual as f64).max(0.0) * (openness / (openness + 4.0));

    // New-bin candidate handling: empty bin has post_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Early on, opening a new bin is cheap; later it is expensive.
        score += 3.0 + 14.0 * progress;
        // If several bins fit the item, opening new is almost never right.
        if fitting_bins_count > 1 {
            score += 8.0;
        }
        // If next item is small, an empty bin wastes future flexibility less; mild discount.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 4.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Late-stream urgency: as stream ends, compress everything into existing bins.
    if progress > 0.8 {
        score += progress * post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;
    // smooth polynomial coupling: prefer small post_residual, weighted by progress
    let pr = post_residual as f64;
    score -= 12.0 * (1.0 - pr / bin_capacity as f64).powi(3) * (1.0 + progress);
    // penalize large post_residual more as stream progresses
    score += 8.0 * (pr / bin_capacity as f64).powi(2) * progress;
    // lookahead: reward bins whose post_residual can't fit next item (avoid wasting exact fits)
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 * (1.0 - progress);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }
    // new-bin candidate: penalize opening new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
        if mean_residual < 8.0 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }
    // dead-space penalty for medium waste
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes model "dead space quality".
    let cls = post_residual % 10;
    // Residuals in {0} are perfect; small odd residuals (1,3,7,9) are nearly unusable dead space.
    score -= 40.0 * (1.0 - cls as f64 / 10.0); // base reward scaled by class digit
    if post_residual == 0 {
        score -= 100.0; // perfect fit: strong reward
    }
    if post_residual < 10 {
        score -= 30.0; // sub-minimum dead space is worthless anyway
    } else if post_residual <= 20 {
        // 10..20 band: usable only by small items; value depends on class
        if cls == 0 {
            score -= 25.0; // 10 or 20: reusable round residual
        }
    } else {
        // Larger residuals are valuable; integer-division thresholds
        let half = bin_capacity / 2;
        if post_residual >= half {
            score -= 20.0; // bin still half-empty: keep it flexible
        }
        if post_residual % 20 == 0 {
            score -= 8.0; // round residuals pair well with common sizes
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus, stronger for exact/near-exact next fits
            let gap = post_residual - next_item_size;
            score -= 25.0 + 15.0 * (1.0 - gap as f64 / post_residual.max(1) as f64);
            if gap == 0 {
                score -= 40.0; // exact two-item chain
            }
        } else {
            // Next item won't fit here; penalize if it also fits few other bins
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }
    // Crowding pressure: many open bins -> prefer tightening existing ones.
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count.min(20) as f64).sqrt();
    }

    // Mean residual alignment: placing into bins below mean residual tightens the fleet.
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: fresh empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are terrible and item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if next_item_size > 0 { next_item_size > post_residual } else { false };
        if item_size > 60 && poor_fits {
            score -= 20.0 + 15.0 * progress; // late stream: consolidate less
        } else {
            score += 55.0; // default: discourage wasting a fresh bin
        }
    }

    // Stream-phase modulation: early on, keep bins flexible (penalize low post_residual slightly less),
    // late on, greedily fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome: apply a steep super-linear
    // penalty when post_residual lands in the "dead zone" (1..=15).
    if post_residual > 0 && post_residual <= 15 {
        score += 40.0 * (16.0 - post_residual as f64);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space is only truly wasted if no future item can use it.
    // If lookahead fits exactly into the gap, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead cannot use this gap -> gap is likely dead space.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // --- Tightness reward: the smaller the gap relative to item, the better ---
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 20.0 * tightness;

    // --- Open bins pressure ---
    // Penalize opening a new bin when existing bins already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // New bin only attractive if existing fits are poor (large dead space).
            let best_reason = if post_residual <= 15 { 30.0 } else { 0.0 };
            score += 15.0 + 5.0 * (fitting_bins_count as f64).sqrt() - best_reason;
        } else {
            // No alternative: opening a new bin is fine, slight reward.
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: more open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64 * if is_new_bin { 1.0 } else { -0.2 };

    // Late in the stream, avoid leaving many tiny fragmented bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual <= 15 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (low post_residual) but avoid tiny useless slivers
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // dead sliver unusable by any realistic item
    }

    // 2-step lookahead: reward when the next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: this bin becomes exactly right for next item
        } else {
            score += diff as f64 * 0.35;
            // partial credit if next item still fits after this placement
            if next_item_size <= post_residual {
                score -= 12.0;
            }
        }
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }
    // Many alternatives exist: mildly penalize this bin so best-fit wins
    if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // perfect 2-step chain and existing fits are poor.
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if perfect_chain {
            score -= 20.0;
        } else if fitting_bins_count > 0 {
            score += 55.0; // discourage abandoning usable open bins
        } else {
            score -= 30.0; // no alternative: new bin is fine
        }
    }

    // Early in the stream, be slightly more willing to open bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted residual nonlinearly (dead space grows quadratically in cost).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste * waste;

    // Reward tight fits strongly.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item can use the leftover space, reward this placement.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // perfect pairing
        } else if gap > 0 && gap <= 15 {
            score -= 10.0; // next item likely fits here afterwards
        } else if gap < 0 && (-gap) as u32 <= bin_capacity {
            score += (gap.abs() as f64) * 0.3; // leftover too small for next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // fits well (large item, few fitting bins) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let openness = (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.5;
        // Base penalty keeps new bins from being opened casually.
        score += 35.0;
        // But discount the penalty when item is big, nothing fits, or early stream.
        score -= 40.0 * pressure * tightness;
        score -= 20.0 * pressure * openness.min(1.0);
        // If item fits nothing else at all, new bin must win.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global state: many open bins with high mean residual → encourage consolidating
    // into existing bins rather than spreading items out.
    let consolidation = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= consolidation * (bin_residual as f64 / bin_capacity as f64) * 6.0;
        score += (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Slight preference for bins whose residual is close to the mean (keep residuals balanced),
    // except when the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * (1.0 - norm_pr));

    // Coupling with stream progress: late in the stream, residual waste matters more
    let progress_coupling = pr * progress * progress * (1.0 - progress);
    score += 2.0 * progress_coupling;

    // Penalize large post residuals relative to mean residual (dead-space risk)
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        score += 1.5 * ratio * ratio / (1.0 + ratio);
    }

    // Reward tight fits: quadratic bonus when post_residual is small
    let tightness = (cap - pr) / cap;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // Slight penalty for spreading across many bins when few remain open
    score += 0.1 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "usable" residue class are rewarded, dead-space classes are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class boundaries via integer division thresholds on post_residual.
    match pr / 10 {
        0 => score -= 40.0,                       // perfect / near-perfect fit
        1 => score -= 30.0,                       // 10..19: fits next small item
        2 => score -= 18.0,                       // 20..29: fits medium items
        3 => score -= 10.0,                       // 30..39
        4 => { /* 40..49 neutral */ }
        5 => score += 6.0,                        // half-full: wasteful
        6 => score += 12.0,
        7 => score += 18.0,
        8 => score += 24.0,
        _ => score += 30.0,                       // nearly untouched bin
    }

    // Modulo arithmetic: residual divisible by common item granularities
    // (10, 20, 25) is more likely reusable by future items.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic pair placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Fractional capacity coupling: how full the bin becomes.
    let fill = (bin_capacity - pr) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Progression: as the stream advances, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (fill - 0.5);

    // Mean residual context: if this bin's residual is below the mean,
    // it is a "tight" bin — prefer filling tight bins first.
    if mean_residual > 0.0 {
        score += 6.0 * ((prf - mean_residual) / cap);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            20.0 + 15.0 * (1.0 - (item_size as f64 / cap))
        };
        score += 55.0 + desperation - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can host the lookahead too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size is small but gaps that small waste capacity).
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 - (post_residual as f64) * 3.0; // worst at residual 1
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residual relative to capacity: mildly reward tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Open-bin pressure: prefer existing bins when many are open,
    // but allow new bins when few are open (early stream).
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize creating stranded space.
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin is a long-term investment.
    if bin_residual == bin_capacity {
        // Attractive early or when open bins have large mean residuals already.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * 0.9
            + progress * 30.0
            - mean_residual * 0.3
            + (open_bins_count as f64) * 2.0;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to bin capacity.
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: strongly reward bins whose post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let waste_after_next = post_residual - next_item_size;
            score -= 20.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportionally to the gap
            let gap = next_item_size - post_residual;
            score += 0.5 * gap as f64;
        }
    }

    // Penalize dead space relative to mean residual of open bins (fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless all fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.2 * open_bins_count as f64;
        // but if next item pairs perfectly with a fresh bin, soften slightly
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: reward if next item can fit into the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_ratio = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * chain_ratio;
    }
    // Penalize leaving residual that no plausible item (>=1, <= next size range) can use:
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score += 1.5 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    // Prefer bins whose residual is near the mean residual (keeps bin profile balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: empty bin should only win when current item is large
    // and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        // Base penalty so open bins usually win...
        score += 20.0;
        // ...unless the item is big and would leave awkward small residuals elsewhere.
        if size_frac > 0.6 {
            score -= 18.0 * (size_frac - 0.6) / 0.4;
        }
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 10.0 * progress;
        }
        // If many bins are open and none fit well, fresh bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty for very small post-residual dead space not filled exactly
    // (encourages exact fills over near-fills when both exist).
    if post_residual > 0 && post_residual < 3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: penalize large residuals more strongly as the stream progresses,
    // since late-stage placements should tighten packing.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress) * bin_capacity as f64;
    score += coupling;

    // Cubic smooth term: reward tight fits (small post_residual) increasingly over time.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * 8.0 * (0.3 + 0.7 * progress);

    // Dead-space penalty: residuals too small to ever fit typical items are wasted.
    let dead = if post_residual < item_size.min(80) { 6.0 * (1.0 - pr_norm) } else { 0.0 };
    score += dead;

    // Mean-residual deviation: prefer bins whose post-residual moves the average
    // residual profile toward compactness.
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * dev * bin_capacity as f64 * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 5.0 * fit_frac * (1.0 - pr_norm) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow into this bin, scaled by waste fraction.
        score += 3.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space classes: tiny leftovers (<10) are nearly useless.
    if post_residual < 10 {
        score -= 30.0; // reward near-perfect fill
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else if post_residual <= 50 {
        score += 10.0;
    } else {
        score += 18.0; // large residual = wasteful placement
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // granularities (10, 20, 25) are more reusable by future items.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }
    // Odd residuals are awkward; penalize slightly.
    if pr % 2 == 1 && pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: residual is reusable
            score -= (next_item_size as f64) * 0.3;
            // harmonic bonus if next item divides residual evenly
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: residual risk of dead space
            score += (next_item_size as f64 - pr as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer the tightest fit via post_residual (already), add mild spread
        score += 0.0;
    }

    // New-bin candidate handling: opening a new bin is only good if no open bin
    // offers a decent fit. Penalize the fresh empty bin, scaled by stream progress
    // and how many bins are already open.
    if bin_residual == bin_capacity {
        // base penalty: prefer existing bins when they give a reasonable fill
        score += 45.0;
        // early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // many open bins with large mean residual: don't open another
        score += (open_bins_count as f64).min(20.0) * 1.5;
        if mean_residual > 40.0 {
            score += 15.0;
        }
        // tiny items don't justify a fresh bin
        if item_size <= 25 {
            score += 20.0;
        }
        // large items (harmonic class > half capacity) pair poorly; a new bin is fine
        if item_size > 50 {
            score -= 15.0;
        }
        // lookahead: if next item is large and current item is small, new bin wasteful
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0;
        }
    }

    // Slight preference to fill bins with larger residual less when few bins open
    // (keep bins flexible), stronger consolidation when many bins open.
    score += frac * (open_bins_count as f64).min(15.0) * 2.0;

    // Integer-division threshold: residual in [item_size, 2*item_size) is a
    // "one more same-item" slot — valuable.
    if item_size > 0 && pr >= item_size && pr < 2 * item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Perfect fit bonus: strongly reward leaving zero or near-zero residual.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Tight fit: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Reward using a bin whose residual closely matches the item (best-fit coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor it to avoid
    // opening a new bin for a single item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit: leftover is likely dead space for the lookahead.
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins with residual below the mean (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no open
    // bin offers a decent fit, or when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 }
            else if item_size >= 70 { 10.0 }
            else { 45.0 + (fitting_bins_count as f64) * 5.0 };
        score += desperation;
        // A fresh bin leaves a large residual; mild penalty scaled by stream progress.
        score += (step_index as f64 / (total_items as f64).max(1.0)) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills leftover
        if gap < 0.5 {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to tightness of chain
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize dead space that's too small for future items
            score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
    }

    // Progress-based mild conservatism early: keep bins flexible early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * dead * dead * 100.0;

    // Lookahead: bonus if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where this item is a near-perfect fit.
        score += 2.0 * (fitting_bins_count as f64).sqrt() * (1.0 - fit_ratio);
    }

    // Prefer fuller bins when mean residual is high (fragmentation pressure).
    if mean_residual > 0.0 {
        let fullness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness * (mean_residual / bin_capacity as f64);
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize mildly so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, waste matters less; later, dead space is heavily penalized.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * (1.0 + 2.0 * progress * progress);
    score += 40.0 * coupling * coupling;

    // Reward filling the bin tightly (quadratic bonus for small post_residual).
    score -= 60.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Perfect fit reward: cubic decay of post_residual.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Favor bins whose residual is already below average (more "used up").
    score -= 10.0 * (mean_residual - pr).tanh();

    // Lookahead: if the next item fits exactly in the post residual, reward; penalize if it nearly fits and we'd strand space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0 * ((nxt - pr) / bin_capacity as f64);
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Mild bonus for using an existing bin vs. a fresh one (fresh bin has bin_residual == bin_capacity,
    // so its high post_residual already penalizes it; add explicit inertia).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are penalized (dead space), large usable
    // residues are rewarded.
    let pr = post_residual;
    let cls = pr / 10; // integer-division class: 0..10
    score += match cls {
        0 => 0.0,                       // near-perfect fit
        1 => 4.0,                       // 10-19 leftover: hard to reuse
        2 => 9.0,                       // 20-29 leftover
        3 => 12.0,
        4 => 10.0,                      // 40s: reusable by mid items
        5 => 6.0,
        6 => 2.0,                       // 60s: very reusable
        _ => 0.0,
    };

    // Modulo-10 harmonic coupling: leftover that is a multiple of 10 is
    // more likely reusable by typical item granularities.
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nres = pr - next_item_size;
            // harmonic penalty on the residual after the lookahead item
            score += (nres as f64) * 0.35;
            if nres % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here either way; slight reward for
            // leaving a bigger general-purpose gap
            score -= (pr as f64) * 0.05;
        }
    } else {
        // last item: just fill as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (item_size as f64) * 0.05;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but reward it if all open residuals are small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = cap - 15.0 * fragmentation - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation early).
    score += (open_bins_count as f64).sqrt() * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1)
    // but practically, gaps below ~10 waste capacity; gaps that cannot fit
    // the lookahead item are also dead.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // gap can't fit the next item
        } else {
            score -= 6.0; // gap remains usable
        }
    } else {
        score -= 20.0; // perfect fit: fully closed bin is excellent
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless
    // this placement closes a bin or the bin is the only option.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; only prefer it when open bins
    // have large mean residual (poor fits elsewhere) or many bins are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * mean_residual;
    }

    // Coupling: prefer bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * snug * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64)) * (gap / bin_capacity as f64).exp();
        // perfect chain bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // penalize leaving residual smaller than the smallest possible next item
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // relative to mean residual: avoid creating outliers of dead space
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // new-bin candidate: only attractive when item is large / no good fit exists
    if bin_residual == bin_capacity {
        score = item_size as f64 * 0.5 + 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // mild waste penalty scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual too small for next item: mild penalty scaled by dead fraction.
        score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: when many bins are open, prefer consolidation (lower residual waste).
    let crowding = (open_bins_count as f64).ln().max(1.0);
    score += 2.0 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual deviates favorably from mean, reward.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Time horizon: early in stream, be pickier (avoid small leftovers); late, just fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * (1.0 - progress) + 3.0 * crowding;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // next item may pair better in a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 45.0; // no viable open bin: open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // tight fits (small post_residual) are increasingly valuable later in the stream.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm); // in [0,1], high for tight fits
    score -= 12.0 * tightness * (0.5 + progress);

    // Quadratic penalty for large leftover space (dead space), amplified mid/late stream
    score += 0.35 * pr_norm * pr_norm * (1.0 + 2.0 * progress) * cap;

    // Cubic interaction: prefer residuals that exactly match the next item's needs
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        // reward when next item fits exactly into the post-residual
        if pr >= nx {
            score -= 10.0 * (1.0 - 4.0 * diff * diff) * (0.4 + progress);
        } else {
            // penalize when next item cannot use this bin's leftover
            score += 6.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.6 + progress);
    }

    // Penalize spreading across many open bins mildly; encourage consolidation
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // New-bin candidate handling: empty bin should only win when no open bin is decent
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decreasing as stream progresses
        score = cap * (0.9 - 0.35 * progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // forced: no open bin fits
        } else {
            // discourage opening a new bin if existing bins fit reasonably well
            let mean_fit = mean_residual / cap;
            score += 18.0 * (1.0 - mean_fit.abs()) * (0.5 + progress);
        }
    }

    // Mild attraction toward bins with residual close to the mean (balanced packing)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Harmonic class of post_residual: residues that are "useful" sizes (multiples
    // of common item granularities) are more valuable to keep than dead space.
    let pr = post_residual as i64;
    let mut residue_bonus = 0.0;
    if pr > 0 {
        // Class A: divisible by 10 (canonical item sizes) -> very reusable.
        if pr % 10 == 0 {
            residue_bonus -= 18.0;
            // Perfect small slots that typical items can fill exactly.
            if pr <= 20 { residue_bonus -= 12.0; }
            else if pr >= 40 && pr <= 90 { residue_bonus -= 6.0; }
        }
        // Class B: divisible by 5 -> moderately reusable.
        else if pr % 5 == 0 {
            residue_bonus -= 8.0;
        }
        // Class C: prime or near-prime residues are dead space.
        else {
            let mut is_prime = pr > 2;
            let mut d = 2i64;
            while d * d <= pr {
                if pr % d == 0 { is_prime = false; break; }
                d += 1;
            }
            if is_prime { residue_bonus += 10.0; }
            else {
                // Odd non-multiples of 5: half-dead.
                if pr % 2 == 1 { residue_bonus += 5.0; }
                else { residue_bonus += 2.0; }
            }
        }
        // Integer-division threshold: post_residual in [1..=9] is nearly dead.
        if pr / 10 == 0 { residue_bonus += 15.0; }
    }
    score += residue_bonus;

    // Lookahead coupling: if the next item exactly fills this bin's post_residual,
    // strongly reward; if next item cannot fit here, the leftover is wasted.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // Fraction of next item covered by this residual: harmonic coupling.
            let cover = (next_item_size as f64) / (post_residual as f64);
            score -= 25.0 * cover;
            // If next item leaves another canonical residue, extra reward.
            if (post_residual - next_item_size) % 10 == 0 { score -= 8.0; }
        } else {
            // Next item can't use this bin's leftover: penalize proportionally.
            score += 10.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if post_residual <= 5 { score -= 10.0; }
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only when all
    // open bins have bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * tightness;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If mean residual across open bins is small, new bin is attractive.
        score -= (mean_residual / 10.0).min(15.0);
        // Large items (>= half capacity) justify a fresh bin.
        if item_size >= bin_capacity / 2 { score -= 15.0; }
    }

    // Mild penalty for proliferating bins when this bin is a poor fit anyway.
    score += 0.5 * (open_bins_count as f64).sqrt() * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small, hard-to-fill leftovers) get super-linear penalties.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            // Tiny gap: nearly unusable for any item (min size 1..100, but
            // small gaps waste capacity) -> heavy quadratic penalty.
            score += 40.0 + (10.0 - pr) * (10.0 - pr) * 2.0;
        } else if pr < 25.0 {
            // Medium-small dead zone: penalize proportionally more.
            score += 20.0 + (25.0 - pr) * 1.5;
        } else if pr > 60.0 {
            // Large leftover is fine (still reusable) -> mild reward.
            score -= 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize opening new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by current open-bin pressure.
        score += 25.0 + pressure * 3.0;
    } else {
        // Existing bin: reward slightly more when pressure is high.
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // reward this placement; if post_residual can't fit next item but is
    // close, add a small dead-space penalty.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr && pr - ni <= 5.0 {
            score -= 25.0; // next item nearly fills the leftover
        } else if ni > pr && pr > 0.0 && pr < ni {
            score += 8.0; // leftover likely stranded relative to lookahead
        }
    }

    // Mean-residual coupling: placing into a bin below-average residual
    // (i.e., fuller than average) is preferred to consolidate fullness.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3; // bin_residual < mean -> dev > 0 -> lower score
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill ratio of this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill * fill;

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is a perfect chain — heavily reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 25.0;
        } else if nxt <= post {
            // Next item still fits: reward proportional to how well it fills.
            score -= 8.0 * (nxt / post.max(1.0));
        } else {
            // Next item won't fit: penalize leftover dead space beyond next item.
            let dead = post - nxt.min(post);
            score += 0.15 * dead;
            // Extra penalty if post-residual is small but unusable for next item.
            if post < nxt {
                score += 4.0 * (1.0 - post / nxt);
            }
        }
    } else {
        // Last item: pure best-fit on post_residual (already the base score).
    }

    // Compare against mean residual across open bins: placing into a bin
    // with residual far below mean wastes a scarce large slot; prefer bins
    // with residual near/above mean when the fit is loose.
    let res = bin_residual as f64;
    if res > mean_residual + 10.0 && fill < 0.5 {
        score += 2.0; // discourage squandering a roomy bin on a small item
    } else if res < mean_residual - 5.0 && fill > 0.6 {
        score -= 3.0; // encourage consuming nearly-full bins
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it attractive only when no open bin offers
    // a genuinely good fit. Its post_residual is large, so make it mildly
    // unattractive unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score += 6.0 - 8.0 * item_ratio;
        // If next item is large, a fresh bin may serve the pair better.
        if next_item_size >= 60 && item_size >= 50 {
            score -= 10.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.05 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Reward bins whose residual can still host the next item.
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many bins when residuals are already small.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.4 * (0.5 + progress);
    }

    // Coupling with global mean residual: prefer bins close to the mean
    // (keeps residual distribution balanced) early; prefer tightest fit late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1 * (1.0 - progress);

    // New-bin candidate logic: opening a fresh bin is attractive only when
    // no open bin fits well (post_residual large relative to item) or
    // item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / (bin_capacity as f64) } else { 0.0 };
        let poor_fit = (post_residual as f64) > 40.0;
        if poor_fit || (fitting_bins_count == 0) {
            score -= 15.0 + fragmentation * 20.0;
        } else {
            // Discourage opening a new bin when a decent fit exists.
            score += 10.0 + (fitting_bins_count as f64) * 2.0;
        }
        // Late in stream, opening bins is fine (no future to protect).
        if progress > 0.8 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let fit_norm = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };

    // Base: waste created, scaled by stream progress (later => more waste-averse)
    let mut score = pr * (0.5 + 1.5 * progress);

    // Non-linear coupling: small post-residuals are good (tight fit), large ones bad
    let tight = 1.0 - pr_norm;
    score -= 40.0 * tight * tight * (1.0 + progress);

    // Penalize unusable dead space: post_residual too small for typical future items
    let dead = (1.0 - (pr / 80.0)).max(0.0);
    score += 25.0 * dead * dead * (0.5 + 0.5 * progress);

    // Scarcity bonus: last fitting bin should be favored
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }
    score -= 15.0 * (1.0 - fit_norm);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (balance), smooth quadratic in mean deviation
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                       // perfect fit — best possible
        1..=5 => 0.0,                   // nearly perfect
        6..=20 => 2.0,                  // awkward small gap
        21..=49 => 1.0,                 // medium gap, still usable
        _ => 3.0,                       // large gap (half-bin waste)
    };
    score += class * (bin_capacity as f64) * 0.05;

    // Reward tight fits non-linearly
    let tightness = 1.0 - (pr as f64) / (bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Modulo arithmetic on post_residual: gaps that are multiples of common
    // item size classes (10/20/25) are re-usable by future items.
    let harmonic = ((pr % 10 == 0) as i32 + (pr % 20 == 0) as i32 + (pr % 25 == 0) as i32) as f64;
    score -= harmonic * 6.0;

    // Integer division thresholds: can the next item land in the gap?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits here: strong reward, scaled by how well it fits
            let look_gap = pr - next_item_size;
            score -= 15.0 + (1.0 - look_gap as f64 / bin_capacity as f64) * 10.0;
        } else {
            // gap too small for lookahead: penalize proportional to overshoot
            let overshoot = next_item_size - pr;
            score += (overshoot as f64).min(30.0) * 0.4;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // prefer new bins early in stream or when mean residual is fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 12.0; // existing bins too fragmented, open fresh
        }
        // don't open a new bin if plenty of bins fit the item
        score += fitting_bins_count as f64 * 3.0;
    }

    // Slight penalty for bin crowding: spread load when many bins open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are extremely desirable.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 60.0;

    // Reward using bins with small residuals (best-fit flavor).
    score += bin_residual as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 3.0;

    // Prefer bins whose residual deviates below the mean (consolidate fullness).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Lookahead: bonus if post_residual can host the next item (keep bins usable).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is dead space for the next item.
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.8;
    }

    // New-bin candidate: baseline moderate score; only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 120.0
            + open_bins_count as f64 * 2.0
            - (if next_item_size > 0 && item_size >= next_item_size { 10.0 } else { 0.0 });
        // If this bin is the only fitting bin, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: quadratic reward for small leftover space.
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) * 0.35;
    score += pr * pr / (bin_capacity as f64 * 1.7);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_tightness = (post_residual - next_item_size) as f64;
        score -= 12.0 - pair_tightness * 0.12;
    }
    // Penalize bins that leave a sliver the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += waste * 0.55;
    }

    // Last-chance rescue: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is small
    // relative to capacity and open bins are fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let openness = (item_size as f64 / bin_capacity as f64).powf(1.5);
        score += 40.0; // base cost of consuming fresh capacity
        score -= openness * 30.0 * (0.5 + fragmentation);
        score -= t * 8.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0 * openness;
        }
    } else {
        // Slight preference toward fuller bins to consolidate waste.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 6.0;
        // Mild penalty for spreading across too many open bins.
        score += (open_bins_count as f64).ln() * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;
    let next = next_item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * t) - norm_pr * (2.0 - t) + 0.5 * t * t;
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tight * (1.0 + t);

    // Penalize wasted residual relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual) * (1.0 + t * t);

    // Lookahead: reward residual that can host the next item
    if next > 0.0 && next <= pr {
        score -= 15.0 * (next / cap) * (1.0 - t) + 10.0 * (next / cap) * t;
    } else if next > pr {
        score += 8.0 * ((next - pr) / cap) * (1.0 - t);
    }

    // Last-chance bin pressure: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t) + 10.0;
    }
    score -= 2.0 * (fit - 1.0).max(0.0);

    // Mild preference for consolidating into fewer bins
    score += 0.5 * open * t;

    // Slight penalty for large leftover dead space (quadratic in normalized residual)
    score += 20.0 * norm_pr * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential decay of wasted space
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual (modulo 10 buckets): small dead zones
    // that can host common small items (1..=10) are less harmful.
    let dead_class = post_residual % 10;
    if post_residual > 0 && post_residual <= 10 {
        score -= 25.0; // residual usable by any small item
    } else if dead_class == 0 {
        score -= 8.0; // multiple-of-10 residuals pair well with decile items
    } else if dead_class > 5 {
        score -= 3.0; // moderately reusable
    } else {
        score += 5.0 * (6 - dead_class) as f64; // awkward dead space
    }

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 20.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // residual likely dead if nothing small can follow
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in stream
    // and when many bins are open with room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 40.0 * (1.0 - progress);
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0 * (open_bins_count as f64).sqrt();
        }
        // still allow new bin if no open bin gives a decent fit
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Prefer bins with below-average residual (consolidate emptiness)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Mild preference for larger residual bins when item is large
    if item_size > 50 {
        score -= 0.1 * bin_residual as f64;
    }

    // Integer-division threshold on post_residual: quarter-capacity boundaries
    let quarter = bin_capacity / 4;
    if post_residual >= quarter && post_residual < 2 * quarter {
        score -= 6.0; // quarter-sized residual is a useful harmonic slot
    } else if post_residual >= 2 * quarter && post_residual < 3 * quarter {
        score -= 10.0; // half-capacity residual is very flexible
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // plausible follow-up item are worthless. Penalize unusable gaps hard.
    let dead_threshold = 10u32; // below this, nothing from a 1..100 stream reliably fits
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect closure is ideal: reward it strongly.
        score -= 120.0;
    }

    // Tight-fit reward: the smaller the post_residual relative to capacity, the better,
    // but only when the gap remains usable (post_residual >= dead_threshold).
    if post_residual >= dead_threshold {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        // Extra reward if the next item also fits in the resulting residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins with slack means we should consolidate.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits perfectly into the post residual,
    // strongly favor this bin; if the next item would be blocked by a small gap,
    // penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next < dead_threshold {
                score -= 15.0; // chain closes nearly perfectly
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // gap blocks the lookahead item
        }
    }

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it is already "dense"; encourage filling dense bins first.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 3.0 * residual_gap.min(50.0);
    }

    // New-bin candidate handling: an empty bin gets a baseline score so that
    // it only wins when existing bins would produce bad fits.
    if bin_residual == bin_capacity {
        score = 55.0
            + 4.0 * open_pressure
            - if next_item_size > 0 && item_size >= next_item_size { 5.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item also fits here: excellent chaining, reward proportionally.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.4;
        } else {
            // Dead space for the next item: penalize unusable leftover.
            let dead = post_residual as f64;
            score += dead * 0.5;
            // Especially bad if leftover is small but unusable (< min plausible item).
            if post_residual < 10 {
                score += 40.0;
            }
        }
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current fits are poor
    // and the item would leave a big awkward residual in existing bins.
    if bin_residual == bin_capacity {
        let best_alternative_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 0.0 };
        let _ = best_alternative_penalty;
        let waste_elsewhere = if fitting_bins_count > 0 {
            // approximate waste if placed in an existing bin: residual - item
            (bin_capacity - item_size) as f64
        } else {
            0.0
        };
        score = 150.0 + waste_elsewhere * 0.2;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
        // Many open bins: discourage adding more.
        score += open_bins_count as f64 * 5.0;
    }

    score
}
